  static EdgeInsets get adaptiveButtonPadding => PlatformConfig.useCupertino
      ? const EdgeInsets.symmetric(horizontal: 16, vertical: 12)
      : const EdgeInsets.symmetric(horizontal: 24, vertical: 16);

