import 'dart:io';
import 'package:flutter_image_compress/flutter_image_compress.dart';
import 'package:path_provider/path_provider.dart';
import '../utils/logger.dart';

class ImageCompressionHelper {
  /// Compress image before uploading to Firebase Storage
  /// Returns compressed file path
  ///
  /// 🔥 FIXED: Now intelligently decides whether to compress
  static Future<File?> compressImage(
      File file, {
        int quality = 85,
        int maxWidth = 1920,
        int maxHeight = 1080,
      }) async {
    try {
      final originalSize = await file.length();

      log.d('🖼️ Compressing image: ${file.path}');
      log.d('📏 Original size: ${_formatBytes(originalSize)}');

      // 🔥 SKIP COMPRESSION IF FILE IS ALREADY SMALL (< 200KB)
      if (originalSize < 200 * 1024) {
        log.i('✅ Image already small (${_formatBytes(originalSize)}), skipping compression');
        return file;
      }

      // 🔥 CREATE TEMP FILE
      final dir = await getTemporaryDirectory();
      final targetPath = '${dir.path}/compressed_${DateTime.now().millisecondsSinceEpoch}.jpg';

      // 🔥 COMPRESS WITH OPTIMIZED SETTINGS
      final result = await FlutterImageCompress.compressAndGetFile(
        file.absolute.path,
        targetPath,
        quality: quality,
        minWidth: maxWidth,
        minHeight: maxHeight,
        format: CompressFormat.jpeg,
        keepExif: false, // 🔥 REMOVE METADATA TO SAVE SPACE
      );

      if (result == null) {
        log.e('❌ Image compression failed, using original');
        return file;
      }

      final compressedFile = File(result.path);
      final compressedSize = await compressedFile.length();

      log.d('📦 Compressed size: ${_formatBytes(compressedSize)}');

      // 🔥 ONLY USE COMPRESSED VERSION IF IT'S ACTUALLY SMALLER
      if (compressedSize < originalSize) {
        final savedBytes = originalSize - compressedSize;
        final savedPercent = ((savedBytes / originalSize) * 100).toStringAsFixed(1);
        log.i('✅ Compression successful: Saved ${_formatBytes(savedBytes)} ($savedPercent%)');
        return compressedFile;
      } else {
        log.i('⚠️ Compressed size ($compressedSize bytes) >= original ($originalSize bytes), using original');

        // 🔥 DELETE THE COMPRESSED FILE TO FREE SPACE
        try {
          await compressedFile.delete();
        } catch (e) {
          log.w('Could not delete temporary compressed file: $e');
        }

        return file;
      }
    } catch (e, s) {
      log.e('❌ Error compressing image', error: e, stackTrace: s);
      return file; // 🔥 RETURN ORIGINAL ON ERROR
    }
  }

  /// Compress for profile pictures (smaller size needed)
  /// 🔥 OPTIMIZED SETTINGS
  static Future<File?> compressProfilePicture(File file) async {
    return compressImage(
      file,
      quality: 80, // 🔥 REDUCED FROM 80
      maxWidth: 500,
      maxHeight: 500,
    );
  }

  /// Compress for salon gallery (higher quality)
  /// 🔥 OPTIMIZED SETTINGS
  static Future<File?> compressSalonPhoto(File file) async {
    return compressImage(
      file,
      quality: 85,
      maxWidth: 1920,
      maxHeight: 1080,
    );
  }

  /// 🔥 NEW: Compress for promotions (balance of quality and size)
  static Future<File?> compressPromotionImage(File file) async {
    return compressImage(
      file,
      quality: 85,
      maxWidth: 1200,
      maxHeight: 800,
    );
  }

  /// 🔥 NEW: Helper to format bytes into human-readable format
  static String _formatBytes(int bytes) {
    if (bytes < 1024) return '$bytes B';
    if (bytes < 1024 * 1024) return '${(bytes / 1024).toStringAsFixed(1)} KB';
    return '${(bytes / (1024 * 1024)).toStringAsFixed(2)} MB';
  }

  /// 🔥 NEW: Aggressive compression for very large images
  static Future<File?> compressAggressively(File file) async {
    try {
      final originalSize = await file.length();

      log.d('🖼️ Aggressive compression for: ${file.path}');
      log.d('📏 Original size: ${_formatBytes(originalSize)}');

      final dir = await getTemporaryDirectory();
      final targetPath = '${dir.path}/compressed_aggressive_${DateTime.now().millisecondsSinceEpoch}.jpg';

      // 🔥 MULTIPLE PASS COMPRESSION FOR LARGE FILES
      File currentFile = file;
      int currentQuality = 85;
      int attempts = 0;
      const maxAttempts = 3;
      const targetSize = 500 * 1024; // 500KB target

      while (attempts < maxAttempts && await currentFile.length() > targetSize) {
        final result = await FlutterImageCompress.compressAndGetFile(
          currentFile.absolute.path,
          '${targetPath}_$attempts.jpg',
          quality: currentQuality,
          minWidth: 1200,
          minHeight: 800,
          format: CompressFormat.jpeg,
          keepExif: false,
        );

        if (result == null) break;

        final newFile = File(result.path);
        final newSize = await newFile.length();

        log.d('🔄 Attempt ${attempts + 1}: ${_formatBytes(newSize)} (quality: $currentQuality)');

        // 🔥 DELETE PREVIOUS ATTEMPT IF NOT THE ORIGINAL
        if (currentFile != file && await currentFile.exists()) {
          await currentFile.delete();
        }

        currentFile = newFile;
        currentQuality = (currentQuality * 0.85).round(); // Reduce quality by 15%
        attempts++;
      }

      final finalSize = await currentFile.length();

      if (finalSize < originalSize) {
        log.i('✅ Aggressive compression: ${_formatBytes(originalSize)} → ${_formatBytes(finalSize)}');
        return currentFile;
      } else {
        // Clean up
        if (currentFile != file && await currentFile.exists()) {
          await currentFile.delete();
        }
        return file;
      }
    } catch (e, s) {
      log.e('❌ Error in aggressive compression', error: e, stackTrace: s);
      return file;
    }
  }
}

import 'package:package_info_plus/package_info_plus.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import '../utils/logger.dart';

class VersionCheckerService {
  final FirebaseFirestore _db = FirebaseFirestore.instance;

  /// Check if app needs update
  /// Store required version in Firestore: config/app_version
  Future<AppVersionStatus> checkVersion() async {
    try {
      final packageInfo = await PackageInfo.fromPlatform();
      final currentVersion = packageInfo.version;

      // Get required version from Firestore
      final doc = await _db.collection('config').doc('app_version').get();

      if (!doc.exists) {
        log.w('App version config not found in Firestore');
        return AppVersionStatus.upToDate;
      }

      final data = doc.data()!;
      final minRequiredVersion = data['minRequiredVersion'] as String;
      final latestVersion = data['latestVersion'] as String;

      if (_compareVersions(currentVersion, minRequiredVersion) < 0) {
        return AppVersionStatus.updateRequired;
      } else if (_compareVersions(currentVersion, latestVersion) < 0) {
        return AppVersionStatus.updateAvailable;
      }

      return AppVersionStatus.upToDate;
    } catch (e, s) {
      log.e('Error checking app version', error: e, stackTrace: s);
      return AppVersionStatus.upToDate; // Don't block user on error
    }
  }

  /// Compare version strings (e.g., "1.2.3" vs "1.2.4")
  int _compareVersions(String v1, String v2) {
    final parts1 = v1.split('.').map(int.parse).toList();
    final parts2 = v2.split('.').map(int.parse).toList();

    for (int i = 0; i < 3; i++) {
      final p1 = i < parts1.length ? parts1[i] : 0;
      final p2 = i < parts2.length ? parts2[i] : 0;

      if (p1 < p2) return -1;
      if (p1 > p2) return 1;
    }

    return 0;
  }
}

enum AppVersionStatus {
  upToDate,
  updateAvailable, // Show banner
  updateRequired,  // Block app
}

// Firestore structure:
// config/app_version:
// {
//   "latestVersion": "1.2.0",
//   "minRequiredVersion": "1.1.0",
//   "releaseNotes": "Bug fixes and improvements"
// }

import 'dart:io';
import 'dart:typed_data';
import 'package:flutter/foundation.dart';
import 'package:video_compress/video_compress.dart';
import 'package:path_provider/path_provider.dart';
import 'package:path/path.dart' as path;

/// Helper class for video compression and thumbnail generation
/// 
/// Features:
/// - Compresses videos for faster upload/playback
/// - Auto-generates thumbnail from first frame
/// - Validates duration (max 60 seconds)
/// - Returns compressed video + thumbnail paths
class VideoCompressionHelper {
  /// Maximum allowed video duration in seconds
  static const int maxDurationSeconds = 60;

  /// Maximum file size after compression (10MB)
  static const int maxFileSizeBytes = 10 * 1024 * 1024;

  /// Result of video processing
  static Future<VideoProcessingResult?> processVideo(File videoFile) async {
    try {
      // 1. Get video info first
      final info = await VideoCompress.getMediaInfo(videoFile.path);

      if (info.duration == null) {
        debugPrint('VideoCompressionHelper: Could not get video duration');
        return null;
      }

      final durationSeconds = (info.duration! / 1000).round();
      debugPrint('VideoCompressionHelper: Video duration = $durationSeconds seconds');

      // 2. Validate duration
      if (durationSeconds > maxDurationSeconds) {
        debugPrint('VideoCompressionHelper: Video too long ($durationSeconds > $maxDurationSeconds)');
        return VideoProcessingResult(
          success: false,
          errorMessage: 'Video must be 60 seconds or less. Your video is $durationSeconds seconds.',
        );
      }

      // 3. Generate thumbnail from first frame
      debugPrint('VideoCompressionHelper: Generating thumbnail...');
      final thumbnailFile = await VideoCompress.getFileThumbnail(
        videoFile.path,
        quality: 75,
        position: 0, // First frame
      );

      if (thumbnailFile == null) {
        debugPrint('VideoCompressionHelper: Failed to generate thumbnail');
        return VideoProcessingResult(
          success: false,
          errorMessage: 'Failed to generate video thumbnail',
        );
      }

      debugPrint('VideoCompressionHelper: Thumbnail generated at ${thumbnailFile.path}');

      // 4. Compress video
      debugPrint('VideoCompressionHelper: Compressing video...');
      final compressedInfo = await VideoCompress.compressVideo(
        videoFile.path,
        quality: VideoQuality.MediumQuality,
        deleteOrigin: false,
        includeAudio: true,
      );

      if (compressedInfo == null || compressedInfo.file == null) {
        debugPrint('VideoCompressionHelper: Compression failed');
        return VideoProcessingResult(
          success: false,
          errorMessage: 'Failed to compress video',
        );
      }

      final compressedFile = compressedInfo.file!;
      final originalSize = videoFile.lengthSync();
      final compressedSize = compressedFile.lengthSync();
      final compressionRatio = ((1 - compressedSize / originalSize) * 100).toStringAsFixed(1);

      debugPrint('VideoCompressionHelper: Compression complete');
      debugPrint('  Original: ${_formatBytes(originalSize)}');
      debugPrint('  Compressed: ${_formatBytes(compressedSize)}');
      debugPrint('  Reduction: $compressionRatio%');

      // 5. Check if still too large
      if (compressedSize > maxFileSizeBytes) {
        debugPrint('VideoCompressionHelper: Compressed file still too large');
        return VideoProcessingResult(
          success: false,
          errorMessage: 'Video file is too large. Please use a shorter video.',
        );
      }

      return VideoProcessingResult(
        success: true,
        compressedVideoFile: compressedFile,
        thumbnailFile: thumbnailFile,
        durationSeconds: durationSeconds,
        originalSizeBytes: originalSize,
        compressedSizeBytes: compressedSize,
      );

    } catch (e, stackTrace) {
      debugPrint('VideoCompressionHelper: Error processing video: $e');
      debugPrint('Stack trace: $stackTrace');
      return VideoProcessingResult(
        success: false,
        errorMessage: 'Error processing video: ${e.toString()}',
      );
    }
  }

  /// Get video duration without full processing
  static Future<int?> getVideoDuration(File videoFile) async {
    try {
      final info = await VideoCompress.getMediaInfo(videoFile.path);
      if (info.duration == null) return null;
      return (info.duration! / 1000).round();
    } catch (e) {
      debugPrint('VideoCompressionHelper: Error getting duration: $e');
      return null;
    }
  }

  /// Generate thumbnail only (for preview before upload)
  static Future<File?> generateThumbnail(File videoFile, {int position = 0}) async {
    try {
      return await VideoCompress.getFileThumbnail(
        videoFile.path,
        quality: 75,
        position: position,
      );
    } catch (e) {
      debugPrint('VideoCompressionHelper: Error generating thumbnail: $e');
      return null;
    }
  }

  /// Cancel ongoing compression
  static Future<void> cancelCompression() async {
    await VideoCompress.cancelCompression();
  }

  /// Delete all temporary files created during compression
  static Future<void> deleteAllCache() async {
    await VideoCompress.deleteAllCache();
  }

  /// Format bytes to human readable string
  static String _formatBytes(int bytes) {
    if (bytes < 1024) return '$bytes B';
    if (bytes < 1024 * 1024) return '${(bytes / 1024).toStringAsFixed(1)} KB';
    return '${(bytes / (1024 * 1024)).toStringAsFixed(2)} MB';
  }
}

/// Result of video processing operation
class VideoProcessingResult {
  final bool success;
  final File? compressedVideoFile;
  final File? thumbnailFile;
  final int? durationSeconds;
  final int? originalSizeBytes;
  final int? compressedSizeBytes;
  final String? errorMessage;

  const VideoProcessingResult({
    required this.success,
    this.compressedVideoFile,
    this.thumbnailFile,
    this.durationSeconds,
    this.originalSizeBytes,
    this.compressedSizeBytes,
    this.errorMessage,
  });

  /// Get compression ratio as percentage
  double? get compressionRatio {
    if (originalSizeBytes == null || compressedSizeBytes == null) return null;
    return (1 - compressedSizeBytes! / originalSizeBytes!) * 100;
  }

  /// Get formatted original size
  String get formattedOriginalSize {
    if (originalSizeBytes == null) return 'Unknown';
    return _formatBytes(originalSizeBytes!);
  }

  /// Get formatted compressed size
  String get formattedCompressedSize {
    if (compressedSizeBytes == null) return 'Unknown';
    return _formatBytes(compressedSizeBytes!);
  }

  static String _formatBytes(int bytes) {
    if (bytes < 1024) return '$bytes B';
    if (bytes < 1024 * 1024) return '${(bytes / 1024).toStringAsFixed(1)} KB';
    return '${(bytes / (1024 * 1024)).toStringAsFixed(2)} MB';
  }
}

