import 'guest_session_tracker.dart';
import '../utils/logger.dart';

/// Service to intelligently manage when and how to show auth prompts to guests.
///
/// This service uses behavioral triggers and timing logic to:
/// - Show prompts at optimal moments (not annoying)
/// - Respect user dismissals
/// - Vary prompt types based on context
/// - Track conversion opportunities
///
/// Strategy: Progressive engagement
/// - Start gentle (banners, cards)
/// - Increase urgency as engagement grows
/// - Respect "Not Now" decisions
class GuestPromptService {
  final GuestSessionTracker _sessionTracker;

  // Configuration constants
  static const int _minMinutesBetweenPrompts = 2;
  static const int _maxPromptsPerSession = 4;
  static const int _salonsBeforePrompt = 3;
  static const int _minutesBeforeTimePrompt = 2;
  static const int _dismissBeforeBackoff = 2;

  GuestPromptService(this._sessionTracker);

  // ============================================================================
  // PROMPT ELIGIBILITY CHECKS
  // ============================================================================

  /// Master check: Should we show ANY prompt right now?
  bool shouldShowPrompt() {
    // 1. Don't show if user dismissed too many times
    if (_sessionTracker.getPromptDismissCount() >= _dismissBeforeBackoff) {
      log.d('Prompt blocked: User dismissed too many times');
      return false;
    }

    // 2. Don't show if we've hit max prompts for this session
    final promptCount = _getEstimatedPromptsShown();
    if (promptCount >= _maxPromptsPerSession) {
      log.d('Prompt blocked: Max prompts reached for session');
      return false;
    }

    // 3. Don't show if not enough time since last prompt
    final minutesSinceLast = _sessionTracker.getMinutesSinceLastPrompt();
    if (minutesSinceLast != null && minutesSinceLast < _minMinutesBetweenPrompts) {
      log.d('Prompt blocked: Too soon since last prompt');
      return false;
    }

    return true;
  }

  /// Estimate prompts shown (since we don't track each type separately)
  int _getEstimatedPromptsShown() {
    // Rough estimate based on dismissals + time
    final dismissals = _sessionTracker.getPromptDismissCount();
    final lastPrompt = _sessionTracker.getLastPromptTimestamp();

    if (lastPrompt != null) {
      return dismissals + 1; // At least one was shown
    }
    return dismissals;
  }

  // ============================================================================
  // TRIGGER-BASED PROMPT CHECKS
  // ============================================================================

  /// Check if we should show prompt after browsing X salons
  PromptTrigger? checkBrowsingTrigger() {
    if (!shouldShowPrompt()) return null;

    final salonsViewed = _sessionTracker.salonsViewedCount;

    if (salonsViewed >= _salonsBeforePrompt) {
      log.i('Browsing trigger activated: $salonsViewed salons viewed');
      return PromptTrigger(
        type: PromptType.banner,
        reason: 'browsing_engagement',
        priority: PromptPriority.low,
        message: 'Save your favorite salons! Create an account to access them anywhere.',
      );
    }

    return null;
  }

  /// Check if we should show prompt after time spent
  PromptTrigger? checkTimeTrigger() {
    if (!shouldShowPrompt()) return null;

    final minutes = _sessionTracker.getSessionDurationMinutes();

    if (minutes >= _minutesBeforeTimePrompt) {
      log.i('Time trigger activated: $minutes minutes spent');
      return PromptTrigger(
        type: PromptType.bottomSheet,
        reason: 'time_engagement',
        priority: PromptPriority.medium,
        message: 'Enjoying Pendeza? Create an account for personalized recommendations!',
      );
    }

    return null;
  }

  /// Check if we should show prompt after favorite attempt
  PromptTrigger? checkFavoriteTrigger() {
    if (!shouldShowPrompt()) return null;

    final attempts = _sessionTracker.favoriteAttemptsCount;

    if (attempts > 0) {
      log.i('Favorite trigger activated: $attempts favorite attempts');
      return PromptTrigger(
        type: PromptType.bottomSheet,
        reason: 'favorite_attempt',
        priority: PromptPriority.high,
        message: 'Sign in to save your favorites and sync across all your devices!',
      );
    }

    return null;
  }

  /// Check if we should show prompt after service views
  PromptTrigger? checkServiceViewTrigger() {
    if (!shouldShowPrompt()) return null;

    final servicesViewed = _sessionTracker.servicesViewedCount;

    if (servicesViewed >= 2) {
      log.i('Service view trigger activated: $servicesViewed services viewed');
      return PromptTrigger(
        type: PromptType.bottomSheet,
        reason: 'service_interest',
        priority: PromptPriority.medium,
        message: 'Ready to book? Create an account to manage your appointments!',
      );
    }

    return null;
  }

  /// Check if we should show prompt after searches
  PromptTrigger? checkSearchTrigger() {
    if (!shouldShowPrompt()) return null;

    final searches = _sessionTracker.searchesMadeCount;

    if (searches >= 2) {
      log.i('Search trigger activated: $searches searches made');
      return PromptTrigger(
        type: PromptType.banner,
        reason: 'search_engagement',
        priority: PromptPriority.low,
        message: 'Get personalized recommendations based on your searches!',
      );
    }

    return null;
  }

  /// Check for high engagement (combination of factors)
  PromptTrigger? checkHighEngagementTrigger() {
    if (!shouldShowPrompt()) return null;

    if (_sessionTracker.isHighlyEngaged) {
      log.i('High engagement trigger activated: Score ${_sessionTracker.calculateEngagementScore()}');
      return PromptTrigger(
        type: PromptType.bottomSheet,
        reason: 'high_engagement',
        priority: PromptPriority.high,
        message: 'You\'re exploring a lot! Create an account to unlock all features.',
      );
    }

    return null;
  }

  // ============================================================================
  // SMART TRIGGER SELECTION
  // ============================================================================

  /// Get the best trigger to show right now
  /// Returns null if no trigger should be shown
  PromptTrigger? getBestTriggerNow() {
    if (!shouldShowPrompt()) return null;

    // Collect all active triggers
    final triggers = <PromptTrigger>[
      if (checkFavoriteTrigger() != null) checkFavoriteTrigger()!,
      if (checkHighEngagementTrigger() != null) checkHighEngagementTrigger()!,
      if (checkServiceViewTrigger() != null) checkServiceViewTrigger()!,
      if (checkTimeTrigger() != null) checkTimeTrigger()!,
      if (checkBrowsingTrigger() != null) checkBrowsingTrigger()!,
      if (checkSearchTrigger() != null) checkSearchTrigger()!,
    ];

    if (triggers.isEmpty) return null;

    // Sort by priority (high to low)
    triggers.sort((a, b) => b.priority.index.compareTo(a.priority.index));

    // Return highest priority trigger
    final bestTrigger = triggers.first;
    log.i('Best trigger selected: ${bestTrigger.reason} (${bestTrigger.priority})');

    return bestTrigger;
  }

  /// Check for specific context-based triggers
  PromptTrigger? checkContextTrigger(String context, {String? customMessage}) {
    if (!shouldShowPrompt()) return null;

    switch (context) {
      case 'salon_detail':
        return PromptTrigger(
          type: PromptType.banner,
          reason: 'salon_detail_view',
          priority: PromptPriority.low,
          message: customMessage ?? 'Like this salon? Save it to your favorites!',
        );

      case 'booking_flow':
      // This is handled by the existing BookingBloc logic
        return null;

      case 'discovery_scroll':
        if (_sessionTracker.salonsViewedCount >= 5) {
          return PromptTrigger(
            type: PromptType.banner,
            reason: 'discovery_engagement',
            priority: PromptPriority.low,
            message: customMessage ?? 'Found some favorites? Save them by creating an account!',
          );
        }
        return null;

      default:
        return null;
    }
  }

  // ============================================================================
  // PROMPT TRACKING
  // ============================================================================

  /// Record that a prompt was shown
  Future<void> recordPromptShown(PromptType type, String reason) async {
    await _sessionTracker.recordPromptShown();
    log.i('Prompt shown: $type for $reason');
  }

  /// Record that a prompt was dismissed
  Future<void> recordPromptDismissed(PromptType type, String reason) async {
    await _sessionTracker.recordPromptDismissed();
    log.i('Prompt dismissed: $type for $reason');
  }

  /// Record that user clicked on prompt (converted)
  void recordPromptClicked(PromptType type, String reason) {
    log.i('Prompt clicked: $type for $reason - User converting!');
    // You can add analytics tracking here
  }

  // ============================================================================
  // UTILITIES
  // ============================================================================

  /// Reset prompt cooldowns (for testing or special cases)
  Future<void> resetPromptCooldowns() async {
    await _sessionTracker.resetPromptData();
    log.i('Prompt cooldowns reset');
  }

  /// Get debug info about current prompt eligibility
  Map<String, dynamic> getDebugInfo() {
    return {
      'canShowPrompt': shouldShowPrompt(),
      'promptDismissCount': _sessionTracker.getPromptDismissCount(),
      'estimatedPromptsShown': _getEstimatedPromptsShown(),
      'minutesSinceLastPrompt': _sessionTracker.getMinutesSinceLastPrompt(),
      'sessionSummary': _sessionTracker.getSessionSummary(),
      'activeTriggers': {
        'browsing': checkBrowsingTrigger() != null,
        'time': checkTimeTrigger() != null,
        'favorite': checkFavoriteTrigger() != null,
        'serviceView': checkServiceViewTrigger() != null,
        'search': checkSearchTrigger() != null,
        'highEngagement': checkHighEngagementTrigger() != null,
      },
    };
  }
}

// ============================================================================
// DATA CLASSES
// ============================================================================

/// Types of prompts we can show
enum PromptType {
  banner,       // Dismissible banner at top/bottom
  bottomSheet,  // Modal bottom sheet
  card,         // In-feed card
  dialog,       // Full modal dialog (used for critical actions only)
}

/// Priority levels for prompts
enum PromptPriority {
  low,     // Show if nothing else is happening
  medium,  // Show when moderately appropriate
  high,    // Show as soon as possible
}

/// A prompt trigger with context
class PromptTrigger {
  final PromptType type;
  final String reason;
  final PromptPriority priority;
  final String message;

  const PromptTrigger({
    required this.type,
    required this.reason,
    required this.priority,
    required this.message,
  });

  @override
  String toString() {
    return 'PromptTrigger(type: $type, reason: $reason, priority: $priority)';
  }
}

import 'package:shared_preferences/shared_preferences.dart';
import '../utils/logger.dart';

/// Service to track guest user behavior and session data.
///
/// This service monitors:
/// - Salons viewed/browsed
/// - Time spent in the app
/// - Favorites attempted (without auth)
/// - Search queries made
/// - Features explored
///
/// Used by GuestPromptService to determine when to show auth prompts.
class GuestSessionTracker {
  final SharedPreferences _prefs;

  // Storage keys
  static const String _keySessionStart = 'guest_session_start';
  static const String _keySalonsViewed = 'guest_salons_viewed';
  static const String _keyFavoritesAttempted = 'guest_favorites_attempted';
  static const String _keySearchesMade = 'guest_searches_made';
  static const String _keyServicesViewed = 'guest_services_viewed';
  static const String _keyLastPromptShown = 'guest_last_prompt_shown';
  static const String _keyPromptDismissCount = 'guest_prompt_dismiss_count';
  static const String _keyFeatureInteractions = 'guest_feature_interactions';

  GuestSessionTracker(this._prefs);

  /// Factory method to initialize the tracker
  static Future<GuestSessionTracker> init() async {
    final prefs = await SharedPreferences.getInstance();
    return GuestSessionTracker(prefs);
  }

  // ============================================================================
  // SESSION MANAGEMENT
  // ============================================================================

  /// Start a new guest session
  Future<void> startSession() async {
    final now = DateTime.now().millisecondsSinceEpoch;
    await _prefs.setInt(_keySessionStart, now);
    log.i('Guest session started at $now');
  }

  /// Get session duration in minutes
  int getSessionDurationMinutes() {
    final start = _prefs.getInt(_keySessionStart);
    if (start == null) return 0;

    final now = DateTime.now().millisecondsSinceEpoch;
    final durationMs = now - start;
    final durationMinutes = (durationMs / 1000 / 60).floor();

    return durationMinutes;
  }

  /// Check if this is a new session (no start time recorded)
  bool get isNewSession {
    return _prefs.getInt(_keySessionStart) == null;
  }

  // ============================================================================
  // BROWSING BEHAVIOR TRACKING
  // ============================================================================

  /// Track when a guest views a salon
  Future<void> trackSalonView(String salonId) async {
    try {
      final viewedSalons = getSalonsViewed();
      if (!viewedSalons.contains(salonId)) {
        viewedSalons.add(salonId);
        await _prefs.setStringList(_keySalonsViewed, viewedSalons);
        log.d('Guest viewed salon: $salonId (Total: ${viewedSalons.length})');
      }
    } catch (e, s) {
      log.e('Error tracking salon view', error: e, stackTrace: s);
    }
  }

  /// Get list of salon IDs viewed in this session
  List<String> getSalonsViewed() {
    return _prefs.getStringList(_keySalonsViewed) ?? [];
  }

  /// Get count of salons viewed
  int get salonsViewedCount => getSalonsViewed().length;

  /// Track when a guest attempts to favorite (before auth)
  Future<void> trackFavoriteAttempt(String salonId) async {
    try {
      final attempts = getFavoriteAttempts();
      if (!attempts.contains(salonId)) {
        attempts.add(salonId);
        await _prefs.setStringList(_keyFavoritesAttempted, attempts);
        log.d('Guest attempted to favorite: $salonId (Total attempts: ${attempts.length})');
      }
    } catch (e, s) {
      log.e('Error tracking favorite attempt', error: e, stackTrace: s);
    }
  }

  /// Get list of salon IDs guest tried to favorite
  List<String> getFavoriteAttempts() {
    return _prefs.getStringList(_keyFavoritesAttempted) ?? [];
  }

  /// Get count of favorite attempts
  int get favoriteAttemptsCount => getFavoriteAttempts().length;

  /// Track search queries made
  Future<void> trackSearch(String query) async {
    try {
      final searches = getSearchesMade();
      searches.add(query);
      await _prefs.setStringList(_keySearchesMade, searches);
      log.d('Guest searched for: "$query" (Total searches: ${searches.length})');
    } catch (e, s) {
      log.e('Error tracking search', error: e, stackTrace: s);
    }
  }

  /// Get list of search queries
  List<String> getSearchesMade() {
    return _prefs.getStringList(_keySearchesMade) ?? [];
  }

  /// Get count of searches made
  int get searchesMadeCount => getSearchesMade().length;

  /// Track when guest views services (on salon detail page)
  Future<void> trackServiceView(String salonId) async {
    try {
      final servicesViewed = getServicesViewed();
      if (!servicesViewed.contains(salonId)) {
        servicesViewed.add(salonId);
        await _prefs.setStringList(_keyServicesViewed, servicesViewed);
        log.d('Guest viewed services for salon: $salonId');
      }
    } catch (e, s) {
      log.e('Error tracking service view', error: e, stackTrace: s);
    }
  }

  /// Get list of salons where services were viewed
  List<String> getServicesViewed() {
    return _prefs.getStringList(_keyServicesViewed) ?? [];
  }

  /// Get count of service views
  int get servicesViewedCount => getServicesViewed().length;

  /// Track feature interactions (e.g., "filter_used", "category_selected")
  Future<void> trackFeatureInteraction(String featureName) async {
    try {
      final interactions = getFeatureInteractions();
      interactions.add('${featureName}_${DateTime.now().millisecondsSinceEpoch}');

      // Keep only last 50 interactions to avoid bloat
      if (interactions.length > 50) {
        interactions.removeRange(0, interactions.length - 50);
      }

      await _prefs.setStringList(_keyFeatureInteractions, interactions);
      log.d('Guest interacted with feature: $featureName');
    } catch (e, s) {
      log.e('Error tracking feature interaction', error: e, stackTrace: s);
    }
  }

  /// Get list of feature interactions
  List<String> getFeatureInteractions() {
    return _prefs.getStringList(_keyFeatureInteractions) ?? [];
  }

  // ============================================================================
  // PROMPT MANAGEMENT
  // ============================================================================

  /// Record when a prompt was shown
  Future<void> recordPromptShown() async {
    final now = DateTime.now().millisecondsSinceEpoch;
    await _prefs.setInt(_keyLastPromptShown, now);
    log.d('Auth prompt shown to guest');
  }

  /// Get timestamp of last prompt shown
  int? getLastPromptTimestamp() {
    return _prefs.getInt(_keyLastPromptShown);
  }

  /// Get minutes since last prompt was shown
  int? getMinutesSinceLastPrompt() {
    final lastPrompt = getLastPromptTimestamp();
    if (lastPrompt == null) return null;

    final now = DateTime.now().millisecondsSinceEpoch;
    final durationMs = now - lastPrompt;
    return (durationMs / 1000 / 60).floor();
  }

  /// Record when user dismisses a prompt
  Future<void> recordPromptDismissed() async {
    try {
      final count = getPromptDismissCount();
      await _prefs.setInt(_keyPromptDismissCount, count + 1);
      log.d('Guest dismissed auth prompt (Total dismissals: ${count + 1})');
    } catch (e, s) {
      log.e('Error recording prompt dismissal', error: e, stackTrace: s);
    }
  }

  /// Get count of times user dismissed prompts
  int getPromptDismissCount() {
    return _prefs.getInt(_keyPromptDismissCount) ?? 0;
  }

  // ============================================================================
  // ENGAGEMENT METRICS
  // ============================================================================

  /// Calculate engagement score (0-100)
  /// Higher score = more engaged = more likely to convert
  int calculateEngagementScore() {
    int score = 0;

    // Time spent (max 20 points)
    final minutes = getSessionDurationMinutes();
    score += (minutes * 4).clamp(0, 20);

    // Salons viewed (max 30 points)
    score += (salonsViewedCount * 6).clamp(0, 30);

    // Services viewed (max 20 points)
    score += (servicesViewedCount * 10).clamp(0, 20);

    // Searches made (max 15 points)
    score += (searchesMadeCount * 5).clamp(0, 15);

    // Favorite attempts (max 15 points)
    score += (favoriteAttemptsCount * 7).clamp(0, 15);

    return score.clamp(0, 100);
  }

  /// Check if user is highly engaged (score > 50)
  bool get isHighlyEngaged => calculateEngagementScore() > 50;

  /// Check if user shows intent to use premium features
  bool get showsPremiumIntent {
    return favoriteAttemptsCount > 0 || servicesViewedCount > 2;
  }

  // ============================================================================
  // RESET & CLEAR
  // ============================================================================

  /// Clear all session data (call after successful signup)
  Future<void> clearSessionData() async {
    await Future.wait([
      _prefs.remove(_keySessionStart),
      _prefs.remove(_keySalonsViewed),
      _prefs.remove(_keyFavoritesAttempted),
      _prefs.remove(_keySearchesMade),
      _prefs.remove(_keyServicesViewed),
      _prefs.remove(_keyLastPromptShown),
      _prefs.remove(_keyPromptDismissCount),
      _prefs.remove(_keyFeatureInteractions),
    ]);
    log.i('Guest session data cleared');
  }

  /// Reset only prompt-related data (for testing or after major dismissals)
  Future<void> resetPromptData() async {
    await Future.wait([
      _prefs.remove(_keyLastPromptShown),
      _prefs.remove(_keyPromptDismissCount),
    ]);
    log.i('Guest prompt data reset');
  }

  // ============================================================================
  // DEBUG & ANALYTICS
  // ============================================================================

  /// Get comprehensive session summary for debugging
  Map<String, dynamic> getSessionSummary() {
    return {
      'sessionDurationMinutes': getSessionDurationMinutes(),
      'salonsViewedCount': salonsViewedCount,
      'servicesViewedCount': servicesViewedCount,
      'searchesMadeCount': searchesMadeCount,
      'favoriteAttemptsCount': favoriteAttemptsCount,
      'promptDismissCount': getPromptDismissCount(),
      'minutesSinceLastPrompt': getMinutesSinceLastPrompt(),
      'engagementScore': calculateEngagementScore(),
      'isHighlyEngaged': isHighlyEngaged,
      'showsPremiumIntent': showsPremiumIntent,
    };
  }

  /// Log current session stats (for debugging)
  void logSessionStats() {
    final summary = getSessionSummary();
    log.i('Guest Session Stats: $summary');
  }
}

import 'package:shared_preferences/shared_preferences.dart';
import '../utils/logger.dart';

/// Service for managing local data storage using SharedPreferences.
///
/// This is used to persist guest browsing data like:
/// - Favorite salons (before authentication)
/// - Browsing history
/// - Search history
/// - Last viewed salons
/// - App Locale/Language settings
///
/// When a guest user signs up, this data can be migrated to their Firestore profile.
class LocalStorageService {
  static const String _keyFavoriteSalons = 'guest_favorite_salons';
  static const String _keyBrowsingHistory = 'guest_browsing_history';
  static const String _keySearchHistory = 'guest_search_history';
  static const String _keyLastViewedSalon = 'guest_last_viewed_salon';
  static const String _keyIsFirstLaunch = 'is_first_launch';
  static const String _keyAppLocale = 'app_locale'; // NEW

  final SharedPreferences _prefs;

  LocalStorageService(this._prefs);

  /// Factory method to initialize the service
  static Future<LocalStorageService> init() async {
    final prefs = await SharedPreferences.getInstance();
    return LocalStorageService(prefs);
  }

  // ============================================================================
  // APP SETTINGS (Locale)
  // ============================================================================

  /// Save the selected language code (e.g., 'en', 'sw')
  Future<void> setLocale(String languageCode) async {
    await _prefs.setString(_keyAppLocale, languageCode);
    log.i('App locale saved: $languageCode');
  }

  /// Get the saved language code. Returns null if not set.
  String? getLocale() {
    return _prefs.getString(_keyAppLocale);
  }

  // ============================================================================
  // GENERIC PREFERENCES
  // ============================================================================

  /// Get a boolean value from preferences
  bool? getBool(String key) {
    return _prefs.getBool(key);
  }

  /// Set a boolean value in preferences
  Future<void> setBool(String key, bool value) async {
    await _prefs.setBool(key, value);
  }

  /// Get a string value from preferences
  String? getString(String key) {
    return _prefs.getString(key);
  }

  /// Set a string value in preferences
  Future<void> setString(String key, String value) async {
    await _prefs.setString(key, value);
  }

  // ============================================================================
  // FIRST LAUNCH
  // ============================================================================

  /// Check if this is the first time the app is launched
  bool get isFirstLaunch {
    return _prefs.getBool(_keyIsFirstLaunch) ?? true;
  }

  /// Mark the app as launched (called after onboarding)
  Future<void> markAsLaunched() async {
    await _prefs.setBool(_keyIsFirstLaunch, false);
    log.i('App marked as launched');
  }

  // ============================================================================
  // FAVORITE SALONS (for guests)
  // ============================================================================

  /// Get list of favorite salon IDs for guest users
  List<String> getFavoriteSalons() {
    try {
      final favorites = _prefs.getStringList(_keyFavoriteSalons) ?? [];
      log.d('Retrieved ${favorites.length} favorite salons for guest');
      return favorites;
    } catch (e, s) {
      log.e('Error getting favorite salons', error: e, stackTrace: s);
      return [];
    }
  }

  /// Add a salon to favorites (for guest users)
  Future<bool> addFavoriteSalon(String salonId) async {
    try {
      final favorites = getFavoriteSalons();
      if (!favorites.contains(salonId)) {
        favorites.add(salonId);
        await _prefs.setStringList(_keyFavoriteSalons, favorites);
        log.i('Added salon $salonId to guest favorites');
        return true;
      }
      return false;
    } catch (e, s) {
      log.e('Error adding favorite salon', error: e, stackTrace: s);
      return false;
    }
  }

  /// Remove a salon from favorites (for guest users)
  Future<bool> removeFavoriteSalon(String salonId) async {
    try {
      final favorites = getFavoriteSalons();
      if (favorites.contains(salonId)) {
        favorites.remove(salonId);
        await _prefs.setStringList(_keyFavoriteSalons, favorites);
        log.i('Removed salon $salonId from guest favorites');
        return true;
      }
      return false;
    } catch (e, s) {
      log.e('Error removing favorite salon', error: e, stackTrace: s);
      return false;
    }
  }

  /// Check if a salon is favorited
  bool isSalonFavorited(String salonId) {
    return getFavoriteSalons().contains(salonId);
  }

  /// Clear all favorite salons (after migration to Firestore)
  Future<void> clearFavoriteSalons() async {
    await _prefs.remove(_keyFavoriteSalons);
    log.i('Cleared guest favorite salons');
  }

  // ============================================================================
  // BROWSING HISTORY
  // ============================================================================

  /// Get browsing history as list of salon IDs
  List<String> getBrowsingHistory() {
    try {
      final history = _prefs.getStringList(_keyBrowsingHistory) ?? [];
      log.d('Retrieved browsing history: ${history.length} items');
      return history;
    } catch (e, s) {
      log.e('Error getting browsing history', error: e, stackTrace: s);
      return [];
    }
  }

  /// Add a salon to browsing history
  Future<void> addToBrowsingHistory(String salonId) async {
    try {
      final history = getBrowsingHistory();

      // Remove if already exists (to move to front)
      history.remove(salonId);

      // Add to front
      history.insert(0, salonId);

      // Keep only last 20 items
      if (history.length > 20) {
        history.removeRange(20, history.length);
      }

      await _prefs.setStringList(_keyBrowsingHistory, history);
      log.d('Added salon $salonId to browsing history');
    } catch (e, s) {
      log.e('Error adding to browsing history', error: e, stackTrace: s);
    }
  }

  /// Clear browsing history
  Future<void> clearBrowsingHistory() async {
    await _prefs.remove(_keyBrowsingHistory);
    log.i('Cleared browsing history');
  }

  // ============================================================================
  // SEARCH HISTORY
  // ============================================================================

  /// Get search history
  List<String> getSearchHistory() {
    try {
      final history = _prefs.getStringList(_keySearchHistory) ?? [];
      return history;
    } catch (e, s) {
      log.e('Error getting search history', error: e, stackTrace: s);
      return [];
    }
  }

  /// Add a search term to history
  Future<void> addToSearchHistory(String searchTerm) async {
    try {
      if (searchTerm.trim().isEmpty) return;

      final history = getSearchHistory();

      // Remove if already exists
      history.remove(searchTerm);

      // Add to front
      history.insert(0, searchTerm);

      // Keep only last 10 items
      if (history.length > 10) {
        history.removeRange(10, history.length);
      }

      await _prefs.setStringList(_keySearchHistory, history);
      log.d('Added "$searchTerm" to search history');
    } catch (e, s) {
      log.e('Error adding to search history', error: e, stackTrace: s);
    }
  }

  /// Clear search history
  Future<void> clearSearchHistory() async {
    await _prefs.remove(_keySearchHistory);
    log.i('Cleared search history');
  }

  // ============================================================================
  // LAST VIEWED SALON
  // ============================================================================

  /// Get last viewed salon ID
  String? getLastViewedSalon() {
    return _prefs.getString(_keyLastViewedSalon);
  }

  /// Set last viewed salon
  Future<void> setLastViewedSalon(String salonId) async {
    await _prefs.setString(_keyLastViewedSalon, salonId);
    log.d('Set last viewed salon: $salonId');
  }

  // ============================================================================
  // CLEAR ALL GUEST DATA
  // ============================================================================

  /// Clear all guest data (call this after successful migration to Firestore)
  Future<void> clearAllGuestData() async {
    await Future.wait([
      clearFavoriteSalons(),
      clearBrowsingHistory(),
      clearSearchHistory(),
      _prefs.remove(_keyLastViewedSalon),
    ]);
    log.i('Cleared all guest data');
  }

  // ============================================================================
  // MIGRATION HELPER
  // ============================================================================

  /// Get all guest data for migration to Firestore
  Map<String, dynamic> getGuestDataForMigration() {
    return {
      'favoriteSalons': getFavoriteSalons(),
      'browsingHistory': getBrowsingHistory(),
      'searchHistory': getSearchHistory(),
      'lastViewedSalon': getLastViewedSalon(),
    };
  }
}

import 'package:firebase_messaging/firebase_messaging.dart';
import 'package:flutter_local_notifications/flutter_local_notifications.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:cloud_functions/cloud_functions.dart';
import 'package:pendeza/app/utils/logger.dart';
import 'package:pendeza/app/config/app_router.dart';

// This must be a top-level function (outside the class)
@pragma('vm:entry-point')
Future<void> _firebaseMessagingBackgroundHandler(RemoteMessage message) async {
  // You can initialize Firebase here if needed for background logic
  // await Firebase.initializeApp();
  print("Handling a background message: ${message.messageId}");
}

class NotificationService {
  final FirebaseMessaging _fcm = FirebaseMessaging.instance;
  final FlutterLocalNotificationsPlugin _localNotifications =
  FlutterLocalNotificationsPlugin();

  bool _isInitialized = false;

  // Singleton pattern
  static final NotificationService _instance = NotificationService._internal();
  factory NotificationService() => _instance;
  NotificationService._internal();

  /// Initialize the Notification Service
  Future<void> init() async {
    if (_isInitialized) return;

    // 1. Request Permissions (Critical for Android 13+ and iOS)
    NotificationSettings settings = await _fcm.requestPermission(
      alert: true,
      badge: true,
      sound: true,
    );

    if (settings.authorizationStatus == AuthorizationStatus.authorized) {
      log.i('User granted notification permission');
    } else if (settings.authorizationStatus ==
        AuthorizationStatus.provisional) {
      log.i('User granted provisional permission');
    } else {
      log.w('User declined or has not accepted permission');
      return;
    }

    // 2. Setup Background Handler
    FirebaseMessaging.onBackgroundMessage(_firebaseMessagingBackgroundHandler);

    // 3. Setup Local Notifications (For Foreground Display)
    const AndroidInitializationSettings initializationSettingsAndroid =
    AndroidInitializationSettings(
        '@mipmap/ic_launcher'); // Ensure this icon exists

    const DarwinInitializationSettings initializationSettingsIOS =
    DarwinInitializationSettings();

    const InitializationSettings initializationSettings = InitializationSettings(
      android: initializationSettingsAndroid,
      iOS: initializationSettingsIOS,
    );

    await _localNotifications.initialize(
      initializationSettings,
      onDidReceiveNotificationResponse: (NotificationResponse response) {
        _handleNotificationTap(response.payload);
      },
    );

    // 4. Create Android Notification Channel (High Importance)
    // This ensures heads-up notifications work on Android 8+
    const AndroidNotificationChannel channel = AndroidNotificationChannel(
      'high_importance_channel', // id
      'High Importance Notifications', // title
      description:
      'This channel is used for important notifications.', // description
      importance: Importance.max,
    );

    await _localNotifications
        .resolvePlatformSpecificImplementation<
        AndroidFlutterLocalNotificationsPlugin>()
        ?.createNotificationChannel(channel);

    // 5. Listen for Foreground Messages
    FirebaseMessaging.onMessage.listen((RemoteMessage message) {
      log.d('Got a message whilst in the foreground!');
      log.d('Message data: ${message.data}');

      if (message.notification != null) {
        log.d('Message also contained a notification: ${message.notification}');
        _showLocalNotification(message);
      }
    });

    // 6. Handle interaction when app opens from terminated state
    _fcm.getInitialMessage().then((RemoteMessage? message) {
      if (message != null) {
        _handleBackgroundInteraction(message);
      }
    });

    // 7. Handle interaction when app opens from background state
    FirebaseMessaging.onMessageOpenedApp.listen(_handleBackgroundInteraction);

    _isInitialized = true;
    log.i("NotificationService initialized");
  }

  /// Display a local notification when a message arrives in foreground
  void _showLocalNotification(RemoteMessage message) {
    RemoteNotification? notification = message.notification;
    AndroidNotification? android = message.notification?.android;

    if (notification != null && android != null) {
      _localNotifications.show(
        notification.hashCode,
        notification.title,
        notification.body,
        NotificationDetails(
          android: AndroidNotificationDetails(
            'high_importance_channel',
            'High Importance Notifications',
            channelDescription:
            'This channel is used for important notifications.',
            icon: '@mipmap/ic_launcher',
            importance: Importance.max,
            priority: Priority.high,
          ),
        ),
        // Pass the route or data as payload
        payload: message.data['route'],
      );
    }
  }

  /// Handle tap on notification (Background/Terminated)
  void _handleBackgroundInteraction(RemoteMessage message) {
    log.i("Notification interaction detected");
    if (message.data.containsKey('route')) {
      _navigate(message.data['route']);
    }
  }

  /// Handle tap on local notification (Foreground)
  void _handleNotificationTap(String? payload) {
    if (payload != null) {
      _navigate(payload);
    }
  }

  /// Navigation Logic using GoRouter
  void _navigate(String route) {
    log.i("Navigating to route from notification: $route");
    // Use a slight delay to ensure the router is ready if app just launched
    Future.delayed(const Duration(milliseconds: 500), () {
      final router = AppRouter.router;
      router.push(route);
    });
  }

  /// Helper to subscribe to topics (e.g., "all_users", "promotions")
  Future<void> subscribeToTopic(String topic) async {
    await _fcm.subscribeToTopic(topic);
    log.i("Subscribed to topic: $topic");
  }

  /// Helper to unsubscribe
  Future<void> unsubscribeFromTopic(String topic) async {
    await _fcm.unsubscribeFromTopic(topic);
  }

  /// Send push notification to users by role
  ///
  /// This uses your EXISTING Cloud Function: send_admin_notification
  /// No need to deploy anything new - it's already deployed!
  ///
  /// [title] - The notification title
  /// [body] - The notification message body
  /// [role] - Target role: null/'all' for all users, 'client' for clients, 'owner' for owners
  /// [data] - Optional additional data to include with notification
  Future<void> sendNotificationToRole({
    required String title,
    required String body,
    String? role, // null = all users, 'client', 'owner'
    Map<String, dynamic>? data,
  }) async {
    try {
      log.i('Sending notification via Cloud Function to role: ${role ?? "all"}');

      // Map role to targetAudience format expected by Cloud Function
      String targetAudience;
      if (role == null || role == 'all') {
        targetAudience = 'all';
      } else if (role == 'client') {
        targetAudience = 'clients'; // Note: plural form for Cloud Function
      } else if (role == 'owner') {
        targetAudience = 'owners'; // Note: plural form for Cloud Function
      } else {
        targetAudience = role;
      }

      // Call the existing Cloud Function: send_admin_notification
      // IMPORTANT: Specify the region where your functions are deployed
      final callable = FirebaseFunctions.instanceFor(region: 'us-central1')
          .httpsCallable(
        'send_admin_notification',
        options: HttpsCallableOptions(
          timeout: const Duration(seconds: 60), // Longer timeout for large sends
        ),
      );

      final result = await callable.call({
        'title': title,
        'body': body,
        'targetAudience': targetAudience,
        'imageUrl': null, // Optional: add if you support images
        'route': data?['route'], // Optional: navigation route
        'customData': data, // Optional: additional data
        'priority': 'high',
        'saveToInbox': true, // Save to notification_inbox collection
      });

      // 🔥 FIX: Properly convert the response to Map<String, dynamic>
      final response = _convertToMap(result.data);

      if (response['success'] == true) {
        final analytics = response['analytics'] != null
            ? _convertToMap(response['analytics'])
            : null;
        log.i('✅ Notification sent successfully!');
        if (analytics != null) {
          log.i('   Tokens found: ${analytics['tokensFound']}');
          log.i('   Sent: ${analytics['sent']}');
          log.i('   Failed: ${analytics['failed']}');
        }
      } else {
        log.w('⚠️ Notification sent but with warnings: ${response['message']}');
      }
    } catch (e, stackTrace) {
      log.e('❌ Error sending notification: $e', error: e, stackTrace: stackTrace);
      rethrow;
    }
  }

  /// Alternative: Send notification to topic
  ///
  /// Users must subscribe to topics first using subscribeToTopic()
  Future<void> sendNotificationToTopic({
    required String topic,
    required String title,
    required String body,
    Map<String, dynamic>? data,
  }) async {
    try {
      log.i('Sending notification to topic: $topic');

      final callable = FirebaseFunctions.instanceFor(region: 'us-central1')
          .httpsCallable(
        'send_admin_notification',
      );

      final result = await callable.call({
        'title': title,
        'body': body,
        'targetAudience': 'topic:$topic',
        'customData': data,
        'priority': 'high',
        'saveToInbox': true,
      });

      // 🔥 FIX: Properly convert the response
      final response = _convertToMap(result.data);
      log.i('Notification sent to topic successfully: $response');
    } catch (e, stackTrace) {
      log.e('Error sending notification to topic: $e',
          error: e, stackTrace: stackTrace);
      rethrow;
    }
  }

  /// 🔥 Helper method to safely convert dynamic map to Map<String, dynamic>
  /// This fixes the type cast error: '_Map<Object?, Object?>' is not a subtype of type 'Map<String, dynamic>'
  Map<String, dynamic> _convertToMap(dynamic data) {
    if (data == null) return {};
    if (data is Map<String, dynamic>) return data;
    if (data is Map) {
      return Map<String, dynamic>.from(data);
    }
    return {};
  }
}

import 'dart:convert';
import 'package:http/http.dart' as http;
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:pendeza/app/config/env_config.dart';
import 'package:pendeza/app/utils/logger.dart';
import 'package:pendeza/shared/models/transaction_model.dart';

/// Payment Service for PalmPesa Integration
///
/// 🔥 ENHANCED VERSION with Smart Status Polling
///
/// Since PalmPesa webhooks are unreliable, this service includes
/// built-in status checking that can be called by WalletBloc.
///
/// Supports:
/// - USSD Push payments (direct to phone)
/// - Pay by Link (web-based payment)
/// - Payment status verification via polling
/// - Automatic Firestore transaction updates
///
/// API Documentation: https://palmpesa-docs.netlify.app
class PaymentService {
  final FirebaseFirestore _firestore = FirebaseFirestore.instance;

  // ✅ SECURE: Credentials loaded from environment configuration
  // Use --dart-define to override at build time for different environments
  static const String _baseUrl = EnvConfig.palmPesaBaseUrl;
  static const String _apiToken = EnvConfig.palmPesaApiToken;
  static const int _userId = EnvConfig.palmPesaUserId;
  static const String _vendorId = EnvConfig.palmPesaVendorId;

  // Webhook URL - Cloud Function for payment confirmation
  static const String _webhookUrl = EnvConfig.paymentWebhookUrl;

  // Custom Redirect URLs for WebView interception (Pay by Link)
  static const String successRedirectUrl = EnvConfig.paymentSuccessUrl;
  static const String cancelRedirectUrl = EnvConfig.paymentCancelUrl;

  static const String _fallbackEmail = EnvConfig.fallbackEmail;

  // ==========================================
  // 🆕 WALLET TOP-UP VIA USSD PUSH
  // ==========================================

  /// Initiate Wallet Top-Up via USSD Push
  ///
  /// Uses the `/api/palmpesa/initiate` endpoint which:
  /// - Sends a USSD prompt directly to the user's phone
  /// - Returns order_id for status polling
  ///
  /// Returns: Map with success status, message, transactionId, and gatewayOrderId
  Future<Map<String, dynamic>> initiateWalletTopUp({
    required String userId,
    required String phoneNumber,
    required double amount,
    required String userName,
    required String userEmail,
  }) async {
    final url = Uri.parse('$_baseUrl/palmpesa/initiate');

    final validEmail = (userEmail.isNotEmpty && userEmail.contains('@'))
        ? userEmail
        : _fallbackEmail;

    // Generate unique transaction ID for tracking
    final transactionId = "WALLET_${userId}_${DateTime.now().millisecondsSinceEpoch}";

    // Format phone number
    final formattedPhone = _formatPhoneNumber(phoneNumber);

    final body = {
      "name": userName,
      "email": validEmail,
      "phone": formattedPhone,
      "amount": amount.toInt(),
      "transaction_id": transactionId,
      "address": "Tanzania",
      "postcode": "00000",
      "callback_url": _webhookUrl,
    };

    try {
      log.i('💳 Initiating Wallet Top-Up via USSD Push');
      log.i('   User: $userId');
      log.i('   Amount: TZS ${amount.toStringAsFixed(0)}');
      log.i('   Phone: $formattedPhone');
      log.d('   Endpoint: $url');
      log.d('   Request Body: ${jsonEncode(body)}');

      final response = await http.post(
        url,
        headers: {
          'Authorization': 'Bearer $_apiToken',
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        body: jsonEncode(body),
      );

      log.i('📥 Response Status: ${response.statusCode}');
      log.d('📥 Response Body: ${response.body}');

      // Accept 200, 201, AND 202 as success codes
      if (response.statusCode >= 200 && response.statusCode < 300) {
        final data = jsonDecode(response.body);

        // Check for order_id - this is the success indicator
        final orderId = data['order_id'];

        if (orderId != null) {
          final message = data['message'] ?? 'Payment request sent. Please check your phone.';

          log.i('✅ USSD Push initiated successfully');
          log.i('   Gateway Order ID: $orderId');
          log.i('   Transaction ID: $transactionId');
          log.i('   Message: $message');

          // 🔥 CREATE TRANSACTION DOCUMENT IN FIRESTORE
          try {
            log.i('📝 Creating transaction document in Firestore...');

            final transaction = TransactionModel.deposit(
              userId: userId,
              amount: amount,
              gatewayOrderId: orderId,
              description: 'Wallet deposit via M-Pesa',
            );

            // Use transactionId as document ID for easy lookup
            await _firestore
                .collection('transactions')
                .doc(transactionId)
                .set({
              ...transaction.toFirestore(),
              'localTransactionId': transactionId,
              'gatewayOrderId': orderId,
              'phoneNumber': formattedPhone,
              'initiatedAt': FieldValue.serverTimestamp(),
            });

            log.i('✅ Transaction document created: $transactionId');
          } catch (firestoreError, stackTrace) {
            log.e('❌ Failed to create transaction document',
                error: firestoreError, stackTrace: stackTrace);
            // Don't fail the whole operation - polling can still work
          }

          return {
            'success': true,
            'message': message,
            'transactionId': transactionId,
            'gatewayOrderId': orderId,
            'paymentStatus': data['payment_status'] ?? 'PENDING',
            'data': data,
          };
        }

        // Fallback for older response format
        if (data['response'] != null) {
          final innerResponse = data['response'];
          if (innerResponse['result'] == 'SUCCESS' ||
              innerResponse['resultcode'] == '000') {
            return {
              'success': true,
              'message': innerResponse['message'] ?? 'Payment prompt sent to your phone',
              'transactionId': transactionId,
              'gatewayOrderId': data['order_id'] ?? transactionId,
              'data': data,
            };
          }
        }

        // If message indicates initiation but no order_id
        if (data['message'] != null &&
            data['message'].toString().toLowerCase().contains('initiated')) {
          log.w('⚠️ Payment initiated but no order_id in response');
          return {
            'success': true,
            'message': data['message'],
            'transactionId': transactionId,
            'gatewayOrderId': transactionId,
            'data': data,
          };
        }

        // Unexpected response format
        final errorMsg = data['message'] ?? data['error'] ?? 'Unknown response from payment gateway';
        log.w('⚠️ Unexpected response format: $errorMsg');
        return {
          'success': false,
          'message': errorMsg,
          'transactionId': transactionId,
        };
      } else {
        // Actual error response (4xx, 5xx)
        log.e('❌ Payment request failed with status: ${response.statusCode}');
        String errorMsg = 'Payment failed. Please try again.';

        try {
          final errorData = jsonDecode(response.body);
          errorMsg = errorData['message'] ?? errorData['error'] ?? errorMsg;
        } catch (_) {}

        return {
          'success': false,
          'message': errorMsg,
          'transactionId': transactionId,
        };
      }
    } catch (e, stackTrace) {
      log.e('❌ Error initiating wallet top-up', error: e, stackTrace: stackTrace);
      return {
        'success': false,
        'message': 'Connection error. Please check your internet and try again.',
        'transactionId': transactionId,
      };
    }
  }

  // ==========================================
  // 🆕 WALLET TOP-UP VIA PAY BY LINK
  // ==========================================

  Future<Map<String, dynamic>> createWalletTopUpLink({
    required String userId,
    required double amount,
    required String userName,
    required String userEmail,
    required String phoneNumber,
  }) async {
    final url = Uri.parse('$_baseUrl/process-payment');
    final validEmail = (userEmail.isNotEmpty && userEmail.contains('@'))
        ? userEmail
        : _fallbackEmail;

    final transactionId = "WALLET_${userId}_${DateTime.now().millisecondsSinceEpoch}";
    final formattedPhone = _formatPhoneNumber(phoneNumber);

    final body = {
      "user_id": _userId, // 🔥 FIX: Now correctly an integer
      "vendor": _vendorId,
      "order_id": transactionId,
      "buyer_email": validEmail,
      "buyer_name": userName,
      "buyer_phone": formattedPhone,
      "amount": amount.toInt(),
      "currency": "TZS",
      "redirect_url": successRedirectUrl,
      "cancel_url": cancelRedirectUrl,
      "webhook": _webhookUrl,
      "buyer_remarks": "Wallet Top-Up",
      "merchant_remarks": "Pendeza Wallet",
      "no_of_items": 1
    };

    try {
      log.i('💳 Creating Wallet Top-Up Link');
      log.i('   Amount: TZS ${amount.toStringAsFixed(0)}');
      log.d('📤 Request body: ${jsonEncode(body)}');

      final response = await http.post(
        url,
        headers: {
          'Authorization': 'Bearer $_apiToken',
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        body: jsonEncode(body),
      );

      log.i('📥 Response Status: ${response.statusCode}');
      log.d('📥 Response Body: ${response.body}');

      if (response.statusCode == 200 || response.statusCode == 201) {
        final data = jsonDecode(response.body);
        if (data['raw'] != null && data['raw']['payment_gateway_url'] != null) {
          final paymentUrl = data['raw']['payment_gateway_url'];

          // Create transaction document
          try {
            final transaction = TransactionModel.deposit(
              userId: userId,
              amount: amount,
              gatewayOrderId: transactionId,
              description: 'Wallet deposit via Pay Link',
            );

            await _firestore.collection('transactions').doc(transactionId).set({
              ...transaction.toFirestore(),
              'localTransactionId': transactionId,
              'gatewayOrderId': transactionId,
              'phoneNumber': formattedPhone,
              'paymentMethod': 'PayByLink',
              'initiatedAt': FieldValue.serverTimestamp(),
            });
          } catch (e) {
            log.e('Failed to create transaction document', error: e);
          }

          return {
            'success': true,
            'paymentUrl': paymentUrl,
            'transactionId': transactionId,
            'gatewayOrderId': transactionId,
          };
        } else {
          throw Exception('Invalid API Response: Link not found');
        }
      } else {
        log.e('❌ Pay by Link failed. Status: ${response.statusCode}, Body: ${response.body}');
        throw Exception('Failed to create link. Status: ${response.statusCode}');
      }
    } catch (e, stackTrace) {
      log.e('❌ Error creating wallet top-up link', error: e, stackTrace: stackTrace);
      rethrow;
    }
  }

  // ==========================================
  // 🔥🔥🔥 SMART STATUS POLLING SYSTEM 🔥🔥🔥
  // ==========================================

  /// Check payment status from PalmPesa API
  ///
  /// This is the KEY method that makes the system work without webhooks.
  /// It calls PalmPesa's `/api/order-status` endpoint and returns
  /// the current status of the payment.
  ///
  /// Returns a map with:
  /// - 'status': 'COMPLETED' | 'PENDING' | 'FAILED' | 'UNKNOWN'
  /// - 'rawData': The full response from PalmPesa
  /// - 'amount': The amount (if available)
  Future<Map<String, dynamic>> checkPaymentStatus(String gatewayOrderId) async {
    final url = Uri.parse('$_baseUrl/order-status');

    try {
      log.d('🔍 Checking payment status for: $gatewayOrderId');

      final response = await http.post(
        url,
        headers: {
          'Authorization': 'Bearer $_apiToken',
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        body: jsonEncode({"order_id": gatewayOrderId}),
      );

      log.d('📥 Status Response: ${response.body}');

      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);

        // Handle array format: { "data": [...] }
        if (data['data'] != null && data['data'] is List && (data['data'] as List).isNotEmpty) {
          final transaction = data['data'][0];
          final status = transaction['payment_status']?.toString().toUpperCase() ?? 'UNKNOWN';
          final amount = transaction['amount'];

          log.i('📊 Payment Status: $status');

          return {
            'status': _normalizeStatus(status),
            'rawStatus': status,
            'amount': amount,
            'rawData': transaction,
          };
        }

        // Handle direct status format: { "payment_status": "..." }
        if (data['payment_status'] != null) {
          final status = data['payment_status'].toString().toUpperCase();
          log.i('📊 Payment Status: $status');

          return {
            'status': _normalizeStatus(status),
            'rawStatus': status,
            'rawData': data,
          };
        }

        // No status found
        log.w('⚠️ No payment status in response');
        return {
          'status': 'UNKNOWN',
          'rawData': data,
        };
      } else {
        log.e('❌ Status check failed: ${response.statusCode}');
        return {
          'status': 'ERROR',
          'error': 'HTTP ${response.statusCode}',
        };
      }
    } catch (e, stackTrace) {
      log.e('❌ Error checking payment status', error: e, stackTrace: stackTrace);
      return {
        'status': 'ERROR',
        'error': e.toString(),
      };
    }
  }

  /// Normalize status strings from PalmPesa
  String _normalizeStatus(String status) {
    switch (status.toUpperCase()) {
      case 'COMPLETED':
      case 'SUCCESS':
      case 'SUCCESSFUL':
      case 'PAID':
        return 'COMPLETED';
      case 'PENDING':
      case 'PROCESSING':
      case 'INITIATED':
        return 'PENDING';
      case 'FAILED':
      case 'FAILURE':
      case 'CANCELLED':
      case 'CANCELED':
      case 'REJECTED':
      case 'DECLINED':
        return 'FAILED';
      default:
        return 'UNKNOWN';
    }
  }

  /// 🔥 CRITICAL METHOD: Check status AND update Firestore if completed
  ///
  /// This is called by WalletBloc's polling loop. It:
  /// 1. Checks PalmPesa API for current status
  /// 2. If COMPLETED, updates Firestore transaction AND credits wallet
  /// 3. Returns the result for WalletBloc to update UI
  ///
  /// Returns:
  /// - 'status': 'COMPLETED' | 'PENDING' | 'FAILED' | 'ERROR'
  /// - 'credited': true if wallet was credited this call
  /// - 'newBalance': The new wallet balance (if credited)
  Future<Map<String, dynamic>> checkAndUpdatePaymentStatus({
    required String gatewayOrderId,
    required String transactionId,
    required String userId,
    required double amount,
  }) async {
    try {
      // 1. Check status from PalmPesa
      final statusResult = await checkPaymentStatus(gatewayOrderId);
      final status = statusResult['status'] as String;

      log.i('🔄 Payment status for $gatewayOrderId: $status');

      // 2. If COMPLETED, update Firestore and credit wallet
      if (status == 'COMPLETED') {
        // Check if already credited (prevent double credit)
        final txnDoc = await _firestore.collection('transactions').doc(transactionId).get();
        if (txnDoc.exists) {
          final currentStatus = txnDoc.data()?['status'];
          if (currentStatus == 'completed') {
            log.i('⚠️ Transaction already completed, skipping credit');
            final walletDoc = await _firestore.collection('wallets').doc(userId).get();
            return {
              'status': 'COMPLETED',
              'credited': false,
              'alreadyCompleted': true,
              'newBalance': walletDoc.data()?['balance'] ?? 0.0,
            };
          }
        }

        // Credit the wallet
        log.i('💰 Crediting wallet for user $userId with amount $amount');
        final newBalance = await _creditWallet(
          userId: userId,
          amount: amount,
          transactionId: transactionId,
          gatewayOrderId: gatewayOrderId,
        );

        return {
          'status': 'COMPLETED',
          'credited': true,
          'newBalance': newBalance,
        };
      }

      // 3. If FAILED, update transaction status
      if (status == 'FAILED') {
        await _firestore.collection('transactions').doc(transactionId).update({
          'status': 'failed',
          'failedAt': FieldValue.serverTimestamp(),
          'failureReason': statusResult['rawData']?['message'] ?? 'Payment failed',
        });

        return {
          'status': 'FAILED',
          'credited': false,
        };
      }

      // 4. Still pending
      return {
        'status': status,
        'credited': false,
      };
    } catch (e, stackTrace) {
      log.e('❌ Error in checkAndUpdatePaymentStatus', error: e, stackTrace: stackTrace);
      return {
        'status': 'ERROR',
        'error': e.toString(),
        'credited': false,
      };
    }
  }

  /// Credit wallet balance in Firestore
  ///
  /// Uses a Firestore transaction for atomicity
  Future<double> _creditWallet({
    required String userId,
    required double amount,
    required String transactionId,
    required String gatewayOrderId,
  }) async {
    double newBalance = 0;

    await _firestore.runTransaction((transaction) async {
      // 1. Get current wallet
      final walletRef = _firestore.collection('wallets').doc(userId);
      final walletDoc = await transaction.get(walletRef);

      double currentBalance = 0;
      double totalDeposited = 0;

      if (walletDoc.exists) {
        currentBalance = (walletDoc.data()?['balance'] ?? 0).toDouble();
        totalDeposited = (walletDoc.data()?['totalDeposited'] ?? 0).toDouble();
      }

      // 2. Calculate new balance
      newBalance = currentBalance + amount;
      totalDeposited += amount;

      // 3. Update wallet
      transaction.set(walletRef, {
        'userId': userId,
        'balance': newBalance,
        'totalDeposited': totalDeposited,
        'currency': 'TZS',
        'status': 'active',
        'lastUpdated': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));

      // 4. Update transaction status
      final txnRef = _firestore.collection('transactions').doc(transactionId);
      transaction.update(txnRef, {
        'status': 'completed',
        'completedAt': FieldValue.serverTimestamp(),
        'balanceAfter': newBalance,
      });
    });

    log.i('✅ Wallet credited! New balance: TZS $newBalance');
    return newBalance;
  }

