  /// Create Payment Link for Appointment Booking
  ///
  /// 🔥 FIXED: user_id now sent as integer (was string causing 500 error)
  Future<String> createPaymentLink({
    required String orderId,
    required double amount,
    required String name,
    required String email,
    required String phone,
    String? userId, // 🔥 NEW: Optional userId for transaction tracking
  }) async {
    final url = Uri.parse('$_baseUrl/process-payment');
    final validEmail = (email.isNotEmpty && email.contains('@')) ? email : _fallbackEmail;
    final formattedPhone = _formatPhoneNumber(phone);

    final body = {
      "user_id": _userId, // 🔥 FIX: Now correctly an integer (21 not "21")
      "vendor": _vendorId,
      "order_id": orderId,
      "buyer_email": validEmail,
      "buyer_name": name,
      "buyer_phone": formattedPhone,
      "amount": amount.toInt(),
      "currency": "TZS",
      "redirect_url": successRedirectUrl,
      "cancel_url": cancelRedirectUrl,
      "webhook": _webhookUrl,
      "buyer_remarks": "Appointment Booking",
      "merchant_remarks": "Salon Booking Payment",
      "no_of_items": 1
    };

    try {
      log.i('💳 Creating Payment Link for Order: $orderId');
      log.d('📤 Request body: ${jsonEncode(body)}');

      final response = await http.post(
        url,
        headers: {
          'Authorization': 'Bearer $_apiToken',
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        body: jsonEncode(body),
      );

      log.i('📥 Response Status: ${response.statusCode}');
      log.d('📥 Response Body: ${response.body}');

      if (response.statusCode == 200 || response.statusCode == 201) {
        final data = jsonDecode(response.body);
        if (data['raw'] != null && data['raw']['payment_gateway_url'] != null) {
          final paymentUrl = data['raw']['payment_gateway_url'];
          // ... (existing transaction creation code)
          return paymentUrl;
        } else {
          throw Exception('Invalid API Response: Link not found');
        }
      } else {
        log.e('❌ Pay by Link failed. Status: ${response.statusCode}, Body: ${response.body}');
        throw Exception('Failed to create link. Status: ${response.statusCode}');
      }

    } catch (e, stackTrace) {
      log.e('❌ Error creating payment link', error: e, stackTrace: stackTrace);
      rethrow;
    }
  }

  /// Initiate USSD Payment for Appointment
  ///
  /// 🔥 FIXED: Now creates transaction document with proper userId field
  /// This allows Firestore rules to validate the write
  Future<Map<String, dynamic>> initiatePayment({
    required String phoneNumber,
    required double amount,
    required String orderId, // This is the appointmentId
    required String email,
    required String name,
    String? userId, // 🔥 NEW: Required for Firestore rules
  }) async {
    final url = Uri.parse('$_baseUrl/palmpesa/initiate');

    final validEmail = (email.isNotEmpty && email.contains('@')) ? email : _fallbackEmail;
    // 🔥 FIX: Generate transaction ID that includes appointmentId for tracking
    final transactionId = "APT_${orderId}_${DateTime.now().millisecondsSinceEpoch}";
    final formattedPhone = _formatPhoneNumber(phoneNumber);

    final body = {
      "name": name,
      "email": validEmail,
      "phone": formattedPhone,
      "amount": amount.toInt(),
      "transaction_id": transactionId,
      "address": "Tanzania",
      "postcode": "00000",
      "callback_url": _webhookUrl,
    };

    try {
      log.i('💳 Initiating USSD Payment for Appointment');
      log.i('   Appointment ID: $orderId');
      log.i('   Transaction ID: $transactionId');
      log.i('   Amount: TZS ${amount.toInt()}');
      log.i('   Phone: $formattedPhone');
      log.d('📤 Request body: ${jsonEncode(body)}');

      final response = await http.post(
        url,
        headers: {
          'Authorization': 'Bearer $_apiToken',
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        body: jsonEncode(body),
      );

      log.i('📥 Payment Response Status: ${response.statusCode}');
      log.d('📥 Payment Response Body: ${response.body}');

      // Accept 2xx range
      if (response.statusCode >= 200 && response.statusCode < 300) {
        final data = jsonDecode(response.body);

        final gatewayOrderId = data['order_id'];
        if (gatewayOrderId != null) {
          log.i('✅ USSD Payment initiated successfully');
          log.i('   Gateway Order ID: $gatewayOrderId');

          // 🔥 FIX: Create transaction document with userId field
          // This is REQUIRED for Firestore rules to work
          if (userId != null && userId.isNotEmpty) {
            try {
              log.i('📝 Creating appointment payment transaction document...');
              await _firestore.collection('transactions').doc(transactionId).set({
                'type': 'appointment_payment',
                'status': 'pending',
                'appointmentId': orderId,
                'gatewayOrderId': gatewayOrderId,
                'userId': userId, // 🔥 CRITICAL: Must match request.auth.uid
                'amount': amount,
                'phoneNumber': formattedPhone,
                'paymentMethod': 'ussd_push',
                'createdAt': FieldValue.serverTimestamp(),
              });
              log.i('✅ Transaction document created: $transactionId');
            } catch (firestoreError, stackTrace) {
              log.e('❌ Failed to create transaction document',
                  error: firestoreError, stackTrace: stackTrace);
              // Continue anyway - the payment was initiated
            }
          } else {
            log.w('⚠️ No userId provided - cannot create transaction document');
          }

          return {
            'success': true,
            'message': data['message'] ?? 'Payment request sent. Check your phone.',
            'transactionId': transactionId,
            'gatewayOrderId': gatewayOrderId,
            'appointmentId': orderId,
            'data': data,
          };
        }

        final errorMsg = data['message'] ?? 'Unknown error from gateway';
        return {
          'success': false,
          'message': errorMsg,
          'appointmentId': orderId,
        };
      } else {
        log.e('❌ Payment failed with status: ${response.statusCode}');
        String errorMsg = 'Payment failed with status ${response.statusCode}';
        try {
          final errorData = jsonDecode(response.body);
          errorMsg = errorData['message'] ?? errorData['error'] ?? errorMsg;
        } catch (_) {}

        return {
          'success': false,
          'message': errorMsg,
          'appointmentId': orderId,
        };
      }
    } catch (e, stackTrace) {
      log.e('❌ Error initiating payment', error: e, stackTrace: stackTrace);
      return {
        'success': false,
        'message': 'Connection error: ${e.toString()}',
        'appointmentId': orderId,
      };
    }
  }

  // ==========================================
  // 🔧 HELPER METHODS
  // ==========================================

  String _formatPhoneNumber(String phone) {
    String cleaned = phone.replaceAll(RegExp(r'[^\d]'), '');

    if (cleaned.startsWith('+')) {
      cleaned = cleaned.substring(1);
    }

    if (cleaned.startsWith('0')) {
      cleaned = '255${cleaned.substring(1)}';
    }

    if (cleaned.length == 9) {
      cleaned = '255$cleaned';
    }

    if (!cleaned.startsWith('255')) {
      cleaned = '255$cleaned';
    }

    return cleaned;
  }
}

import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:pendeza/app/utils/logger.dart';
import '../../shared/models/promotion_model.dart';

/// Service to handle fetching and managing the 3-Tier Promotions.
///
/// Tiers:
/// 1. Platform-wide promotions (Admin controlled)
/// 2. Salon-specific promotions (Owner controlled)
/// 3. Featured/Paid promotions (Priority display)
class PromotionsService {
  final FirebaseFirestore _db = FirebaseFirestore.instance;

  /// Fetch all active Platform Promotions.
  /// These are global promos created by Pendeza admins (e.g., "Black Friday").
  Future<List<PromotionModel>> getPlatformPromotions() async {
    try {
      final now = Timestamp.now();

      final snapshot = await _db.collection('promotions')
          .where('isActive', isEqualTo: true)
          .where('endDate', isGreaterThan: now)
          .orderBy('endDate') // Required for inequality filter
          .get();

      final promotions = snapshot.docs
          .map((doc) => PromotionModel.fromFirestore(doc))
          .toList();

      // Sort by priority (High to Low)
      promotions.sort((a, b) => b.priority.compareTo(a.priority));

      return promotions;
    } catch (e, s) {
      log.e('Error fetching platform promotions', error: e, stackTrace: s);
      return [];
    }
  }

  /// Fetch active promotions for a specific salon.
  /// Used on the Salon Detail page.
  Future<List<PromotionModel>> getSalonPromotions(String salonId) async {
    try {
      final now = Timestamp.now();

      final snapshot = await _db
          .collection('salons')
          .doc(salonId)
          .collection('promotions')
          .where('isActive', isEqualTo: true)
          .where('endDate', isGreaterThan: now)
          .get();

      return snapshot.docs
          .map((doc) => PromotionModel.fromFirestore(doc, salonId: salonId))
          .toList();
    } catch (e, s) {
      log.e('Error fetching salon promotions for $salonId', error: e, stackTrace: s);
      return [];
    }
  }

  /// Fetch ALL active promotions for the Main Dashboard Carousel.
  ///
  /// Strategy:
  /// 1. Fetch Platform promos (Always show)
  /// 2. Fetch "Featured" salon promos (Paid tier only) using collectionGroup
  /// 3. Combine and sort
  Future<List<PromotionModel>> getDashboardPromotions() async {
    try {
      // 1. Get Platform Promos
      final platformPromos = await getPlatformPromotions();

      // 2. Get Featured Salon Promos (Collection Group Query)
      // This searches ALL 'promotions' subcollections across ALL salons
      final now = Timestamp.now();

      final featuredSnapshot = await _db.collectionGroup('promotions')
          .where('isFeatured', isEqualTo: true)
          .where('isActive', isEqualTo: true)
          .where('endDate', isGreaterThan: now)
          .limit(10) // Limit to keep dashboard performance high
          .get();

      final featuredSalonPromos = featuredSnapshot.docs.map((doc) {
        // Try to get salonId from parent path
        final parentPath = doc.reference.parent.parent?.id;
        return PromotionModel.fromFirestore(doc, salonId: parentPath);
      }).toList();

      // 3. Combine lists
      final allPromos = [...platformPromos, ...featuredSalonPromos];

      // 4. Sort Logic:
      // - Platform High Priority (>0)
      // - Featured Salon Promos
      // - Platform Standard Priority (0)
      allPromos.sort((a, b) {
        if (a.isPlatformPromo && a.priority > 0 && !b.isPlatformPromo) return -1;
        if (b.isPlatformPromo && b.priority > 0 && !a.isPlatformPromo) return 1;

        // Default sort by priority field
        return b.priority.compareTo(a.priority);
      });

      return allPromos;
    } catch (e, s) {
      log.e('Error fetching dashboard promotions', error: e, stackTrace: s);
      // Fallback: return empty list so UI doesn't crash
      return [];
    }
  }
}

