/// Temporary service to seed salon video data for development/testing
///
/// This version uses REAL Firebase Storage video URLs uploaded by the developer
/// DELETE THIS FILE before production release!
class VideoDataSeederService {
  final FirebaseFirestore _firestore;

  VideoDataSeederService({FirebaseFirestore? firestore})
      : _firestore = firestore ?? FirebaseFirestore.instance;

  /// Seed all salon videos from the mega data
  /// Returns the number of videos uploaded
  Future<int> seedSalonVideos() async {
    try {
      debugPrint('🚀 [VideoSeeder] Starting video data seed...');

      final batch = _firestore.batch();
      int count = 0;

      for (final videoData in _salonVideosMegaData) {
        final docRef = _firestore.collection('salon_videos').doc(videoData['id']);

        batch.set(docRef, {
          'salonId': videoData['salonId'],
          'salonName': videoData['salonName'],
          'salonImage': videoData['salonImage'],
          'salonAddress': videoData['salonAddress'],
          'videoUrl': videoData['videoUrl'],
          'thumbnailUrl': videoData['thumbnailUrl'],
          'caption': videoData['caption'],
          'durationSeconds': videoData['durationSeconds'],
          'status': videoData['status'],
          'ownerId': videoData['ownerId'],
          'createdAt': Timestamp.fromDate(DateTime.parse(videoData['createdAt'])),
        });

        count++;
      }

      await batch.commit();
      debugPrint('✅ [VideoSeeder] Successfully seeded $count videos!');
      return count;

    } catch (e, stack) {
      debugPrint('❌ [VideoSeeder] Error seeding videos: $e');
      debugPrint('Stack: $stack');
      rethrow;
    }
  }

  /// Delete all seeded videos (for cleanup)
  Future<int> deleteAllSeededVideos() async {
    try {
      debugPrint('🗑️ [VideoSeeder] Deleting all seeded videos...');

      final snapshot = await _firestore.collection('salon_videos').get();
      final batch = _firestore.batch();

      for (final doc in snapshot.docs) {
        batch.delete(doc.reference);
      }

      await batch.commit();
      debugPrint('✅ [VideoSeeder] Deleted ${snapshot.docs.length} videos');
      return snapshot.docs.length;

    } catch (e) {
      debugPrint('❌ [VideoSeeder] Error deleting videos: $e');
      rethrow;
    }
  }

