    this.trailing,
    this.actions,
    this.automaticallyImplyLeading = true,
    this.backgroundColor,
    this.foregroundColor,
    this.expandedHeight,
    this.collapsedHeight,
    this.pinned = true,
    this.floating = false,
    this.snap = false,
    this.stretch = false,
    this.flexibleSpace,
    this.largeTitle = false,
  });

  final String title;
  final Widget? leading;
  final Widget? trailing;
  final List<Widget>? actions;
  final bool automaticallyImplyLeading;
  final Color? backgroundColor;
  final Color? foregroundColor;
  final double? expandedHeight;
  final double? collapsedHeight;
  final bool pinned;
  final bool floating;
  final bool snap;
  final bool stretch;
  final Widget? flexibleSpace;
  final bool largeTitle;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final bgColor = backgroundColor ??
        (isDark ? AppColors.darkSurface : AppColors.primary);
    final fgColor = foregroundColor ??
        (isDark ? AppColors.darkTextPrimary : Colors.white);

    final effectiveActions = <Widget>[
      if (trailing != null) trailing!,
      if (actions != null) ...actions!,
    ];

    if (PlatformConfig.useCupertino) {
      return CupertinoSliverNavigationBar(
        largeTitle: Text(
          title,
          style: TextStyle(color: fgColor),
        ),
        leading: leading,
        trailing: effectiveActions.isNotEmpty
            ? Row(mainAxisSize: MainAxisSize.min, children: effectiveActions)
            : null,
        automaticallyImplyLeading: automaticallyImplyLeading,
        backgroundColor: bgColor,
        border: Border(
          bottom: BorderSide(
            color: isDark ? AppColors.darkBorder : AppColors.border,
            width: 0.5,
          ),
        ),
        stretch: stretch,
      );
    }

    return SliverAppBar(
      title: Text(title),
      leading: leading,
      actions: effectiveActions.isNotEmpty ? effectiveActions : null,
      automaticallyImplyLeading: automaticallyImplyLeading,
      backgroundColor: bgColor,
      foregroundColor: fgColor,
      expandedHeight: expandedHeight,
      collapsedHeight: collapsedHeight,
      pinned: pinned,
      floating: floating,
      snap: snap,
      stretch: stretch,
      flexibleSpace: flexibleSpace,
      elevation: 1,
      centerTitle: true,
    );
  }
}

