/// A platform-adaptive elevated/filled button.
/// Uses ElevatedButton on Android and CupertinoButton.filled on iOS.
class AdaptiveButton extends StatelessWidget {
  const AdaptiveButton({
    super.key,
    required this.onPressed,
    required this.child,
    this.color,
    this.disabledColor,
    this.textColor,
    this.padding,
    this.borderRadius,
    this.isLoading = false,
    this.isExpanded = false,
  });

  /// Called when the button is pressed
  final VoidCallback? onPressed;

  /// Button content (usually Text widget)
  final Widget child;

  /// Background color of the button
  final Color? color;

  /// Background color when disabled
  final Color? disabledColor;

  /// Text/icon color
  final Color? textColor;

  /// Button padding
  final EdgeInsets? padding;

  /// Border radius
  final BorderRadius? borderRadius;

  /// Show loading indicator instead of child
  final bool isLoading;

  /// Expand to fill available width
  final bool isExpanded;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final bgColor = color ?? (isDark ? AppColors.accent2 : AppColors.accent);
    final fgColor = textColor ?? AppColors.textPrimary;
    final effectivePadding =
        padding ?? AdaptiveTheme.adaptiveButtonPadding;
    final effectiveRadius =
        borderRadius ?? AdaptiveTheme.adaptiveButtonRadius;

    final buttonChild = isLoading
        ? SizedBox(
            height: 20,
            width: 20,
            child: PlatformConfig.useCupertino
                ? const CupertinoActivityIndicator(color: Colors.white)
                : CircularProgressIndicator(
                    strokeWidth: 2,
                    valueColor: AlwaysStoppedAnimation<Color>(fgColor),
                  ),
          )
        : child;

    Widget button = PlatformElevatedButton(
      onPressed: isLoading ? null : onPressed,
      padding: effectivePadding,
      color: bgColor,
      child: DefaultTextStyle(
        style: TextStyle(
          color: fgColor,
          fontSize: 16,
          fontWeight: FontWeight.w600,
          fontFamily: 'Poppins',
        ),
        child: buttonChild,
      ),
      material: (_, __) => MaterialElevatedButtonData(
        style: ElevatedButton.styleFrom(
          backgroundColor: bgColor,
          foregroundColor: fgColor,
          disabledBackgroundColor:
              disabledColor ?? bgColor.withAlpha(128),
          padding: effectivePadding,
          elevation: 4,
          shadowColor: bgColor.withAlpha(77),
          shape: RoundedRectangleBorder(borderRadius: effectiveRadius),
        ),
      ),
      cupertino: (_, __) => CupertinoElevatedButtonData(
        color: bgColor,
        disabledColor: disabledColor ?? bgColor.withAlpha(128),
        padding: effectivePadding,
        borderRadius: effectiveRadius,
      ),
    );

    if (isExpanded) {
      button = SizedBox(width: double.infinity, child: button);
    }

    return button;
  }
}

