/// A platform-adaptive outlined button.
/// Uses OutlinedButton on Android and bordered CupertinoButton on iOS.
class AdaptiveOutlinedButton extends StatelessWidget {
  const AdaptiveOutlinedButton({
    super.key,
    required this.onPressed,
    required this.child,
    this.color,
    this.borderColor,
    this.padding,
    this.borderRadius,
    this.isExpanded = false,
  });

  final VoidCallback? onPressed;
  final Widget child;
  final Color? color;
  final Color? borderColor;
  final EdgeInsets? padding;
  final BorderRadius? borderRadius;
  final bool isExpanded;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final textColor =
        color ?? (isDark ? AppColors.primaryLight : AppColors.primary);
    final effectiveBorderColor = borderColor ?? textColor;
    final effectivePadding =
        padding ?? AdaptiveTheme.adaptiveButtonPadding;
    final effectiveRadius =
        borderRadius ?? AdaptiveTheme.adaptiveButtonRadius;

    Widget button;

    if (PlatformConfig.useCupertino) {
      button = CupertinoButton(
        onPressed: onPressed,
        padding: effectivePadding,
        color: Colors.transparent,
        child: DefaultTextStyle(
          style: TextStyle(
            color: textColor,
            fontSize: 16,
            fontWeight: FontWeight.w600,
            fontFamily: 'Poppins',
          ),
          child: child,
        ),
      );
      button = Container(
        decoration: BoxDecoration(
          border: Border.all(color: effectiveBorderColor, width: 1.5),
          borderRadius: effectiveRadius,
        ),
        child: ClipRRect(
          borderRadius: effectiveRadius,
          child: button,
        ),
      );
    } else {
      button = OutlinedButton(
        onPressed: onPressed,
        style: OutlinedButton.styleFrom(
          foregroundColor: textColor,
          padding: effectivePadding,
          side: BorderSide(color: effectiveBorderColor, width: 1.5),
          shape: RoundedRectangleBorder(borderRadius: effectiveRadius),
        ),
        child: DefaultTextStyle(
          style: TextStyle(
            color: textColor,
            fontSize: 16,
            fontWeight: FontWeight.w600,
            fontFamily: 'Poppins',
          ),
          child: child,
        ),
      );
    }

    if (isExpanded) {
      button = SizedBox(width: double.infinity, child: button);
    }

    return button;
  }
}

