/// A floating action button that adapts to platform
class AdaptiveFloatingActionButton extends StatelessWidget {
  const AdaptiveFloatingActionButton({
    super.key,
    required this.onPressed,
    required this.icon,
    this.label,
    this.backgroundColor,
    this.foregroundColor,
    this.heroTag,
    this.mini = false,
    this.extended = false,
  });

  final VoidCallback? onPressed;
  final IconData icon;
  final String? label;
  final Color? backgroundColor;
  final Color? foregroundColor;
  final Object? heroTag;
  final bool mini;
  final bool extended;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final bgColor = backgroundColor ??
        (isDark ? AppColors.accent2 : AppColors.accent);
    final fgColor = foregroundColor ?? AppColors.textPrimary;

    // On iOS, we still use a Material FAB but with subtle styling
    if (extended && label != null) {
      return FloatingActionButton.extended(
        onPressed: onPressed,
        icon: Icon(icon, color: fgColor),
        label: Text(
          label!,
          style: TextStyle(color: fgColor, fontWeight: FontWeight.w600),
        ),
        backgroundColor: bgColor,
        elevation: PlatformConfig.useCupertino ? 2 : 6,
        heroTag: heroTag,
      );
    }

    return FloatingActionButton(
      onPressed: onPressed,
      backgroundColor: bgColor,
      foregroundColor: fgColor,
      elevation: PlatformConfig.useCupertino ? 2 : 6,
      mini: mini,
      heroTag: heroTag,
      child: Icon(icon),
    );
  }
}

import 'package:flutter/cupertino.dart';
import 'package:flutter/material.dart';
import 'package:flutter_platform_widgets/flutter_platform_widgets.dart';

import 'package:pendeza/app/config/platform_config.dart';
import 'package:pendeza/app/config/theme/app_colors.dart';
import 'package:pendeza/app/config/theme/adaptive_theme.dart';

/// Shows a platform-adaptive alert dialog.
/// Uses AlertDialog on Android and CupertinoAlertDialog on iOS.
Future<T?> showAdaptiveDialog<T>({
  required BuildContext context,
  required String title,
  String? content,
  Widget? contentWidget,
  String? confirmText,
  String? cancelText,
  VoidCallback? onConfirm,
  VoidCallback? onCancel,
  bool barrierDismissible = true,
  bool isDestructive = false,
}) {
  return showPlatformDialog<T>(
    context: context,
    barrierDismissible: barrierDismissible,
    builder: (context) => AdaptiveAlertDialog(
      title: title,
      content: content,
      contentWidget: contentWidget,
      confirmText: confirmText,
      cancelText: cancelText,
      onConfirm: onConfirm,
      onCancel: onCancel,
      isDestructive: isDestructive,
    ),
  );
}

/// Shows a platform-adaptive confirmation dialog with Yes/No options.
Future<bool> showAdaptiveConfirmDialog({
  required BuildContext context,
  required String title,
  String? content,
  String confirmText = 'Yes',
  String cancelText = 'No',
  bool isDestructive = false,
}) async {
  final result = await showAdaptiveDialog<bool>(
    context: context,
    title: title,
    content: content,
    confirmText: confirmText,
    cancelText: cancelText,
    isDestructive: isDestructive,
  );
  return result ?? false;
}

/// Shows a platform-adaptive delete confirmation dialog.
Future<bool> showAdaptiveDeleteDialog({
  required BuildContext context,
  String title = 'Delete',
  String content = 'Are you sure you want to delete this item? This action cannot be undone.',
}) {
  return showAdaptiveConfirmDialog(
    context: context,
    title: title,
    content: content,
    confirmText: 'Delete',
    cancelText: 'Cancel',
    isDestructive: true,
  );
}

/// A platform-adaptive alert dialog widget.
class AdaptiveAlertDialog extends StatelessWidget {
  const AdaptiveAlertDialog({
    super.key,
    required this.title,
    this.content,
    this.contentWidget,
    this.confirmText,
    this.cancelText,
    this.onConfirm,
    this.onCancel,
    this.isDestructive = false,
  });

  final String title;
  final String? content;
  final Widget? contentWidget;
  final String? confirmText;
  final String? cancelText;
  final VoidCallback? onConfirm;
  final VoidCallback? onCancel;
  final bool isDestructive;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;

    final List<Widget> actions = [];

    if (cancelText != null || onCancel != null) {
      actions.add(
        PlatformDialogAction(
          onPressed: onCancel ?? () => Navigator.of(context).pop(),
          child: Text(cancelText ?? 'Cancel'),
          material: (_, __) => MaterialDialogActionData(
            style: TextButton.styleFrom(
              foregroundColor:
                  isDark ? AppColors.darkTextSecondary : AppColors.textSecondary,
            ),
          ),
          cupertino: (_, __) => CupertinoDialogActionData(
            isDefaultAction: !isDestructive,
          ),
        ),
      );
    }

    if (confirmText != null || onConfirm != null) {
      actions.add(
        PlatformDialogAction(
          onPressed: onConfirm ?? () => Navigator.of(context).pop(true),
          child: Text(confirmText ?? 'OK'),
          material: (_, __) => MaterialDialogActionData(
            style: TextButton.styleFrom(
              foregroundColor: isDestructive
                  ? AppColors.error
                  : (isDark ? AppColors.primaryLight : AppColors.primary),
            ),
          ),
          cupertino: (_, __) => CupertinoDialogActionData(
            isDestructiveAction: isDestructive,
            isDefaultAction: !isDestructive && cancelText == null,
          ),
        ),
      );
    }

    // If no actions specified, add default OK button
    if (actions.isEmpty) {
      actions.add(
        PlatformDialogAction(
          onPressed: () => Navigator.of(context).pop(),
          child: const Text('OK'),
          cupertino: (_, __) => CupertinoDialogActionData(
            isDefaultAction: true,
          ),
        ),
      );
    }

    return PlatformAlertDialog(
      title: Text(title),
      content: contentWidget ?? (content != null ? Text(content!) : null),
      actions: actions,
      material: (_, __) => MaterialAlertDialogData(
        backgroundColor: isDark ? AppColors.darkSurface : AppColors.surface,
        titleTextStyle: TextStyle(
          color: isDark ? AppColors.darkTextPrimary : AppColors.textPrimary,
          fontSize: 20,
          fontWeight: FontWeight.w600,
          fontFamily: 'Poppins',
        ),
        contentTextStyle: TextStyle(
          color: isDark ? AppColors.darkTextSecondary : AppColors.textSecondary,
          fontSize: 16,
          fontFamily: 'Poppins',
        ),
        shape: RoundedRectangleBorder(
          borderRadius: AdaptiveTheme.adaptiveCardRadius,
        ),
      ),
      cupertino: (_, __) => CupertinoAlertDialogData(),
    );
  }
}

/// Shows a platform-adaptive action sheet (bottom sheet on Android).
Future<T?> showAdaptiveActionSheet<T>({
  required BuildContext context,
  String? title,
  String? message,
  required List<AdaptiveSheetAction<T>> actions,
  AdaptiveSheetAction<T>? cancelAction,
}) {
  if (PlatformConfig.useCupertino) {
    return showCupertinoModalPopup<T>(
      context: context,
      builder: (context) => CupertinoActionSheet(
        title: title != null ? Text(title) : null,
        message: message != null ? Text(message) : null,
        actions: actions
            .map((action) => CupertinoActionSheetAction(
                  onPressed: () {
                    Navigator.of(context).pop(action.value);
                    action.onPressed?.call();
                  },
                  isDefaultAction: action.isDefault,
                  isDestructiveAction: action.isDestructive,
                  child: Text(action.label),
                ))
            .toList(),
        cancelButton: cancelAction != null
            ? CupertinoActionSheetAction(
                onPressed: () {
                  Navigator.of(context).pop(cancelAction.value);
                  cancelAction.onPressed?.call();
                },
                isDefaultAction: cancelAction.isDefault,
                child: Text(cancelAction.label),
              )
            : CupertinoActionSheetAction(
                onPressed: () => Navigator.of(context).pop(),
                child: const Text('Cancel'),
              ),
      ),
    );
  }

  // Material bottom sheet
  return showModalBottomSheet<T>(
    context: context,
    backgroundColor: Colors.transparent,
    builder: (context) {
      final isDark = Theme.of(context).brightness == Brightness.dark;
      return Container(
        decoration: BoxDecoration(
          color: isDark ? AppColors.darkSurface : AppColors.surface,
          borderRadius: const BorderRadius.vertical(top: Radius.circular(20)),
        ),
        child: SafeArea(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              // Handle bar
              Container(
                width: 40,
                height: 4,
                margin: const EdgeInsets.symmetric(vertical: 12),
                decoration: BoxDecoration(
                  color: isDark ? AppColors.darkBorder : AppColors.border,
                  borderRadius: BorderRadius.circular(2),
                ),
              ),
              // Title
              if (title != null)
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
                  child: Text(
                    title,
                    style: TextStyle(
                      color: isDark
                          ? AppColors.darkTextPrimary
                          : AppColors.textPrimary,
                      fontSize: 18,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ),
              // Message
              if (message != null)
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),
                  child: Text(
                    message,
                    style: TextStyle(
                      color: isDark
                          ? AppColors.darkTextSecondary
                          : AppColors.textSecondary,
                      fontSize: 14,
                    ),
                    textAlign: TextAlign.center,
                  ),
                ),
              const SizedBox(height: 8),
              // Actions
              ...actions.map((action) => ListTile(
                    onTap: () {
                      Navigator.of(context).pop(action.value);
                      action.onPressed?.call();
                    },
                    leading: action.icon != null
                        ? Icon(
                            action.icon,
                            color: action.isDestructive
                                ? AppColors.error
                                : (isDark
                                    ? AppColors.darkTextPrimary
                                    : AppColors.textPrimary),
                          )
                        : null,
                    title: Text(
                      action.label,
                      style: TextStyle(
                        color: action.isDestructive
                            ? AppColors.error
                            : (isDark
                                ? AppColors.darkTextPrimary
                                : AppColors.textPrimary),
                        fontWeight:
                            action.isDefault ? FontWeight.w600 : FontWeight.w500,
                      ),
                    ),
                  )),
              // Cancel
              if (cancelAction != null)
                ListTile(
                  onTap: () {
                    Navigator.of(context).pop(cancelAction.value);
                    cancelAction.onPressed?.call();
                  },
                  title: Text(
                    cancelAction.label,
                    style: TextStyle(
                      color: isDark
                          ? AppColors.darkTextSecondary
                          : AppColors.textSecondary,
                    ),
                    textAlign: TextAlign.center,
                  ),
                ),
              const SizedBox(height: 8),
            ],
          ),
        ),
      );
    },
  );
}

/// Represents an action in an adaptive action sheet.
class AdaptiveSheetAction<T> {
  const AdaptiveSheetAction({
    required this.label,
    this.value,
    this.icon,
    this.onPressed,
    this.isDefault = false,
    this.isDestructive = false,
  });

  final String label;
  final T? value;
  final IconData? icon;
  final VoidCallback? onPressed;
  final bool isDefault;
  final bool isDestructive;
}

/// Shows a platform-adaptive loading dialog.
Future<void> showAdaptiveLoadingDialog({
  required BuildContext context,
  String? message,
  bool barrierDismissible = false,
}) {
  return showPlatformDialog(
    context: context,
    barrierDismissible: barrierDismissible,
    builder: (context) => AdaptiveLoadingDialog(message: message),
  );
}

/// A platform-adaptive loading dialog widget.
class AdaptiveLoadingDialog extends StatelessWidget {
  const AdaptiveLoadingDialog({
    super.key,
    this.message,
  });

  final String? message;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;

    if (PlatformConfig.useCupertino) {
      return CupertinoAlertDialog(
        content: Padding(
          padding: const EdgeInsets.all(16),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const CupertinoActivityIndicator(radius: 14),
              if (message != null) ...[
                const SizedBox(height: 16),
                Text(message!),
              ],
            ],
          ),
        ),
      );
    }

    return AlertDialog(
      backgroundColor: isDark ? AppColors.darkSurface : AppColors.surface,
      shape: RoundedRectangleBorder(
        borderRadius: AdaptiveTheme.adaptiveCardRadius,
      ),
      content: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            CircularProgressIndicator(
              valueColor: AlwaysStoppedAnimation<Color>(
                isDark ? AppColors.primaryLight : AppColors.primary,
              ),
            ),
            if (message != null) ...[
              const SizedBox(height: 16),
              Text(
                message!,
                style: TextStyle(
                  color: isDark
                      ? AppColors.darkTextPrimary
                      : AppColors.textPrimary,
                ),
              ),
            ],
          ],
        ),
      ),
    );
  }
}

/// Shows a platform-adaptive snackbar/toast.
void showAdaptiveSnackBar({
  required BuildContext context,
  required String message,
  Duration duration = const Duration(seconds: 3),
  SnackBarAction? action,
  Color? backgroundColor,
  bool isError = false,
  bool isSuccess = false,
}) {
  final isDark = Theme.of(context).brightness == Brightness.dark;

  Color bgColor;
  if (backgroundColor != null) {
    bgColor = backgroundColor;
  } else if (isError) {
    bgColor = AppColors.error;
  } else if (isSuccess) {
    bgColor = AppColors.success;
  } else {
    bgColor = isDark ? AppColors.darkSurfaceVariant : AppColors.textPrimary;
  }

  final textColor = (isError || isSuccess || !isDark)
      ? Colors.white
      : AppColors.darkTextPrimary;

  if (PlatformConfig.useCupertino) {
    // Show a Cupertino-style overlay notification
    _showCupertinoToast(
      context: context,
      message: message,
      duration: duration,
      backgroundColor: bgColor,
      textColor: textColor,
    );
  } else {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(message, style: TextStyle(color: textColor)),
        duration: duration,
        backgroundColor: bgColor,
        action: action,
        behavior: SnackBarBehavior.floating,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(8),
        ),
      ),
    );
  }
}

void _showCupertinoToast({
  required BuildContext context,
  required String message,
  required Duration duration,
  required Color backgroundColor,
  required Color textColor,
}) {
  final overlay = Overlay.of(context);
  late OverlayEntry entry;

  entry = OverlayEntry(
    builder: (context) => Positioned(
      bottom: MediaQuery.of(context).padding.bottom + 60,
      left: 16,
      right: 16,
      child: Material(
        color: Colors.transparent,
        child: TweenAnimationBuilder<double>(
          tween: Tween(begin: 0.0, end: 1.0),
          duration: const Duration(milliseconds: 200),
          builder: (context, value, child) => Opacity(
            opacity: value,
            child: Transform.translate(
              offset: Offset(0, 20 * (1 - value)),
              child: child,
            ),
          ),
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
            decoration: BoxDecoration(
              color: backgroundColor,
              borderRadius: BorderRadius.circular(10),
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withAlpha(51),
                  blurRadius: 10,
                  offset: const Offset(0, 4),
                ),
              ],
            ),
            child: Text(
              message,
              style: TextStyle(
                color: textColor,
                fontSize: 14,
                fontWeight: FontWeight.w500,
              ),
              textAlign: TextAlign.center,
            ),
          ),
        ),
      ),
    ),
  );

  overlay.insert(entry);

  Future.delayed(duration, () {
    entry.remove();
  });
}

import 'package:flutter/cupertino.dart';
import 'package:flutter/material.dart';
import 'package:flutter_platform_widgets/flutter_platform_widgets.dart';

import 'package:pendeza/app/config/platform_config.dart';
import 'package:pendeza/app/config/theme/app_colors.dart';
import 'package:pendeza/app/widgets/adaptive/adaptive_app_bar.dart';

/// A platform-adaptive scaffold that uses Material Scaffold on Android
/// and CupertinoPageScaffold on iOS.
class AdaptiveScaffold extends StatelessWidget {
  const AdaptiveScaffold({
    super.key,
    this.appBar,
    this.title,
    this.leading,
    this.trailing,
    this.automaticallyImplyLeading = true,
    required this.body,
    this.floatingActionButton,
    this.floatingActionButtonLocation,
    this.bottomNavigationBar,
    this.backgroundColor,
    this.resizeToAvoidBottomInset = true,
    this.extendBodyBehindAppBar = false,
    this.extendBody = false,
  });

  /// Custom app bar widget. If provided, [title], [leading], and [trailing] are ignored.
  final PreferredSizeWidget? appBar;

  /// Title for the app bar (used if [appBar] is null)
  final String? title;

  /// Leading widget for the app bar (used if [appBar] is null)
  final Widget? leading;

  /// Trailing widget(s) for the app bar (used if [appBar] is null)
  final Widget? trailing;

  /// Whether to automatically add a back button
  final bool automaticallyImplyLeading;

  /// The main content of the scaffold
  final Widget body;

  /// Floating action button (Material only, ignored on iOS)
  final Widget? floatingActionButton;

  /// FAB location (Material only)
  final FloatingActionButtonLocation? floatingActionButtonLocation;

  /// Bottom navigation bar
  final Widget? bottomNavigationBar;

  /// Background color of the scaffold
  final Color? backgroundColor;

  /// Whether to resize body when keyboard appears
  final bool resizeToAvoidBottomInset;

  /// Whether the body extends behind the app bar
  final bool extendBodyBehindAppBar;

  /// Whether the body extends to the bottom
  final bool extendBody;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final bgColor = backgroundColor ??
        (isDark ? AppColors.darkBackground : AppColors.background);

    // Build the app bar if title is provided and no custom appBar
    final effectiveAppBar = appBar ??
        (title != null
            ? AdaptiveAppBar(
                title: title!,
                leading: leading,
                trailing: trailing,
                automaticallyImplyLeading: automaticallyImplyLeading,
              )
            : null);

    return PlatformScaffold(
      appBar: effectiveAppBar != null
          ? PlatformAppBar(
              title: Text(title ?? ''),
              leading: leading,
              trailingActions: trailing != null ? [trailing!] : null,
              automaticallyImplyLeading: automaticallyImplyLeading,
              backgroundColor: isDark ? AppColors.darkSurface : AppColors.primary,
              material: (_, __) => MaterialAppBarData(
                elevation: 1,
                centerTitle: true,
              ),
              cupertino: (_, __) => CupertinoNavigationBarData(
                border: Border(
                  bottom: BorderSide(
                    color: isDark ? AppColors.darkBorder : AppColors.border,
                    width: 0.5,
                  ),
                ),
              ),
            )
          : null,
      body: body,
      backgroundColor: bgColor,
      material: (_, __) => MaterialScaffoldData(
        floatingActionButton: floatingActionButton,
        floatingActionButtonLocation: floatingActionButtonLocation,
        bottomNavBar: bottomNavigationBar,
        resizeToAvoidBottomInset: resizeToAvoidBottomInset,
        extendBodyBehindAppBar: extendBodyBehindAppBar,
        extendBody: extendBody,
      ),
      cupertino: (_, __) => CupertinoPageScaffoldData(
        resizeToAvoidBottomInset: resizeToAvoidBottomInset,
        navigationBar: effectiveAppBar != null
            ? CupertinoNavigationBar(
                middle: Text(
                  title ?? '',
                  style: TextStyle(
                    color: isDark ? AppColors.darkTextPrimary : Colors.white,
                  ),
                ),
                leading: leading,
                trailing: trailing,
                automaticallyImplyLeading: automaticallyImplyLeading,
                backgroundColor:
                    isDark ? AppColors.darkSurface : AppColors.primary,
                border: Border(
                  bottom: BorderSide(
                    color: isDark ? AppColors.darkBorder : AppColors.border,
                    width: 0.5,
                  ),
                ),
              )
            : null,
      ),
    );
  }
}

/// A simple adaptive scaffold without an app bar
class AdaptiveScaffoldBody extends StatelessWidget {
  const AdaptiveScaffoldBody({
    super.key,
    required this.child,
    this.backgroundColor,
    this.padding,
    this.safeArea = true,
  });

  final Widget child;
  final Color? backgroundColor;
  final EdgeInsets? padding;
  final bool safeArea;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final bgColor = backgroundColor ??
        (isDark ? AppColors.darkBackground : AppColors.background);

    Widget content = child;

    if (padding != null) {
      content = Padding(padding: padding!, child: content);
    }

    if (safeArea) {
      content = SafeArea(child: content);
    }

    if (PlatformConfig.useCupertino) {
      return CupertinoPageScaffold(
        backgroundColor: bgColor,
        child: content,
      );
    }

    return Scaffold(
      backgroundColor: bgColor,
      body: content,
    );
  }
}

import 'package:flutter/cupertino.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_platform_widgets/flutter_platform_widgets.dart';

import 'package:pendeza/app/config/platform_config.dart';
import 'package:pendeza/app/config/theme/app_colors.dart';
import 'package:pendeza/app/config/theme/adaptive_theme.dart';

/// A platform-adaptive text field.
/// Uses TextField with InputDecoration on Android and CupertinoTextField on iOS.
class AdaptiveTextField extends StatelessWidget {
  const AdaptiveTextField({
    super.key,
    this.controller,
    this.focusNode,
    this.labelText,
    this.hintText,
    this.helperText,
    this.errorText,
    this.prefixIcon,
    this.suffixIcon,
    this.prefix,
    this.suffix,
    this.obscureText = false,
    this.enabled = true,
    this.readOnly = false,
    this.autofocus = false,
    this.maxLines = 1,
    this.minLines,
    this.maxLength,
    this.keyboardType,
    this.textInputAction,
    this.textCapitalization = TextCapitalization.none,
    this.inputFormatters,
    this.onChanged,
    this.onSubmitted,
    this.onTap,
    this.validator,
    this.autovalidateMode,
    this.fillColor,
    this.borderColor,
    this.focusedBorderColor,
    this.borderRadius,
    this.contentPadding,
    this.style,
  });

  final TextEditingController? controller;
  final FocusNode? focusNode;
  final String? labelText;
  final String? hintText;
  final String? helperText;
  final String? errorText;
  final IconData? prefixIcon;
  final IconData? suffixIcon;
  final Widget? prefix;
  final Widget? suffix;
  final bool obscureText;
  final bool enabled;
  final bool readOnly;
  final bool autofocus;
  final int? maxLines;
  final int? minLines;
  final int? maxLength;
  final TextInputType? keyboardType;
  final TextInputAction? textInputAction;
  final TextCapitalization textCapitalization;
  final List<TextInputFormatter>? inputFormatters;
  final ValueChanged<String>? onChanged;
  final ValueChanged<String>? onSubmitted;
  final VoidCallback? onTap;
  final FormFieldValidator<String>? validator;
  final AutovalidateMode? autovalidateMode;
  final Color? fillColor;
  final Color? borderColor;
  final Color? focusedBorderColor;
  final BorderRadius? borderRadius;
  final EdgeInsets? contentPadding;
  final TextStyle? style;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final effectiveFillColor = fillColor ??
        (isDark ? AppColors.darkSurface : AppColors.surface);
    final effectiveBorderColor = borderColor ??
        (isDark ? AppColors.darkBorder : AppColors.border);
    final effectiveFocusedColor = focusedBorderColor ??
        (isDark ? AppColors.primaryLight : AppColors.primary);
    final effectiveRadius = borderRadius ?? AdaptiveTheme.adaptiveInputRadius;
    final effectivePadding = contentPadding ?? AdaptiveTheme.adaptiveCardPadding;

    final textColor = isDark ? AppColors.darkTextPrimary : AppColors.textPrimary;
    final hintColor = isDark ? AppColors.darkTextTertiary : AppColors.textLight;
    final labelColor = isDark ? AppColors.darkTextSecondary : AppColors.textSecondary;

    final effectiveStyle = style ?? TextStyle(
      color: textColor,
      fontSize: 16,
      fontFamily: 'Poppins',
    );

    // Build prefix widget
    Widget? effectivePrefix = prefix;
    if (prefixIcon != null && effectivePrefix == null) {
      effectivePrefix = Padding(
        padding: const EdgeInsets.only(left: 12, right: 8),
        child: Icon(
          prefixIcon,
          color: isDark ? AppColors.darkTextSecondary : AppColors.textSecondary,
          size: AdaptiveTheme.adaptiveIconSize,
        ),
      );
    }

    // Build suffix widget
    Widget? effectiveSuffix = suffix;
    if (suffixIcon != null && effectiveSuffix == null) {
      effectiveSuffix = Padding(
        padding: const EdgeInsets.only(right: 12, left: 8),
        child: Icon(
          suffixIcon,
          color: isDark ? AppColors.darkTextSecondary : AppColors.textSecondary,
          size: AdaptiveTheme.adaptiveIconSize,
        ),
      );
    }

    return PlatformTextFormField(
      controller: controller,
      focusNode: focusNode,
      obscureText: obscureText,
      enabled: enabled,
      readOnly: readOnly,
      autofocus: autofocus,
      maxLines: maxLines,
      minLines: minLines,
      maxLength: maxLength,
      keyboardType: keyboardType,
      textInputAction: textInputAction,
      textCapitalization: textCapitalization,
      inputFormatters: inputFormatters,
      onChanged: onChanged,
      onFieldSubmitted: onSubmitted,
      onTap: onTap,
      validator: validator,
      autovalidateMode: autovalidateMode,
      style: effectiveStyle,
      material: (_, _) => MaterialTextFormFieldData(
        decoration: InputDecoration(
          labelText: labelText,
          hintText: hintText,
          helperText: helperText,
          errorText: errorText,
          prefixIcon: prefixIcon != null
              ? Icon(prefixIcon, color: labelColor)
              : null,
          prefix: prefixIcon == null ? prefix : null,
          suffixIcon: suffixIcon != null
              ? Icon(suffixIcon, color: labelColor)
              : null,
          suffix: suffixIcon == null ? suffix : null,
          filled: true,
          fillColor: effectiveFillColor,
          labelStyle: TextStyle(color: labelColor, fontFamily: 'Poppins'),
          hintStyle: TextStyle(color: hintColor, fontFamily: 'Poppins'),
          helperStyle: TextStyle(color: labelColor, fontSize: 12, fontFamily: 'Poppins'),
          errorStyle: const TextStyle(color: AppColors.error, fontSize: 12, fontFamily: 'Poppins'),
          contentPadding: effectivePadding,
          border: OutlineInputBorder(
            borderRadius: effectiveRadius,
            borderSide: BorderSide.none,
          ),
          enabledBorder: OutlineInputBorder(
            borderRadius: effectiveRadius,
            borderSide: BorderSide(color: effectiveBorderColor),
          ),
          focusedBorder: OutlineInputBorder(
            borderRadius: effectiveRadius,
            borderSide: BorderSide(color: effectiveFocusedColor, width: 2),
          ),
          errorBorder: OutlineInputBorder(
            borderRadius: effectiveRadius,
            borderSide: const BorderSide(color: AppColors.error, width: 1.5),
          ),
          focusedErrorBorder: OutlineInputBorder(
            borderRadius: effectiveRadius,
            borderSide: const BorderSide(color: AppColors.error, width: 2),
          ),
          disabledBorder: OutlineInputBorder(
            borderRadius: effectiveRadius,
            borderSide: BorderSide(color: effectiveBorderColor.withAlpha(128)),
          ),
        ),
      ),
      cupertino: (_, _) => CupertinoTextFormFieldData(
        placeholder: hintText ?? labelText,
        prefix: effectivePrefix,
        padding: effectivePadding,
        placeholderStyle: TextStyle(color: hintColor, fontFamily: 'Poppins'),
        decoration: BoxDecoration(
          color: effectiveFillColor,
          borderRadius: effectiveRadius,
          border: Border.all(
            color: errorText != null ? AppColors.error : effectiveBorderColor,
            width: errorText != null ? 1.5 : 1,
          ),
        ),
      ),
    );
  }
}

/// A platform-adaptive search field with search icon and clear button.
class AdaptiveSearchField extends StatefulWidget {
  const AdaptiveSearchField({
    super.key,
    this.controller,
    this.focusNode,
    this.hintText = 'Search...',
    this.onChanged,
    this.onSubmitted,
    this.onClear,
    this.autofocus = false,
    this.enabled = true,
    this.backgroundColor,
    this.borderRadius,
  });

  final TextEditingController? controller;
  final FocusNode? focusNode;
  final String hintText;
  final ValueChanged<String>? onChanged;
  final ValueChanged<String>? onSubmitted;
  final VoidCallback? onClear;
  final bool autofocus;
  final bool enabled;
  final Color? backgroundColor;
  final BorderRadius? borderRadius;

  @override
  State<AdaptiveSearchField> createState() => _AdaptiveSearchFieldState();
}

class _AdaptiveSearchFieldState extends State<AdaptiveSearchField> {
  late TextEditingController _controller;
  bool _showClear = false;

  @override
  void initState() {
    super.initState();
    _controller = widget.controller ?? TextEditingController();
    _controller.addListener(_updateClearVisibility);
    _showClear = _controller.text.isNotEmpty;
  }

  @override
  void dispose() {
    if (widget.controller == null) {
      _controller.dispose();
    } else {
      _controller.removeListener(_updateClearVisibility);
    }
    super.dispose();
  }

  void _updateClearVisibility() {
    final shouldShow = _controller.text.isNotEmpty;
    if (shouldShow != _showClear) {
      setState(() => _showClear = shouldShow);
    }
  }

  void _handleClear() {
    _controller.clear();
    widget.onClear?.call();
    widget.onChanged?.call('');
  }

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final bgColor = widget.backgroundColor ??
        (isDark ? AppColors.darkSurface : AppColors.surface);
    final iconColor = isDark ? AppColors.darkTextSecondary : AppColors.textSecondary;
    final effectiveRadius = widget.borderRadius ?? BorderRadius.circular(12);

    if (PlatformConfig.useCupertino) {
      return CupertinoSearchTextField(
        controller: _controller,
        focusNode: widget.focusNode,
        placeholder: widget.hintText,
        onChanged: widget.onChanged,
        onSubmitted: widget.onSubmitted,
        autofocus: widget.autofocus,
        enabled: widget.enabled,
        backgroundColor: bgColor,
        borderRadius: effectiveRadius,
        prefixIcon: Icon(
          CupertinoIcons.search,
          color: iconColor,
        ),
        style: TextStyle(
          color: isDark ? AppColors.darkTextPrimary : AppColors.textPrimary,
          fontFamily: 'Poppins',
        ),
        placeholderStyle: TextStyle(
          color: isDark ? AppColors.darkTextTertiary : AppColors.textLight,
          fontFamily: 'Poppins',
        ),
      );
    }

    return TextField(
      controller: _controller,
      focusNode: widget.focusNode,
      autofocus: widget.autofocus,
      enabled: widget.enabled,
      onChanged: widget.onChanged,
      onSubmitted: widget.onSubmitted,
      style: TextStyle(
        color: isDark ? AppColors.darkTextPrimary : AppColors.textPrimary,
        fontFamily: 'Poppins',
      ),
      decoration: InputDecoration(
        hintText: widget.hintText,
        hintStyle: TextStyle(
          color: isDark ? AppColors.darkTextTertiary : AppColors.textLight,
          fontFamily: 'Poppins',
        ),
        filled: true,
        fillColor: bgColor,
        prefixIcon: Icon(Icons.search, color: iconColor),
        suffixIcon: _showClear
            ? IconButton(
                icon: Icon(Icons.clear, color: iconColor, size: 20),
