import 'features/2_client_appointments/presentation/bloc/appointments_bloc.dart';

/// ============================================================================
/// APP.DART - FIXED VERSION
/// ============================================================================
///
/// IMPORTANT: All BLoCs that need to persist across the app lifecycle should
/// be provided here using BlocProvider.value() for singletons.
///
/// KEY RULES:
/// 1. Singletons (registered with registerLazySingleton) → Use BlocProvider.value()
/// 2. Factories (registered with registerFactory) → Use BlocProvider(create: ...)
///
/// The WalletBloc and ProfileBloc are SINGLETONS, so we use .value() here.
/// This means NEVER create local BlocProviders for these in child widgets!
/// ============================================================================

class App extends StatelessWidget {
  const App({super.key});

  @override
  Widget build(BuildContext context) {
    return MultiProvider(
      providers: [
        // ====================================================================
        // STEP 1: Provide Services & Repositories FIRST
        // ====================================================================
        Provider<WalletService>.value(value: sl<WalletService>()),
        Provider<PaymentService>.value(value: sl<PaymentService>()),
        Provider<WalletRepository>.value(value: sl<WalletRepository>()),

        // ====================================================================
        // STEP 2: Provide BLoCs
        // ====================================================================

        // Theme Cubit - not a singleton, create fresh
        BlocProvider<ThemeCubit>(create: (context) => ThemeCubit()),

        // AuthBloc - SINGLETON (registered with registerLazySingleton)
        // Use .value() to avoid closing it when widgets dispose
        BlocProvider<AuthBloc>.value(value: sl<AuthBloc>()),

        // BookingBloc - FACTORY (registered with registerFactory)
        // Create new instance each time
        BlocProvider<BookingBloc>(create: (context) => sl<BookingBloc>()),

        // DiscoveryBloc - FACTORY
        BlocProvider<DiscoveryBloc>(create: (context) => sl<DiscoveryBloc>()),

        // FavoritesBloc - FACTORY
        BlocProvider<FavoritesBloc>(create: (context) => sl<FavoritesBloc>()),

        // AppointmentsBloc - FACTORY
        BlocProvider<AppointmentsBloc>(create: (context) => sl<AppointmentsBloc>()),

        // ================================================================
        // 🔥 ProfileBloc - SINGLETON (changed from FACTORY in service_locator)
        // Must use .value() to keep it alive across navigations
        // ================================================================
        BlocProvider<ProfileBloc>.value(value: sl<ProfileBloc>()),

        // ================================================================
        // 🔥 WalletBloc - SINGLETON
        // Must use .value() to keep it alive across navigations
        // ================================================================
        BlocProvider<WalletBloc>.value(value: sl<WalletBloc>()),

        // ================================================================
        // 🔔 NotificationBloc - SINGLETON
        // Tracks unread count and real-time notifications across the app
        // ================================================================
        BlocProvider<NotificationBloc>.value(value: sl<NotificationBloc>()),
      ],
      child: BlocBuilder<ThemeCubit, ThemeMode>(
        builder: (context, themeMode) {
          return PlatformProvider(
            settings: PlatformSettingsData(
              iosUsesMaterialWidgets: true,
              iosUseZeroPaddingForAppbarPlatformIcon: true,
            ),
            builder: (context) => PlatformTheme(
              themeMode: themeMode,
              materialLightTheme: AppTheme.lightTheme,
              materialDarkTheme: AppTheme.darkTheme,
              cupertinoLightTheme: AppTheme.cupertinoLightTheme,
              cupertinoDarkTheme: AppTheme.cupertinoDarkTheme,
              builder: (context) => PlatformApp.router(
                title: 'Pendeza App',
                debugShowCheckedModeBanner: false,
                routerConfig: AppRouter.router,
                localizationsDelegates: [
                  ...context.localizationDelegates,
                  GlobalMaterialLocalizations.delegate,
                  GlobalWidgetsLocalizations.delegate,
                  GlobalCupertinoLocalizations.delegate,
                  FlutterQuillLocalizations.delegate,
                ],
                supportedLocales: context.supportedLocales,
                locale: context.locale,
              ),
            ),
          );
        },
      ),
    );
  }
}

import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:equatable/equatable.dart';

/// An enumeration for user gender to ensure type safety.
enum Gender { male, female, other, preferNotToSay }

/// Extension to convert Gender enum to/from string
extension GenderExtension on Gender {
  String get value {
    switch (this) {
      case Gender.male:
        return 'male';
      case Gender.female:
        return 'female';
      case Gender.other:
        return 'other';
      case Gender.preferNotToSay:
        return 'prefer_not_to_say';
    }
  }

  static Gender fromString(String value) {
    switch (value.toLowerCase()) {
      case 'male':
        return Gender.male;
      case 'female':
        return Gender.female;
      case 'other':
        return Gender.other;
      case 'prefer_not_to_say':
        return Gender.preferNotToSay;
      default:
        return Gender.preferNotToSay;
    }
  }
}

/// The primary User entity for the application.
///
/// This class represents a single user's profile data, designed to be robust
/// and scalable. It includes methods for serialization/deserialization from
/// Firestore and supports immutable state updates.
///
/// NOW SUPPORTS GUEST MODE - Users can browse without authentication!
/// ENHANCED WITH USERNAME - Users have unique usernames for social features.
class UserModel extends Equatable {
  /// The unique identifier from FirebaseAuth. This is the document ID in Firestore.
  final String uid;

  /// The user's primary email address.
  final String email;

  /// The user's full name.
  final String fullName;

  /// **NEW**: The user's unique username (lowercase, no spaces).
  /// Used for mentions, profile URLs, and social features.
  final String? username;

  /// The user's phone number, may be null if signed up with email.
  final String? phoneNumber;

  /// The URL for the user's profile picture.
  final String? profilePictureUrl;

  /// The user's role ('client', 'owner', or 'admin'). Null if onboarding is not complete.
  final String? role;

  /// **NEW**: The user's selected gender for personalization.
  final Gender? gender;

  /// A list of Firebase Cloud Messaging (FCM) tokens for push notifications.
  /// A list is used to support a user being logged in on multiple devices.
  final List<String> fcmTokens;

  /// The timestamp when the user account was created.
  final DateTime createdAt;

  /// The timestamp of the last profile update.
  final DateTime? updatedAt;

  /// Whether this is a guest user (browsing without authentication)
  final bool isGuest;

  const UserModel({
    required this.uid,
    required this.email,
    required this.fullName,
    this.username,
    this.phoneNumber,
    this.profilePictureUrl,
    this.role,
    this.gender,
    required this.fcmTokens,
    required this.createdAt,
    this.updatedAt,
    this.isGuest = false, // Default to false for backward compatibility
  });

  /// Factory constructor to create a guest user for browsing
  factory UserModel.guest() {
    return UserModel(
      uid: 'guest_${DateTime.now().millisecondsSinceEpoch}',
      email: '',
      fullName: 'Guest',
      username: null,
      role: 'client', // Guests always browse as clients
      fcmTokens: [],
      createdAt: DateTime.now(),
      isGuest: true,
    );
  }

  /// A computed property to easily check if the user needs to select a role.
  bool get needsOnboarding => role == null && !isGuest;

  /// A computed property to check if the user is an admin.
  bool get isAdmin => role == 'admin' && !isGuest;

  /// A computed property to check if the user is authenticated (not a guest)
  bool get isAuthenticated => !isGuest;

  /// Check if user has all mandatory fields for client profile
  /// SIMPLIFIED: Only phone and gender required (username optional)
  bool get hasCompleteMandatoryFields {
    return phoneNumber != null &&
        phoneNumber!.isNotEmpty &&
        gender != null &&
        fullName.isNotEmpty &&
        fullName != 'New User';
  }

  /// Factory constructor to create a `UserModel` instance from a Firestore document.
  ///
  /// This method safely handles data extraction and type conversion, providing
  /// default values for missing fields to prevent runtime errors.
  factory UserModel.fromFirestore(DocumentSnapshot<Map<String, dynamic>> doc) {
    final data = doc.data() ?? {};
    return UserModel(
      uid: doc.id,
      email: data['email'] as String? ?? '',
      fullName: data['fullName'] as String? ?? '',
      username: data['username'] as String?, // NEW
      phoneNumber: data['phoneNumber'] as String?,
      profilePictureUrl: data['profilePictureUrl'] as String?,
      role: data['role'] as String?,
      // Safely handle the gender enum from a string in Firestore
      gender: data['gender'] != null
          ? GenderExtension.fromString(data['gender'] as String)
          : null,
      // Ensure fcmTokens is always a list of strings
      fcmTokens: List<String>.from(data['fcmTokens'] ?? []),
      // Safely convert Firestore Timestamp to DateTime
      createdAt: (data['createdAt'] as Timestamp? ?? Timestamp.now()).toDate(),
      updatedAt: (data['updatedAt'] as Timestamp?)?.toDate(),
      isGuest: false, // Firestore users are never guests
    );
  }

  /// Converts the `UserModel` instance into a `Map` for writing to Firestore.
  ///
  /// This method handles converting enums and DateTimes back to Firestore-compatible types.
  Map<String, dynamic> toFirestore() {
    return {
      // We don't write the uid to the document body, as it's the document ID.
      'email': email,
      'fullName': fullName,
      'username': username, // NEW
      'phoneNumber': phoneNumber,
      'profilePictureUrl': profilePictureUrl,
      'role': role,
      // Store the gender enum as a simple string
      'gender': gender?.value,
      'fcmTokens': fcmTokens,
      'createdAt': Timestamp.fromDate(createdAt),
      'updatedAt': updatedAt != null ? Timestamp.fromDate(updatedAt!) : null,
      // isGuest is never stored in Firestore - it's a client-only flag
    };
  }

  /// Creates a copy of the current `UserModel` instance with updated fields.
  ///
  /// This is essential for working with immutable state in BLoC, allowing for
  /// predictable state changes.
  UserModel copyWith({
    String? uid,
    String? email,
    String? fullName,
    String? username,
    String? phoneNumber,
    String? profilePictureUrl,
    String? role,
    Gender? gender,
    List<String>? fcmTokens,
    DateTime? createdAt,
    DateTime? updatedAt,
    bool? isGuest,
  }) {
    return UserModel(
      uid: uid ?? this.uid,
      email: email ?? this.email,
      fullName: fullName ?? this.fullName,
      username: username ?? this.username,
      phoneNumber: phoneNumber ?? this.phoneNumber,
      profilePictureUrl: profilePictureUrl ?? this.profilePictureUrl,
      role: role ?? this.role,
      gender: gender ?? this.gender,
      fcmTokens: fcmTokens ?? this.fcmTokens,
      createdAt: createdAt ?? this.createdAt,
      updatedAt: updatedAt ?? this.updatedAt,
      isGuest: isGuest ?? this.isGuest,
    );
  }

  @override
  List<Object?> get props => [
    uid,
    email,
    fullName,
    username,
    phoneNumber,
    profilePictureUrl,
    role,
    gender,
    fcmTokens,
    createdAt,
    updatedAt,
    isGuest,
  ];
}

import 'package:firebase_auth/firebase_auth.dart' as firebase;
import '../../../../app/services/auth_service.dart';
import '../../../../app/services/firestore_service.dart';
import '../../domain/repositories/auth_repository.dart';
import '../models/user_model.dart';
import 'package:pendeza/shared/models/salon_model.dart';
import '../../../../app/utils/logger.dart';

/// ============================================================================
/// AUTH REPOSITORY IMPLEMENTATION - FIXED VERSION
/// ============================================================================
///
/// 🔥 KEY FIX: Google Sign-In no longer overwrites custom profile pictures!
///
/// PROBLEM BEFORE:
/// - User uploads custom profile picture
/// - User logs out and signs in again with Google
/// - Code saw Google photo URL != custom photo URL
/// - Code OVERWROTE custom photo with Google photo
/// - User's custom profile picture was lost!
///
/// FIX APPLIED:
/// - Only use Google photo if user has NO existing profile picture
/// - If user already has a custom photo, preserve it
/// - Added helper method `_isCustomProfilePicture()` to detect custom uploads
/// ============================================================================

class AuthRepositoryImpl implements AuthRepository {
  final AuthService _authService;
  final FirestoreService _firestoreService;

  AuthRepositoryImpl({
    required AuthService authService,
    required FirestoreService firestoreService,
  })  : _authService = authService,
        _firestoreService = firestoreService;

  @override
  Stream<firebase.User?> get authStateChanges => _authService.authStateChanges;

  @override
  firebase.User? get currentUser => _authService.currentUser;

  @override
  Future<UserModel?> getUserProfile(String uid) {
    return _firestoreService.getUserProfile(uid: uid);
  }

  @override
  Future<void> createUserProfile(firebase.User user) {
    return _firestoreService.createUser(
      uid: user.uid,
      email: user.email ?? '',
      fullName: user.displayName ?? 'New User',
      phoneNumber: user.phoneNumber,
      profilePictureUrl: user.photoURL,
    );
  }

  @override
  Future<void> updateUserProfile({
    required String uid,
    String? newName,
    String? profilePictureUrl,
    String? phoneNumber,
    Gender? gender,
  }) {
    return _firestoreService.updateUserProfile(
      uid: uid,
      newName: newName,
      profilePictureUrl: profilePictureUrl,
      phoneNumber: phoneNumber,
      gender: gender,
    );
  }

  @override
  Future<void> completeClientProfile({
    required String uid,
    required String fullName,
    required String phoneNumber,
    required Gender gender,
    String? profilePictureUrl,
  }) {
    return _firestoreService.completeClientProfile(
      uid: uid,
      fullName: fullName,
      phoneNumber: phoneNumber,
      gender: gender,
      profilePictureUrl: profilePictureUrl,
    );
  }

  @override
  Future<void> signUpWithEmailAndPassword({
    required String fullName,
    required String email,
    required String password,
  }) async {
    final userCredential = await _authService.signUpWithEmailAndPassword(
      email: email,
      password: password,
    );
    if (userCredential?.user != null) {
      await _firestoreService.createUser(
        uid: userCredential!.user!.uid,
        email: userCredential.user!.email ?? '',
        fullName: fullName,
      );
    }
  }

  @override
  Future<void> signInWithEmailAndPassword(
      {required String email, required String password}) async {
    await _authService.signInWithEmailAndPassword(
      email: email,
      password: password,
    );
  }

  // ==========================================================================
  // 🔥 FIXED: Google Sign-In now preserves custom profile pictures!
  // ==========================================================================
  @override
  Future<void> signInWithGoogle() async {
    final credential = await _authService.signInWithGoogle();
    if (credential?.user != null) {
      final user = credential!.user!;
      final existingProfile = await getUserProfile(user.uid);

      if (existingProfile == null) {
        // New user - create profile with Google data
        log.i("Creating new profile for Google user: ${user.uid}");
        await createUserProfile(user);
      } else {
        // Existing user - be careful not to overwrite custom data!
        bool needsUpdate = false;
        String? newName;
        String? newPhotoUrl;

        // ================================================================
        // NAME UPDATE LOGIC (unchanged)
        // Only update name if user still has default name
        // ================================================================
        if (user.displayName != null &&
            user.displayName!.isNotEmpty &&
            (existingProfile.fullName.isEmpty ||
                existingProfile.fullName == 'New User')) {
          newName = user.displayName;
          needsUpdate = true;
          log.i("Will update name from Google: $newName");
        }

        // ================================================================
        // 🔥 FIXED: PROFILE PICTURE UPDATE LOGIC
        //
        // OLD (BROKEN) LOGIC:
        //   if (googlePhoto != existingPhoto) → overwrite with Google photo
        //   This ALWAYS overwrote custom photos!
        //
        // NEW (FIXED) LOGIC:
        //   Only use Google photo if user has NO profile picture at all
        //   If user has ANY profile picture (custom or Google), keep it
        // ================================================================

        final existingPhotoUrl = existingProfile.profilePictureUrl;
        final googlePhotoUrl = user.photoURL;

        // Only set Google photo if user has NO existing profile picture
        if (_shouldUseGooglePhoto(existingPhotoUrl, googlePhotoUrl)) {
          newPhotoUrl = googlePhotoUrl;
          needsUpdate = true;
          log.i("Will set Google photo (user had no profile picture)");
        } else {
          log.i("Preserving existing profile picture: $existingPhotoUrl");
        }

        // Apply updates if needed
        if (needsUpdate) {
          log.i("Updating profile from Google Sign-In for user ${user.uid}");
          await updateUserProfile(
            uid: user.uid,
            newName: newName,
            profilePictureUrl: newPhotoUrl,
          );
        } else {
          log.i("No profile updates needed for Google user ${user.uid}");
        }
      }
    }
  }

  /// ========================================================================
  /// Helper: Determine if we should use Google's profile photo
  ///
  /// Returns TRUE only if:
  /// - User has NO existing profile picture, AND
  /// - Google provides a photo URL
  ///
  /// Returns FALSE if:
  /// - User already has a profile picture (custom OR Google)
  /// - Google doesn't provide a photo
  /// ========================================================================
  bool _shouldUseGooglePhoto(String? existingPhotoUrl, String? googlePhotoUrl) {
    // If Google doesn't provide a photo, nothing to use
    if (googlePhotoUrl == null || googlePhotoUrl.isEmpty) {
      return false;
    }

    // If user has no existing photo, use Google's
    if (existingPhotoUrl == null || existingPhotoUrl.isEmpty) {
      return true;
    }

    // User already has a photo - DON'T overwrite it!
    // This preserves custom uploaded photos
    return false;
  }

  /// ========================================================================
  /// Helper: Check if a URL is a custom uploaded profile picture
  /// (Not currently used, but useful for more sophisticated logic)
  /// ========================================================================
  bool _isCustomProfilePicture(String? photoUrl) {
    if (photoUrl == null || photoUrl.isEmpty) {
      return false;
    }

    // Custom photos are stored in Firebase Storage under these paths:
    // - profile_pictures/{userId}/...
    // - users/{userId}/... (old path, might still exist)
    return photoUrl.contains('profile_pictures') ||
        photoUrl.contains('firebasestorage.googleapis.com');
  }

  /// ========================================================================
  /// Helper: Check if a URL is from Google's servers
  /// (Not currently used, but useful for debugging)
  /// ========================================================================
  bool _isGoogleProfilePicture(String? photoUrl) {
    if (photoUrl == null || photoUrl.isEmpty) {
      return false;
    }

    // Google profile photos come from these domains
    return photoUrl.contains('googleusercontent.com') ||
        photoUrl.contains('google.com/');
  }

  @override
  Future<void> signInWithPhone({
    required String phoneNumber,
    required void Function(String, int?) codeSent,
    required void Function(firebase.FirebaseAuthException) verificationFailed,
  }) async {
    await _authService.signInWithPhone(
      phoneNumber: phoneNumber,
      codeSent: codeSent,
      verificationFailed: verificationFailed,
      verificationCompleted: (phoneAuthCredential) async {
        log.i("Phone verification auto-completed.");
        final userCredential = await firebase.FirebaseAuth.instance
            .signInWithCredential(phoneAuthCredential);
        final user = userCredential.user;
        if (user != null) {
          final existingProfile = await getUserProfile(user.uid);
          if (existingProfile == null) {
            log.i("Creating profile for auto-verified phone user: ${user.uid}");
            await createUserProfile(user);
          }
        }
      },
      codeAutoRetrievalTimeout: (id) {},
    );
  }

  @override
  Future<void> verifyOtp(
      {required String verificationId, required String smsCode}) async {
    final userCredential = await _authService.verifyOtp(
        verificationId: verificationId, smsCode: smsCode);
    if (userCredential?.user != null) {
      final user = userCredential!.user!;
      final existingProfile = await getUserProfile(user.uid);
      if (existingProfile == null) {
        log.i("Creating profile for manually verified phone user: ${user.uid}");
        await createUserProfile(user);
      }
    }
  }

  @override
  Future<void> updateUserFcmToken({required String uid}) {
    return _firestoreService.updateUserFcmToken(uid: uid);
  }

  @override
