              // Create Account Button
              SizedBox(
                width: double.infinity,
                child: OutlinedButton(
                  onPressed: () {
                    context.pop();
                    context.push(
                      AppRoutes.signup,
                      extra: {
                        'returnRoute': returnRoute,
                        'returnData': returnData,
                      },
                    );
