abstract class AppointmentsRepository {
  /// Fetches appointments for a given CLIENT ID (Existing method)
  Future<List<AppointmentWithDetails>> getAppointments(String clientId);

  /// Fetches confirmed appointments for a given SALON ID on a specific DATE
  Future<List<AppointmentModel>> getConfirmedAppointmentsForSalon(
      String salonId, DateTime date);

  /// Fetches the salon profile for a given OWNER ID
  Future<SalonModel?> getSalonForOwner(String ownerId);
}

import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:pendeza/app/services/firestore_service.dart';
import 'package:pendeza/features/2_client_appointments/domain/models/appointment_with_details.dart';
import 'package:pendeza/shared/models/appointment_model.dart';
import 'package:pendeza/shared/models/salon_model.dart';
import 'package:pendeza/shared/models/service_model.dart';
import 'package:pendeza/app/utils/logger.dart';

import 'appoitments_repository.dart';

class AppointmentsRepositoryImpl implements AppointmentsRepository {
  final FirestoreService _firestoreService;
  final FirebaseFirestore _db = FirebaseFirestore.instance;

  AppointmentsRepositoryImpl(this._firestoreService);

  @override
  Future<List<AppointmentWithDetails>> getAppointments(String clientId) async {
    log.d("Fetching appointments for client: $clientId");
    final List<AppointmentModel> rawAppointments =
    await _firestoreService.getAppointmentsForClient(clientId);
    log.d(
        "Found ${rawAppointments.length} raw appointments for client $clientId");

    if (rawAppointments.isEmpty) {
      return [];
    }

    // --- NEW: Resilient Fetching Logic ---
    // Instead of Future.wait, we fetch salons and services individually
    // so one error doesn't break the whole list.

    // 1. Fetch all unique salons
    final salonIds = rawAppointments.map((e) => e.salonId).toSet();
    final salonMap = <String, SalonModel>{};
    for (String id in salonIds) {
      try {
        final salon = await _firestoreService.getSalonDetails(id);
        salonMap[id] = salon;
      } catch (e, s) {
        log.e("Failed to fetch salon details for salonId: $id",
            error: e, stackTrace: s);
        // If a salon fails, we'll skip appointments for it later
      }
    }
    log.d("Successfully fetched ${salonMap.length} salons");

    // 2. Fetch all unique services
    final serviceIds = rawAppointments.expand((e) => e.serviceIds).toSet();
    final serviceMap = <String, ServiceModel>{};
    for (String id in serviceIds) {
      try {
        final service = await _firestoreService.getServiceDetails(id);
        serviceMap[id] = service;
      } catch (e, s) {
        log.e("Failed to fetch service details for serviceId: $id",
            error: e, stackTrace: s);
        // If a service fails, we'll skip appointments that need it
      }
    }
    log.d("Successfully fetched ${serviceMap.length} services");

    // 3. Map appointments, checking for missing data
    final detailedAppointments = <AppointmentWithDetails>[];
    for (var appointment in rawAppointments) {
      // Check if salon was fetched
      final salon = salonMap[appointment.salonId];
      if (salon == null) {
        log.w(
            "Skipping appointment ${appointment.id}: Salon ${appointment.salonId} could not be loaded.");
        continue;
      }

      // Check if ALL services for this appointment were fetched
      final appointmentServices = <ServiceModel>[];
      bool allServicesFound = true;
      for (String serviceId in appointment.serviceIds) {
        final service = serviceMap[serviceId];
        if (service == null) {
          log.w(
              "Skipping appointment ${appointment.id}: Service $serviceId could not be loaded (likely deleted).");
          allServicesFound = false;
          break; // Stop checking services for this appointment
        }
        appointmentServices.add(service);
      }

      if (allServicesFound) {
        detailedAppointments.add(AppointmentWithDetails(
          appointment: appointment,
          salon: salon,
          services: appointmentServices,
        ));
      }
    }
    // --- End of Resilient Logic ---

    log.d(
        "Returning ${detailedAppointments.length} detailed (and valid) appointments for client $clientId");
    return detailedAppointments;
  }

  /// Implementation for getConfirmedAppointmentsForSalon
  @override
  Future<List<AppointmentModel>> getConfirmedAppointmentsForSalon(
      String salonId, DateTime date) async {
    log.d(
        "Fetching confirmed appointments for salon: $salonId on date: ${date.toIso8601String()}");
    try {
      // Calculate start and end of the selected day
      final startOfDay = DateTime(date.year, date.month, date.day, 0, 0, 0);
      final endOfDay = DateTime(date.year, date.month, date.day, 23, 59, 59);

      final snapshot = await _db
          .collection('appointments')
          .where('salonId', isEqualTo: salonId)
      // We can also query for 'Confirmed' status if needed
      // .where('status', isEqualTo: 'Confirmed')
          .where('startTime',
          isGreaterThanOrEqualTo: Timestamp.fromDate(startOfDay))
          .where('startTime', isLessThanOrEqualTo: Timestamp.fromDate(endOfDay))
          .orderBy('startTime', descending: false)
          .get();

      final appointments = snapshot.docs
          .map((doc) => AppointmentModel.fromFirestore(doc))
      // Filter out cancelled appointments on the client side
          .where((app) => app.status != 'Cancelled')
          .toList();

      log.d(
          "Found ${appointments.length} appointments for salon $salonId on ${date.toIso8601String()}");
      return appointments;
    } catch (e, s) {
      log.e("Error fetching appointments for salon $salonId on $date",
          error: e, stackTrace: s);
      rethrow;
    }
  }

  /// Implementation for getSalonForOwner (delegates to FirestoreService)
  @override
  Future<SalonModel?> getSalonForOwner(String ownerId) {
    log.d("Fetching salon for owner: $ownerId via AppointmentsRepository");
    return _firestoreService.getSalonForOwner(ownerId: ownerId);
  }
}

import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:pendeza/features/0_auth/presentation/bloc/auth_bloc.dart';
import 'package:pendeza/features/0_auth/presentation/bloc/auth_state.dart';
import 'package:pendeza/app/utils/logger.dart';
import 'package:pendeza/shared/models/appointment_model.dart';

import '../../domain/repositories/appoitments_repository.dart';
import 'appoitment_events.dart';
import 'appoitments_state.dart';

class AppointmentsBloc extends Bloc<AppointmentsEvent, AppointmentsState> {
  final AppointmentsRepository _appointmentsRepository;
  final AuthBloc _authBloc;

  AppointmentsBloc({
    required AppointmentsRepository appointmentsRepository,
    required AuthBloc authBloc,
  })  : _appointmentsRepository = appointmentsRepository,
        _authBloc = authBloc,
        super(AppointmentsInitial()) {
    on<FetchAppointmentsRequested>(_onFetchAppointmentsRequested);
  }

  Future<void> _onFetchAppointmentsRequested(
      FetchAppointmentsRequested event,
      Emitter<AppointmentsState> emit,
      ) async {
    emit(AppointmentsLoading());

    try {
      final authState = _authBloc.state;

      // Check for GuestMode first
      if (authState is GuestMode) {
        log.i('AppointmentsBloc: Guest user - returning empty list');
        emit(const AppointmentsLoaded(
          pendingPaymentAppointments: [],
          upcomingAppointments: [],
          pastAppointments: [],
        ));
        return;
      }

      // Check for authentication
      if (authState is! Authenticated) {
        log.w('AppointmentsBloc: User not authenticated');
        emit(const AppointmentsError(
            'Please sign in to view your appointments.'));
        return;
      }

      final userId = authState.user.uid;
      log.d('AppointmentsBloc: Fetching appointments for user: $userId');

      final allAppointments =
      await _appointmentsRepository.getAppointments(userId);
      log.d(
          'AppointmentsBloc: Fetched ${allAppointments.length} total appointments');

      final now = DateTime.now();

      //==========================================================================
      // FIXED: Proper categorization based on STATUS + TIME
      //==========================================================================

      // 1. PENDING PAYMENT: Status is 'Pending Payment' regardless of time
      //    These need user action (complete payment or will expire)
      final pendingPayment = allAppointments
          .where((app) => app.appointment.status == AppointmentStatus.pendingPayment)
          .toList();

      // 2. UPCOMING: Status is 'Confirmed' AND time is in the future
      //    These are paid and scheduled
      final upcoming = allAppointments
          .where((app) =>
      app.appointment.status == AppointmentStatus.confirmed &&
          app.appointment.startTime.isAfter(now))
          .toList();

      // 3. PAST: Either:
      //    - Status is 'Confirmed' but time has passed (should be auto-completed)
      //    - Status is 'Completed', 'Cancelled', 'No Show', 'Payment Failed'
      final past = allAppointments.where((app) {
        final appointment = app.appointment;
        final status = appointment.status;
        final isPastTime = appointment.startTime.isBefore(now);

        // Include if status is terminal (completed, cancelled, etc.)
        if (AppointmentStatus.terminal.contains(status)) {
          return true;
        }

        // Include confirmed appointments that are past their time
        if (status == AppointmentStatus.confirmed && isPastTime) {
          return true;
        }

        return false;
      }).toList();

      // Sort each list appropriately
      pendingPayment.sort(
              (a, b) => a.appointment.createdAt.compareTo(b.appointment.createdAt));
      upcoming.sort(
              (a, b) => a.appointment.startTime.compareTo(b.appointment.startTime));
      past.sort(
              (a, b) => b.appointment.startTime.compareTo(a.appointment.startTime));

      log.i(
          'AppointmentsBloc: Loaded ${pendingPayment.length} pending payment, '
              '${upcoming.length} upcoming, ${past.length} past appointments');

      emit(AppointmentsLoaded(
        pendingPaymentAppointments: pendingPayment,
        upcomingAppointments: upcoming,
        pastAppointments: past,
      ));
    } catch (e, s) {
      log.e('AppointmentsBloc: Error loading appointments',
          error: e, stackTrace: s);
      emit(AppointmentsError('Failed to load appointments: ${e.toString()}'));
    }
  }
}

import 'package:equatable/equatable.dart';
import 'package:pendeza/features/2_client_appointments/domain/models/appointment_with_details.dart';

abstract class AppointmentsState extends Equatable {
  const AppointmentsState();

  @override
  List<Object> get props => [];
}

class AppointmentsInitial extends AppointmentsState {}

class AppointmentsLoading extends AppointmentsState {}

/// ENHANCED: Now includes pendingPaymentAppointments for proper status handling
class AppointmentsLoaded extends AppointmentsState {
  /// Appointments that are awaiting payment completion
  /// These should be shown prominently with a "Complete Payment" action
  final List<AppointmentWithDetails> pendingPaymentAppointments;

  /// Appointments that are confirmed (paid) and scheduled for the future
  final List<AppointmentWithDetails> upcomingAppointments;

  /// Appointments that are completed, cancelled, or in the past
  final List<AppointmentWithDetails> pastAppointments;

  const AppointmentsLoaded({
    this.pendingPaymentAppointments = const [],
    required this.upcomingAppointments,
    required this.pastAppointments,
  });

  /// Helper: Check if there are any pending payments requiring action
  bool get hasPendingPayments => pendingPaymentAppointments.isNotEmpty;

  /// Helper: Total count of appointments requiring attention
  int get actionRequiredCount => pendingPaymentAppointments.length;

  /// Helper: Combined count of active appointments (pending + upcoming)
  int get activeAppointmentsCount =>
      pendingPaymentAppointments.length + upcomingAppointments.length;

  @override
  List<Object> get props => [
    pendingPaymentAppointments,
    upcomingAppointments,
    pastAppointments,
  ];
}

class AppointmentsError extends AppointmentsState {
  final String message;

  const AppointmentsError(this.message);

  @override
  List<Object> get props => [message];
}

