          ),
          padding: const EdgeInsets.all(AppConstants.padM),
          child: Row(
            children: [
              AnimatedScale(
                scale: widget.isSelected ? 1.0 : 0.9,
                duration: AppConstants.durationFast,
                child: Icon(
                  widget.isSelected
                      ? CupertinoIcons.check_mark_circled_solid
                      : CupertinoIcons.circle,
                  color: widget.isSelected
