                      'client.dashboard.up_next'.tr(),
                      style: theme.textTheme.titleLarge?.copyWith(
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 12),
              UpcomingAppointmentWidget(
                appointmentWithDetails: state.upcomingAppointments.first,
              ),
            ],
          );
        }
        return const SizedBox.shrink();
      },
    );
  }

  Widget _buildPromotionsSection(BuildContext context, ThemeData theme) {
    return BlocBuilder<PromotionsBloc, PromotionsState>(
      builder: (context, state) {
        if (state is PromotionsLoading) {
          return const SizedBox(
            height: 180,
            child: Center(child: CircularProgressIndicator()),
          );
        }

        if (state is PromotionsLoaded) {
          if (state.promotions.isEmpty) {
            return const SizedBox.shrink();
          }

          return PromotionCarousel(
            promotions: state.promotions,
            onPromotionTap: _handlePromotionTap,
          );
        }

        return const SizedBox.shrink();
      },
    );
  }

  Widget _buildCategoriesSection(BuildContext context, ThemeData theme) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _buildSectionHeader(
          context,
          theme,
          // Key: "client.dashboard.categories"
          title: 'client.dashboard.categories'.tr(),
        ),
        const SizedBox(height: AppConstants.padM),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: AppConstants.padL),
          child: CategoryGridWidget(
            categories: CategoriesData.allCategories,
            onCategorySelected: _handleCategorySelected,
          ),
        ),
      ],
    );
  }

  Widget _buildSectionHeader(
      BuildContext context,
      ThemeData theme, {
        required String title,
        IconData? icon,
        String? actionLabel,
        VoidCallback? onActionTap,
      }) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: AppConstants.padL),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Row(
            children: [
              if (icon != null) ...[
                Icon(
                  icon,
                  color: theme.colorScheme.primary,
                  size: 20,
                ),
                const SizedBox(width: 8),
              ],
              Text(
                title,
                style: theme.textTheme.titleLarge?.copyWith(
                  fontWeight: FontWeight.bold,
                ),
              ),
            ],
          ),
          if (actionLabel != null && onActionTap != null)
            TextButton(
              onPressed: onActionTap,
              style: TextButton.styleFrom(
                padding: const EdgeInsets.symmetric(
                  horizontal: 12,
                  vertical: 8,
                ),
              ),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(actionLabel),
                  const SizedBox(width: 4),
                  Icon(
                    Icons.arrow_forward_rounded,
                    size: 16,
                  ),
                ],
              ),
            ),
        ],
      ),
    );
  }

  /// Salons carousel with loading states
  Widget _buildSalonsCarousel(BuildContext context) {
    return BlocBuilder<DiscoveryBloc, DiscoveryState>(
      builder: (context, state) {
        if (state is DiscoveryLoading) {
          return _buildLoadingCarousel();
        }

        if (state is DiscoveryLoaded) {
          if (state.allSalons.isEmpty) {
            return _buildEmptySalonsState(context);
          }

          // Responsive card width based on screen size
          final screenWidth = MediaQuery.of(context).size.width;
          final cardWidth = (screenWidth * 0.65).clamp(220.0, 280.0);

          return SizedBox(
            height: 280,
            child: ListView.separated(
              scrollDirection: Axis.horizontal,
              padding: const EdgeInsets.symmetric(
                horizontal: AppConstants.padL,
              ),
              itemCount: state.allSalons.length,
              separatorBuilder: (context, index) => const SizedBox(
                width: AppConstants.padM,
              ),
              itemBuilder: (context, index) {
                final salon = state.allSalons[index];
                return SalonCard(
                  salon: salon,
                  width: cardWidth,
                  onTap: () => _handleSalonTap(salon),
                );
              },
            ),
          );
        }

        return const SizedBox.shrink();
      },
    );
  }

  /// Loading shimmer for salons carousel
  Widget _buildLoadingCarousel() {
    final screenWidth = MediaQuery.of(context).size.width;
    final cardWidth = (screenWidth * 0.65).clamp(220.0, 280.0);

    return SizedBox(
      height: 280,
      child: ListView.separated(
        scrollDirection: Axis.horizontal,
        padding: const EdgeInsets.symmetric(horizontal: AppConstants.padL),
        itemCount: 3,
        separatorBuilder: (context, index) => const SizedBox(
          width: AppConstants.padM,
        ),
        itemBuilder: (context, index) {
          return ShimmerPlaceholder.rectangular(
            width: cardWidth,
            height: 280,
            borderRadius: BorderRadius.circular(20),
          );
        },
      ),
    );
  }

  /// Empty state when no salons available
  Widget _buildEmptySalonsState(BuildContext context) {
    final theme = Theme.of(context);
    return Container(
      height: 200,
      margin: const EdgeInsets.symmetric(horizontal: AppConstants.padL),
      decoration: BoxDecoration(
        color: theme.colorScheme.surfaceContainerHighest,
        borderRadius: BorderRadius.circular(16),
      ),
      child: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(
              Icons.store_outlined,
              size: 48,
              color: theme.colorScheme.onSurface.withOpacity(0.3),
            ),
            const SizedBox(height: 12),
            // Key: "client.dashboard.no_salons_title"
            Text(
              'client.dashboard.no_salons_title'.tr(),
              style: theme.textTheme.bodyLarge?.copyWith(
                color: theme.colorScheme.onSurface.withOpacity(0.6),
              ),
            ),
            const SizedBox(height: 8),
            // Key: "client.dashboard.no_salons_msg"
            Text(
              'client.dashboard.no_salons_msg'.tr(),
              style: theme.textTheme.bodySmall?.copyWith(
                color: theme.colorScheme.onSurface.withOpacity(0.4),
              ),
            ),
          ],
        ),
      ),
    );
  }

  // ══════════════════════════════════════════════════════════════════════════
  // EVENT HANDLERS - Smart Navigation & Tracking
  // ══════════════════════════════════════════════════════════════════════════

  void _handlePromotionTap(PromotionModel promotion) {
    if (_isGuest) {
      _sessionTracker.trackFeatureInteraction('promotion_tapped');
    }

    switch (promotion.action) {
      case PromotionAction.openDiscover:
        context.go(AppRoutes.clientDiscover);
        break;

      case PromotionAction.openCategory:
        if (promotion.actionValue != null && promotion.actionValue!.isNotEmpty) {
          context.go(AppRoutes.clientDiscover, extra: promotion.actionValue);
        } else {
          context.go(AppRoutes.clientDiscover);
        }
        break;

      case PromotionAction.openSalon:
        if (promotion.actionValue != null && promotion.actionValue!.isNotEmpty) {
          context.push(
            AppRoutes.salonDetail.replaceFirst(':salonId', promotion.actionValue!),
          );
        }
        break;

      case PromotionAction.openUrl:
      // TODO: Implement url_launcher if needed
        break;

      case PromotionAction.none:
        break;
    }
  }

  void _handleCategorySelected(String categoryId) {
    if (_isGuest) {
      _sessionTracker.trackFeatureInteraction('category_selected');
    }
    context.go(AppRoutes.clientDiscover, extra: categoryId);
  }

  void _handleSalonTap(SalonModel salon) {
    if (_isGuest) {
      _sessionTracker.trackSalonView(salon.id);
      sl<LocalStorageService>().addToBrowsingHistory(salon.id);
    }
    context.push(
      AppRoutes.salonDetail.replaceFirst(':salonId', salon.id),
      extra: salon,
    );
  }

  Future<void> _handleRefresh() async {
    context.read<DiscoveryBloc>().add(const RefreshSalons());
    context.read<PromotionsBloc>().add(RefreshPromotions());
    // 🆕 Refresh video shorts
    context.read<VideoShortsBloc>().add(const RefreshVideoShorts());
  }
}

import 'package:easy_localization/easy_localization.dart';
import 'package:flutter/material.dart';
import 'package:pendeza/app/config/theme/app_constants.dart';
import 'package:pendeza/shared/models/category_model.dart';

class CategoryGridWidget extends StatelessWidget {
  final List<CategoryModel> categories;
  final Function(String categoryId) onCategorySelected;
  final bool showAll;

  const CategoryGridWidget({
    super.key,
    required this.categories,
    required this.onCategorySelected,
    this.showAll = false,
  });

  @override
  Widget build(BuildContext context) {
    final displayList = showAll ? categories : categories.take(6).toList();
    final screenWidth = MediaQuery.of(context).size.width;

    // Responsive: 2 columns for phones, 3 for tablets
    final crossAxisCount = screenWidth > 600 ? 3 : 2;
    // Adjust aspect ratio based on screen width
    final childAspectRatio = screenWidth > 600 ? 2.6 : 2.4;

    return GridView.builder(
      padding: EdgeInsets.zero, // Remove internal padding - parent handles it
      shrinkWrap: true,
      physics: const NeverScrollableScrollPhysics(),
      gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: crossAxisCount,
        crossAxisSpacing: AppConstants.padM,
        mainAxisSpacing: AppConstants.padM,
        childAspectRatio: childAspectRatio,
      ),
      itemCount: displayList.length,
      itemBuilder: (context, index) {
        // Simplified animation - single fade-in for entire grid on load
        return _CategoryCard(
          category: displayList[index],
          onTap: () => onCategorySelected(displayList[index].id),
        );
      },
    );
  }
}

class _CategoryCard extends StatefulWidget {
  final CategoryModel category;
  final VoidCallback onTap;

  const _CategoryCard({
    required this.category,
    required this.onTap,
  });

  @override
  State<_CategoryCard> createState() => _CategoryCardState();
}

class _CategoryCardState extends State<_CategoryCard> {
  bool _isPressed = false;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final isDark = theme.brightness == Brightness.dark;

    final backgroundColor = isDark
        ? theme.colorScheme.surfaceContainerHighest
        : const Color(0xFFF5F7FA);

    final textColor = isDark ? Colors.white : Colors.black87;

    return GestureDetector(
      onTapDown: (_) => setState(() => _isPressed = true),
      onTapUp: (_) => setState(() => _isPressed = false),
      onTapCancel: () => setState(() => _isPressed = false),
      onTap: widget.onTap,
      child: AnimatedScale(
        scale: _isPressed ? 0.95 : 1.0,
        duration: const Duration(milliseconds: 100),
        child: Container(
          decoration: BoxDecoration(
            color: backgroundColor,
            borderRadius: BorderRadius.circular(16),
            border: isDark
                ? Border.all(
              color: Colors.white.withValues(alpha: 0.05),
              width: 1.5,
            )
                : null,
            boxShadow: [
              BoxShadow(
                color: Colors.black.withValues(alpha: 0.04),
                blurRadius: 8,
                offset: const Offset(0, 2),
              ),
            ],
          ),
          child: LayoutBuilder(
            builder: (context, constraints) {
              // Calculate responsive dimensions once
              final imageWidth = (constraints.maxWidth * 0.38).clamp(60.0, 90.0);
              final textRightPadding = (constraints.maxWidth * 0.40).clamp(50.0, 80.0);

              return Stack(
                children: [
                  // Gradient overlay
                  Positioned.fill(
                    child: Container(
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          colors: [
                            theme.colorScheme.primary.withValues(alpha: 0.02),
                            Colors.transparent,
                          ],
                          begin: Alignment.topLeft,
                          end: Alignment.bottomRight,
                        ),
                        borderRadius: BorderRadius.circular(16),
                      ),
                    ),
                  ),

                  // Text - adaptive padding
                  Positioned.fill(
                    child: Align(
                      alignment: Alignment.centerLeft,
                      child: Padding(
                        padding: EdgeInsets.only(
                          left: 14.0,
                          right: textRightPadding,
                        ),
                        child: Text(
                          widget.category.name.tr(),
                          style: theme.textTheme.bodyMedium?.copyWith(
                            fontWeight: FontWeight.bold,
                            color: textColor,
                            height: 1.2,
                            fontSize: 13,
                          ),
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                        ),
                      ),
                    ),
                  ),

                  // Image - responsive width
                  Positioned(
                    right: 0,
                    bottom: 0,
                    top: 0,
                    width: imageWidth,
                    child: ClipRRect(
                      borderRadius: const BorderRadius.only(
                        topRight: Radius.circular(16),
                        bottomRight: Radius.circular(16),
                      ),
                      child: widget.category.iconUrl != null
                          ? Image.asset(
                        widget.category.iconUrl!,
                        fit: BoxFit.cover,
                        alignment: Alignment.bottomCenter,
                        errorBuilder: (context, error, stackTrace) {
                          return Center(
                            child: Icon(
                              Icons.spa,
                              color: textColor.withValues(alpha: 0.2),
                              size: 28,
                            ),
                          );
                        },
                      )
                          : const SizedBox.shrink(),
                    ),
                  ),
                ],
              );
            },
          ),
        ),
      ),
    );
  }
}

import 'package:easy_localization/easy_localization.dart';
