                            borderRadius: BorderRadius.circular(12),
                          ),
                        ),
                        child: const Text('Cancel'),
                      ),
                    ),
                    const SizedBox(width: AppConstants.padM),
                    Expanded(
                      flex: 2,
                      child: PrimaryGradientButton(
                        text: 'Apply Filters',
                        onPressed: _applyFilters,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildSectionTitle(ThemeData theme, String title) {
    return Row(
      children: [
        Container(
          width: 4,
          height: 20,
          decoration: BoxDecoration(
            gradient: LinearGradient(
              colors: [theme.colorScheme.primary, theme.colorScheme.secondary],
            ),
            borderRadius: BorderRadius.circular(2),
          ),
        ),
        const SizedBox(width: 8),
        Text(
          title,
          style: theme.textTheme.titleMedium?.copyWith(
            fontWeight: FontWeight.bold,
          ),
        ),
      ],
    );
  }

  Widget _buildCategoryChips(ThemeData theme) {
    final categories = CategoriesData.allCategories;

    return Wrap(
      spacing: AppConstants.padS,
      runSpacing: AppConstants.padS,
      children: [
        _buildCategoryChip(
          theme: theme,
          label: 'All Categories',
          isSelected: _selectedCategoryId == null,
          onTap: () => setState(() => _selectedCategoryId = null),
        ),
        ...categories.map((category) {
          final isSelected = _selectedCategoryId == category.id;
          return _buildCategoryChip(
            theme: theme,
            label: category.name,
            isSelected: isSelected,
            color: Color(category.color),
            onTap: () => setState(() => _selectedCategoryId = category.id),
          );
        }),
      ],
    );
  }

  Widget _buildCategoryChip({
    required ThemeData theme,
    required String label,
    required bool isSelected,
    Color? color,
    required VoidCallback onTap,
  }) {
    final chipColor = color ?? theme.colorScheme.primary;

    return GestureDetector(
      onTap: onTap,
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 250),
        curve: Curves.easeOutCubic,
        padding: const EdgeInsets.symmetric(
          horizontal: AppConstants.padM + 2,
          vertical: AppConstants.padS + 2,
        ),
        decoration: BoxDecoration(
          gradient: isSelected
              ? LinearGradient(
            colors: [chipColor, chipColor.withValues(alpha: 0.8)],
          )
              : null,
          color: isSelected ? null : theme.colorScheme.surface,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
            color: isSelected ? chipColor : theme.colorScheme.outline.withValues(alpha: 0.3),
            width: isSelected ? 2 : 1,
          ),
          boxShadow: isSelected
              ? [
            BoxShadow(
              color: chipColor.withValues(alpha: 0.3),
              blurRadius: 8,
              offset: const Offset(0, 2),
            )
          ]
              : null,
        ),
        child: Text(
          label,
          style: theme.textTheme.bodyMedium?.copyWith(
            color: isSelected ? Colors.white : theme.colorScheme.onSurface,
            fontWeight: isSelected ? FontWeight.bold : FontWeight.normal,
          ),
        ),
      ),
    );
  }

  Widget _buildRatingFilter(ThemeData theme) {
    final ratings = [1.0, 2.0, 3.0, 4.0, 4.5];

    return Wrap(
      spacing: AppConstants.padS,
      runSpacing: AppConstants.padS,
      children: [
        _buildRatingChip(
          theme: theme,
          rating: null,
          label: 'Any Rating',
          isSelected: _selectedMinRating == null,
        ),
        ...ratings.map((rating) {
          return _buildRatingChip(
            theme: theme,
            rating: rating,
            isSelected: _selectedMinRating == rating,
          );
        }),
      ],
    );
  }

  Widget _buildRatingChip({
    required ThemeData theme,
    required double? rating,
    String? label,
    required bool isSelected,
  }) {
    return GestureDetector(
      onTap: () => setState(() => _selectedMinRating = rating),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 250),
        padding: const EdgeInsets.symmetric(
          horizontal: AppConstants.padM + 2,
          vertical: AppConstants.padS + 2,
        ),
        decoration: BoxDecoration(
          gradient: isSelected
              ? LinearGradient(
            colors: [theme.colorScheme.primary, theme.colorScheme.secondary],
          )
              : null,
          color: isSelected ? null : theme.colorScheme.surface,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
            color: isSelected
                ? theme.colorScheme.primary
                : theme.colorScheme.outline.withValues(alpha: 0.3),
            width: isSelected ? 2 : 1,
          ),
          boxShadow: isSelected
              ? [
            BoxShadow(
              color: theme.colorScheme.primary.withValues(alpha: 0.3),
              blurRadius: 8,
              offset: const Offset(0, 2),
            )
          ]
              : null,
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            if (rating != null) ...[
              Icon(
                Icons.star_rounded,
                size: 18,
                color: isSelected ? Colors.white : theme.colorScheme.primary,
              ),
              const SizedBox(width: 4),
              Text(
                '$rating+',
                style: theme.textTheme.bodyMedium?.copyWith(
                  color: isSelected ? Colors.white : theme.colorScheme.onSurface,
                  fontWeight: isSelected ? FontWeight.bold : FontWeight.normal,
                ),
              ),
            ] else ...[
              Text(
                label ?? '',
                style: theme.textTheme.bodyMedium?.copyWith(
                  color: isSelected ? Colors.white : theme.colorScheme.onSurface,
                  fontWeight: isSelected ? FontWeight.bold : FontWeight.normal,
                ),
              ),
            ],
          ],
        ),
      ),
    );
  }

  Widget _buildSortOptions(ThemeData theme) {
    return Column(
      children: SortType.values.map((sortType) {
        return _buildSortOption(
          theme: theme,
          sortType: sortType,
          isSelected: _selectedSortType == sortType,
        );
      }).toList(),
    );
  }

  Widget _buildSortOption({
    required ThemeData theme,
    required SortType sortType,
    required bool isSelected,
  }) {
    IconData icon;
    String description;

    switch (sortType) {
      case SortType.popularity:
        icon = Icons.trending_up_rounded;
        description = 'Most popular first';
        break;
      case SortType.rating:
        icon = Icons.star_rounded;
        description = 'Highest rated first';
        break;
      case SortType.newest:
        icon = Icons.schedule_rounded;
        description = 'Recently added first';
        break;
    }

    return GestureDetector(
      onTap: () => setState(() => _selectedSortType = sortType),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 250),
        margin: const EdgeInsets.only(bottom: AppConstants.padS),
        padding: const EdgeInsets.all(AppConstants.padM),
        decoration: BoxDecoration(
          gradient: isSelected
              ? LinearGradient(
            colors: [
              theme.colorScheme.primary.withValues(alpha: 0.1),
              theme.colorScheme.secondary.withValues(alpha: 0.05),
            ],
          )
              : null,
          color: isSelected ? null : theme.colorScheme.surface,
          borderRadius: BorderRadius.circular(12),
          border: Border.all(
            color: isSelected
                ? theme.colorScheme.primary
                : theme.colorScheme.outline.withValues(alpha: 0.2),
            width: isSelected ? 2 : 1,
          ),
        ),
        child: Row(
          children: [
            Container(
              padding: const EdgeInsets.all(AppConstants.padS),
              decoration: BoxDecoration(
                gradient: isSelected
                    ? LinearGradient(
                  colors: [theme.colorScheme.primary, theme.colorScheme.secondary],
                )
                    : null,
                color: isSelected ? null : theme.colorScheme.primary.withValues(alpha: 0.1),
                shape: BoxShape.circle,
              ),
              child: Icon(
                icon,
                color: isSelected ? Colors.white : theme.colorScheme.primary,
                size: 20,
              ),
            ),
            const SizedBox(width: AppConstants.padM),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    sortType.displayName,
                    style: theme.textTheme.titleSmall?.copyWith(
                      fontWeight: FontWeight.bold,
                      color: isSelected
                          ? theme.colorScheme.primary
                          : theme.colorScheme.onSurface,
                    ),
                  ),
                  const SizedBox(height: 2),
                  Text(
                    description,
                    style: theme.textTheme.bodySmall?.copyWith(
                      color: theme.colorScheme.onSurfaceVariant,
                    ),
                  ),
                ],
              ),
            ),
            AnimatedContainer(
              duration: const Duration(milliseconds: 250),
              width: 20,
              height: 20,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                gradient: isSelected
                    ? LinearGradient(
                  colors: [theme.colorScheme.primary, theme.colorScheme.secondary],
                )
                    : null,
                border: Border.all(
                  color: isSelected
                      ? theme.colorScheme.primary
                      : theme.colorScheme.outline,
                  width: 2,
                ),
                color: isSelected ? null : Colors.transparent,
              ),
              child: isSelected
                  ? const Center(
                child: Icon(Icons.check, size: 12, color: Colors.white),
              )
                  : null,
            ),
          ],
        ),
      ),
    );
  }

  void _applyFilters() {
    context.read<DiscoveryBloc>().add(
      ApplyFilters(
        categoryId: _selectedCategoryId,
        minRating: _selectedMinRating,
        sortType: _selectedSortType,
      ),
    );
    Navigator.pop(context);
  }

  void _resetFilters() {
    setState(() {
      _selectedCategoryId = null;
      _selectedMinRating = null;
      _selectedSortType = SortType.popularity;
    });
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/cupertino.dart';
import 'package:pendeza/shared/models/salon_model.dart';
import 'package:pendeza/app/config/theme/app_constants.dart';

class SalonDescriptionSection extends StatefulWidget {
  final SalonModel salon;

  const SalonDescriptionSection({super.key, required this.salon});

  @override
  State<SalonDescriptionSection> createState() => _SalonDescriptionSectionState();
}

class _SalonDescriptionSectionState extends State<SalonDescriptionSection>
    with SingleTickerProviderStateMixin {
  bool _isExpanded = false;
  late AnimationController _expandController;
  late Animation<double> _iconRotation;

  @override
  void initState() {
    super.initState();
    _expandController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 300),
    );
    _iconRotation = Tween<double>(begin: 0.0, end: 0.5).animate(
      CurvedAnimation(parent: _expandController, curve: Curves.easeInOut),
    );
  }

  @override
  void dispose() {
    _expandController.dispose();
    super.dispose();
  }

  void _toggleExpanded() {
    setState(() {
      _isExpanded = !_isExpanded;
      if (_isExpanded) {
        _expandController.forward();
      } else {
        _expandController.reverse();
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final description = widget.salon.description ?? 'No description available.';
    final hasLongDescription = description.length > 150;

    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: AppConstants.padL),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                padding: const EdgeInsets.all(8),
                decoration: BoxDecoration(
                  gradient: LinearGradient(
                    colors: [
                      theme.colorScheme.primary.withValues(alpha: 0.1),
                      theme.colorScheme.secondary.withValues(alpha: 0.1),
                    ],
                  ),
                  borderRadius: BorderRadius.circular(10),
                ),
                child: Icon(
                  CupertinoIcons.info_circle_fill,
                  color: theme.colorScheme.primary,
                  size: 20,
                ),
              ),
              const SizedBox(width: 12),
              Text(
                'About ${widget.salon.salonName}',
                style: theme.textTheme.titleLarge?.copyWith(
                  fontWeight: FontWeight.bold,
                ),
              ),
            ],
          ),
          const SizedBox(height: AppConstants.padM),

          // Description with smooth expansion
          AnimatedSize(
            duration: const Duration(milliseconds: 300),
            curve: Curves.easeInOut,
            child: _isExpanded
                ? _buildExpandedDescription(theme, description)
                : _buildCollapsedDescription(theme, description),
          ),

          // See More/Less Button
          if (hasLongDescription)
            Padding(
              padding: const EdgeInsets.only(top: AppConstants.padS),
              child: GestureDetector(
                onTap: _toggleExpanded,
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    gradient: LinearGradient(
                      colors: [
                        theme.colorScheme.primary.withValues(alpha: 0.1),
                        theme.colorScheme.secondary.withValues(alpha: 0.1),
                      ],
                    ),
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        _isExpanded ? 'Show Less' : 'Read More',
                        style: theme.textTheme.bodyMedium?.copyWith(
                          color: theme.colorScheme.primary,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                      const SizedBox(width: 4),
                      RotationTransition(
                        turns: _iconRotation,
                        child: Icon(
                          CupertinoIcons.chevron_down,
                          size: 16,
                          color: theme.colorScheme.primary,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),

          const SizedBox(height: AppConstants.padL),
          _buildServiceCategories(context, widget.salon.serviceCategories),
        ],
      ),
    );
  }

  Widget _buildCollapsedDescription(ThemeData theme, String description) {
    return Text(
      description,
      style: theme.textTheme.bodyLarge?.copyWith(
        height: 1.6,
        color: theme.colorScheme.onSurfaceVariant,
      ),
      maxLines: 3,
      overflow: TextOverflow.ellipsis,
    );
  }

  Widget _buildExpandedDescription(ThemeData theme, String description) {
    return Text(
      description,
      style: theme.textTheme.bodyLarge?.copyWith(
        height: 1.6,
        color: theme.colorScheme.onSurfaceVariant,
      ),
    );
  }

  Widget _buildServiceCategories(BuildContext context, List<String> categories) {
    final theme = Theme.of(context);

    if (categories.isEmpty) {
      return const SizedBox.shrink();
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          children: [
            Icon(
              CupertinoIcons.tag_fill,
              size: 16,
              color: theme.colorScheme.primary,
            ),
            const SizedBox(width: 8),
            Text(
              'Services Offered',
              style: theme.textTheme.titleSmall?.copyWith(
                fontWeight: FontWeight.bold,
                color: theme.colorScheme.onSurface,
              ),
            ),
          ],
        ),
        const SizedBox(height: AppConstants.padS),
        Wrap(
          spacing: AppConstants.padS,
          runSpacing: AppConstants.padS,
          children: categories.asMap().entries.map((entry) {
            final index = entry.key;
            final category = entry.value;

            return TweenAnimationBuilder<double>(
              tween: Tween(begin: 0.0, end: 1.0),
              duration: Duration(milliseconds: 300 + (index * 50)),
              curve: Curves.easeOutBack,
              builder: (context, value, child) {
                // BUG FIX: Curves.easeOutBack can overshoot 1.0 or go below 0.0.
                // We must clamp the value for Opacity to prevent crashes.
                final safeOpacity = value.clamp(0.0, 1.0);

                return Transform.scale(
                  scale: value,
                  child: Opacity(
                    opacity: safeOpacity,
                    child: Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: AppConstants.padM,
                        vertical: AppConstants.padS,
                      ),
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          colors: [
                            theme.colorScheme.primary.withValues(alpha: 0.15),
                            theme.colorScheme.secondary.withValues(alpha: 0.15),
                          ],
                          begin: Alignment.topLeft,
                          end: Alignment.bottomRight,
                        ),
                        borderRadius: BorderRadius.circular(20),
                        border: Border.all(
                          color: theme.colorScheme.primary.withValues(alpha: 0.3),
                          width: 1.5,
                        ),
                        boxShadow: [
                          BoxShadow(
                            color: theme.colorScheme.primary.withValues(alpha: 0.1),
                            blurRadius: 4,
                            offset: const Offset(0, 2),
                          ),
                        ],
                      ),
                      child: Text(
                        category.toUpperCase(),
                        style: theme.textTheme.bodySmall?.copyWith(
                          fontWeight: FontWeight.bold,
                          color: theme.colorScheme.primary,
                          letterSpacing: 0.5,
                        ),
                      ),
                    ),
                  ),
                );
              },
            );
          }).toList(),
        ),
      ],
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/cupertino.dart';
import 'package:go_router/go_router.dart';
import 'package:cached_network_image/cached_network_image.dart';
import 'package:share_plus/share_plus.dart';
import 'package:pendeza/app/config/theme/app_constants.dart';
import 'package:pendeza/app/utils/business_hours_utils.dart';
import 'package:pendeza/shared/models/salon_model.dart';
import 'package:pendeza/app/config/app_router.dart';
import 'package:pendeza/app/config/app_config.dart';

class SalonHeroAppBar extends StatelessWidget {
  final SalonModel salon;
  final double scrollOffset;

  const SalonHeroAppBar({
    super.key,
    required this.salon,
    required this.scrollOffset,
  });

  void _shareSalon(BuildContext context) {
    final String deepLink = AppConfig.getSalonDeepLink(salon.id);
    final String shareMessage =
        'Check out ${salon.salonName} on Pendeza! Book your appointment now.\n\n$deepLink';

    SharePlus.instance.share(
      ShareParams(
        text: shareMessage,
        subject: 'Book ${salon.salonName} on Pendeza',
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final opacity = (scrollOffset / 250).clamp(0.0, 1.0);

    return SliverAppBar(
      expandedHeight: 320,
      pinned: true,
      stretch: true,
      backgroundColor: theme.colorScheme.surface.withValues(alpha: opacity),
      elevation: opacity > 0.8 ? 1 : 0,
      leading: _buildGlassButton(
        context,
        icon: CupertinoIcons.back,
        onTap: () {
          if (context.canPop()) {
            context.pop();
          } else {
            context.go(AppRoutes.clientDiscover);
          }
        },
      ),
      actions: [
        _buildGlassButton(
          context,
          icon: CupertinoIcons.share_up,
          onTap: () => _shareSalon(context),
        ),
        const SizedBox(width: 8),
        _buildGlassButton(
          context,
          icon: CupertinoIcons.heart,
          onTap: () {}, // TODO: Implement favorite
        ),
        const SizedBox(width: AppConstants.padM),
      ],
      flexibleSpace: FlexibleSpaceBar(
        background: Stack(
          fit: StackFit.expand,
          children: [
            // Hero Image with parallax effect
            Hero(
              tag: 'salon_${salon.id}',
              child: Transform.scale(
                scale: 1 + (scrollOffset / 1000).clamp(0.0, 0.3),
                child: salon.primaryImage != null
                    ? CachedNetworkImage(
                  imageUrl: salon.primaryImage!,
                  fit: BoxFit.cover,
                  placeholder: (context, url) => Container(
                    color: theme.colorScheme.surfaceContainerHighest,
                  ),
                  errorWidget: (context, url, error) => Container(
                    color: theme.colorScheme.surfaceContainerHighest,
                    child: const Icon(CupertinoIcons.building_2_fill, size: 80),
                  ),
                )
                    : Container(
                  color: theme.colorScheme.surfaceContainerHighest,
                  child: const Icon(CupertinoIcons.building_2_fill, size: 80),
                ),
              ),
            ),

            // Enhanced gradient overlay
            DecoratedBox(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  colors: [
                    Colors.black.withValues(alpha: 0.2),
                    Colors.transparent,
                    Colors.black.withValues(alpha: 0.4),
                    Colors.black.withValues(alpha: 0.9),
                  ],
                  stops: const [0.0, 0.3, 0.6, 1.0],
                ),
              ),
            ),

            // Salon info with fade animation
            Positioned(
              bottom: AppConstants.padL,
              left: AppConstants.padL,
              right: AppConstants.padL,
              child: Opacity(
                opacity: (1 - (scrollOffset / 200)).clamp(0.0, 1.0),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      salon.salonName,
                      style: theme.textTheme.headlineLarge?.copyWith(
                        color: Colors.white,
                        fontWeight: FontWeight.bold,
                        fontSize: 28,
                        shadows: [
                          Shadow(
                            offset: const Offset(0, 2),
                            blurRadius: 8,
                            color: Colors.black.withValues(alpha: 0.8),
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(height: 6),
                    Row(
                      children: [
                        Container(
                          padding: const EdgeInsets.all(4),
                          decoration: BoxDecoration(
                            color: Colors.white.withValues(alpha: 0.2),
                            borderRadius: BorderRadius.circular(4),
                          ),
                          child: const Icon(
                            CupertinoIcons.location_solid,
                            size: 14,
                            color: Colors.white,
                          ),
                        ),
                        const SizedBox(width: 6),
                        Expanded(
                          child: Text(
                            salon.address,
                            style: theme.textTheme.bodyMedium?.copyWith(
                              color: Colors.white.withValues(alpha: 0.95),
                              fontWeight: FontWeight.w500,
                              shadows: [
                                Shadow(
                                  offset: const Offset(0, 1),
                                  blurRadius: 4,
                                  color: Colors.black.withValues(alpha: 0.6),
                                ),
                              ],
                            ),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 10),
                    // Status Badge
                    _buildStatusBadge(context),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildStatusBadge(BuildContext context) {
    final status = BusinessHoursUtils.getStatus(
      openingTime: salon.openingTime,
      closingTime: salon.closingTime,
    );
    final statusColor = BusinessHoursUtils.getStatusColor(status);
    final statusText = BusinessHoursUtils.getStatusText(
      openingTime: salon.openingTime,
      closingTime: salon.closingTime,
    );

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
      decoration: BoxDecoration(
        color: statusColor.withValues(alpha: 0.2),
        borderRadius: BorderRadius.circular(20),
        border: Border.all(
          color: statusColor.withValues(alpha: 0.4),
          width: 1,
        ),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          // Pulsing dot for open status
          _PulsingDot(color: statusColor, isAnimated: status == SalonStatus.open),
          const SizedBox(width: 6),
          Text(
            statusText,
            style: TextStyle(
              color: Colors.white,
              fontSize: 12,
              fontWeight: FontWeight.w600,
              shadows: [
                Shadow(
                  offset: const Offset(0, 1),
                  blurRadius: 2,
                  color: Colors.black.withValues(alpha: 0.5),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildGlassButton(
      BuildContext context, {
        required IconData icon,
        required VoidCallback onTap,
      }) {
    return Container(
      margin: const EdgeInsets.all(8),
      decoration: BoxDecoration(
        color: Colors.black.withValues(alpha: 0.3),
        shape: BoxShape.circle,
        border: Border.all(
          color: Colors.white.withValues(alpha: 0.15),
          width: 1.5,
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.2),
            blurRadius: 8,
            offset: const Offset(0, 2),
          ),
        ],
      ),
      child: IconButton(
        icon: Icon(icon, color: Colors.white, size: 20),
        onPressed: onTap,
        padding: EdgeInsets.zero,
        constraints: const BoxConstraints(minWidth: 40, minHeight: 40),
      ),
    );
  }
}

/// A pulsing dot indicator for status display.
class _PulsingDot extends StatefulWidget {
  final Color color;
  final bool isAnimated;

  const _PulsingDot({
    required this.color,
    this.isAnimated = true,
  });

  @override
  State<_PulsingDot> createState() => _PulsingDotState();
}

class _PulsingDotState extends State<_PulsingDot>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  late Animation<double> _animation;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      duration: const Duration(milliseconds: 1500),
      vsync: this,
    );
    _animation = Tween<double>(begin: 0.5, end: 1.0).animate(
      CurvedAnimation(parent: _controller, curve: Curves.easeInOut),
    );

    if (widget.isAnimated) {
      _controller.repeat(reverse: true);
    }
  }

  @override
  void didUpdateWidget(_PulsingDot oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.isAnimated && !_controller.isAnimating) {
      _controller.repeat(reverse: true);
    } else if (!widget.isAnimated && _controller.isAnimating) {
      _controller.stop();
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (!widget.isAnimated) {
      return Container(
        width: 8,
        height: 8,
        decoration: BoxDecoration(
          color: widget.color,
          shape: BoxShape.circle,
        ),
      );
    }

    return AnimatedBuilder(
      animation: _animation,
      builder: (context, child) {
        return Container(
          width: 8,
          height: 8,
          decoration: BoxDecoration(
            color: widget.color,
            shape: BoxShape.circle,
            boxShadow: [
              BoxShadow(
                color: widget.color.withValues(alpha: _animation.value * 0.6),
                blurRadius: 4 * _animation.value,
                spreadRadius: 2 * _animation.value,
              ),
            ],
          ),
        );
      },
    );
  }
}

