import 'package:pendeza/shared/models/salon_model.dart';

import '../../../../shared/models/favorite_model.dart';


/// Abstract repository interface for managing user favorites.
///
/// This repository handles:
/// - Adding/removing favorites (for both guests and authenticated users)
/// - Fetching user's favorite salons
/// - Checking if a salon is favorited
/// - Migrating guest favorites to authenticated user account
abstract class FavoritesRepository {
  /// Add a salon to user's favorites
  /// - For guests: Saves to local storage
  /// - For authenticated users: Saves to Firestore
  Future<void> addFavorite({
    required String userId,
    required String salonId,
    bool isGuest = false,
  });

  /// Remove a salon from user's favorites
  /// - For guests: Removes from local storage
  /// - For authenticated users: Removes from Firestore
  Future<void> removeFavorite({
    required String userId,
    required String salonId,
    bool isGuest = false,
  });

  /// Toggle favorite status (add if not favorited, remove if favorited)
  Future<bool> toggleFavorite({
    required String userId,
    required String salonId,
    bool isGuest = false,
  });

  /// Check if a salon is in user's favorites
  /// - For guests: Checks local storage
  /// - For authenticated users: Checks Firestore
  Future<bool> isFavorited({
    required String userId,
    required String salonId,
    bool isGuest = false,
  });

  /// Get list of user's favorite salon IDs
  /// - For guests: Returns from local storage
  /// - For authenticated users: Returns from Firestore
  Future<List<String>> getFavoriteSalonIds({
    required String userId,
    bool isGuest = false,
  });

  /// Get full salon details for user's favorites
  /// - Fetches salon IDs first, then gets full salon data
  Future<List<SalonModel>> getFavoriteSalons({
    required String userId,
    bool isGuest = false,
  });

  /// Get favorite models with metadata (authenticated users only)
  Future<List<FavoriteModel>> getFavoriteModels({
    required String userId,
  });

  /// Migrate guest favorites to authenticated user account
  /// Called after successful signup/signin
  Future<void> migrateGuestFavorites({
    required String guestUserId,
    required String authenticatedUserId,
  });

  /// Stream of favorite salon IDs (for real-time updates)
  /// Authenticated users only - guests don't get real-time updates
  Stream<List<String>> watchFavoriteSalonIds({
    required String userId,
  });

  /// Get count of user's favorites
  Future<int> getFavoritesCount({
    required String userId,
    bool isGuest = false,
  });

  /// Clear all favorites (mainly for guests on logout/cleanup)
  Future<void> clearAllFavorites({
    required String userId,
    bool isGuest = false,
  });
}

import 'package:pendeza/app/services/firestore_service.dart';
import 'package:pendeza/app/services/local_storage_service.dart';
import 'package:pendeza/app/utils/logger.dart';
import 'package:pendeza/shared/models/salon_model.dart';
import '../../../../shared/models/favorite_model.dart';
import '../../domain/repositories/favorites_repository.dart';


/// Implementation of FavoritesRepository that handles both:
/// - Guest favorites (via LocalStorageService)
/// - Authenticated user favorites (via FirestoreService)
class FavoritesRepositoryImpl implements FavoritesRepository {
  final FirestoreService _firestoreService;
  final LocalStorageService _localStorageService;

  FavoritesRepositoryImpl({
    required FirestoreService firestoreService,
    required LocalStorageService localStorageService,
  })  : _firestoreService = firestoreService,
        _localStorageService = localStorageService;

  @override
  Future<void> addFavorite({
    required String userId,
    required String salonId,
    bool isGuest = false,
  }) async {
    try {
      if (isGuest) {
        // Guest: Use local storage
        await _localStorageService.addFavoriteSalon(salonId);
        log.i('Added salon $salonId to guest favorites');
      } else {
        // Authenticated: Use Firestore
        await _firestoreService.addFavoriteSalon(
          userId: userId,
          salonId: salonId,
        );
        log.i('Added salon $salonId to favorites for user $userId');
      }
    } catch (e, s) {
      log.e('Error adding favorite', error: e, stackTrace: s);
      rethrow;
    }
  }

  @override
  Future<void> removeFavorite({
    required String userId,
    required String salonId,
    bool isGuest = false,
  }) async {
    try {
      if (isGuest) {
        // Guest: Use local storage
        await _localStorageService.removeFavoriteSalon(salonId);
        log.i('Removed salon $salonId from guest favorites');
      } else {
        // Authenticated: Use Firestore
        await _firestoreService.removeFavoriteSalon(
          userId: userId,
          salonId: salonId,
        );
        log.i('Removed salon $salonId from favorites for user $userId');
      }
    } catch (e, s) {
      log.e('Error removing favorite', error: e, stackTrace: s);
      rethrow;
    }
  }

  @override
  Future<bool> toggleFavorite({
    required String userId,
    required String salonId,
    bool isGuest = false,
  }) async {
    try {
      final isFav = await isFavorited(
        userId: userId,
        salonId: salonId,
        isGuest: isGuest,
      );

      if (isFav) {
        await removeFavorite(
          userId: userId,
          salonId: salonId,
          isGuest: isGuest,
        );
        return false; // Now not favorited
      } else {
        await addFavorite(
          userId: userId,
          salonId: salonId,
          isGuest: isGuest,
        );
        return true; // Now favorited
      }
    } catch (e, s) {
      log.e('Error toggling favorite', error: e, stackTrace: s);
      rethrow;
    }
  }

  @override
  Future<bool> isFavorited({
    required String userId,
    required String salonId,
    bool isGuest = false,
  }) async {
    try {
      if (isGuest) {
        // Guest: Check local storage
        return _localStorageService.isSalonFavorited(salonId);
      } else {
        // Authenticated: Check Firestore
        return await _firestoreService.isSalonFavorited(
          userId: userId,
          salonId: salonId,
        );
      }
    } catch (e, s) {
      log.e('Error checking if favorited', error: e, stackTrace: s);
      return false;
    }
  }

  @override
  Future<List<String>> getFavoriteSalonIds({
    required String userId,
    bool isGuest = false,
  }) async {
    try {
      if (isGuest) {
        // Guest: Get from local storage
        return _localStorageService.getFavoriteSalons();
      } else {
        // Authenticated: Get from Firestore
        return await _firestoreService.getFavoriteSalonIds(userId: userId);
      }
    } catch (e, s) {
      log.e('Error getting favorite salon IDs', error: e, stackTrace: s);
      return [];
    }
  }

  @override
  Future<List<SalonModel>> getFavoriteSalons({
    required String userId,
    bool isGuest = false,
  }) async {
    try {
      // First, get the list of favorited salon IDs
      final salonIds = await getFavoriteSalonIds(
        userId: userId,
        isGuest: isGuest,
      );

      if (salonIds.isEmpty) {
        return [];
      }

      // Then fetch full salon details for each ID
      final salons = await _firestoreService.getSalonsByIds(salonIds);

      log.i('Retrieved ${salons.length} favorite salons for user $userId');
      return salons;
    } catch (e, s) {
      log.e('Error getting favorite salons', error: e, stackTrace: s);
      return [];
    }
  }

  @override
  Future<List<FavoriteModel>> getFavoriteModels({
    required String userId,
  }) async {
    try {
      // This only works for authenticated users (has metadata)
      return await _firestoreService.getFavoriteModels(userId: userId);
    } catch (e, s) {
      log.e('Error getting favorite models', error: e, stackTrace: s);
      return [];
    }
  }

  @override
  Future<void> migrateGuestFavorites({
    required String guestUserId,
    required String authenticatedUserId,
  }) async {
    try {
      log.i('Starting favorite migration from guest to user $authenticatedUserId');

      // Get guest favorites from local storage
      final guestFavorites = _localStorageService.getFavoriteSalons();

      if (guestFavorites.isEmpty) {
        log.i('No guest favorites to migrate');
        return;
      }

      // Add each favorite to Firestore for authenticated user
      for (final salonId in guestFavorites) {
        await _firestoreService.addFavoriteSalon(
          userId: authenticatedUserId,
          salonId: salonId,
        );
      }

      // Clear guest favorites after successful migration
      await _localStorageService.clearFavoriteSalons();

      log.i('Migrated ${guestFavorites.length} favorites successfully');
    } catch (e, s) {
      log.e('Error migrating guest favorites', error: e, stackTrace: s);
      // Don't rethrow - migration failure shouldn't block user signup
    }
  }

  @override
  Stream<List<String>> watchFavoriteSalonIds({
    required String userId,
  }) {
    try {
      // Real-time updates for authenticated users only
      return _firestoreService.watchFavoriteSalonIds(userId: userId);
    } catch (e, s) {
      log.e('Error watching favorite salon IDs', error: e, stackTrace: s);
      // Return empty stream on error
      return Stream.value([]);
    }
  }

  @override
  Future<int> getFavoritesCount({
    required String userId,
    bool isGuest = false,
  }) async {
    try {
      final salonIds = await getFavoriteSalonIds(
        userId: userId,
        isGuest: isGuest,
      );
      return salonIds.length;
    } catch (e, s) {
      log.e('Error getting favorites count', error: e, stackTrace: s);
      return 0;
    }
  }

  @override
  Future<void> clearAllFavorites({
    required String userId,
    bool isGuest = false,
  }) async {
    try {
      if (isGuest) {
        // Guest: Clear local storage
        await _localStorageService.clearFavoriteSalons();
        log.i('Cleared all guest favorites');
      } else {
        // Authenticated: Clear Firestore favorites
        await _firestoreService.clearAllFavorites(userId: userId);
        log.i('Cleared all favorites for user $userId');
      }
    } catch (e, s) {
      log.e('Error clearing favorites', error: e, stackTrace: s);
      rethrow;
    }
  }
}

import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:pendeza/app/utils/logger.dart';
import 'package:pendeza/features/0_auth/presentation/bloc/auth_bloc.dart';
import 'package:pendeza/features/0_auth/presentation/bloc/auth_state.dart';
import '../../domain/repositories/favorites_repository.dart';
import 'favorites_event.dart';
import 'favorites_state.dart';

/// BLoC for managing favorites feature.
///
/// This BLoC handles:
/// - Loading user's favorite salons
/// - Adding/removing favorites
/// - Toggling favorite status
/// - Guest to authenticated user migration
/// - Real-time updates for authenticated users
class FavoritesBloc extends Bloc<FavoritesEvent, FavoritesState> {
  final FavoritesRepository _favoritesRepository;
  final AuthBloc _authBloc;

  FavoritesBloc({
    required FavoritesRepository favoritesRepository,
    required AuthBloc authBloc,
  })  : _favoritesRepository = favoritesRepository,
        _authBloc = authBloc,
        super(const FavoritesInitial()) {
    // Register event handlers
    on<LoadFavorites>(_onLoadFavorites);
    on<ToggleFavorite>(_onToggleFavorite);
    on<AddFavorite>(_onAddFavorite);
    on<RemoveFavorite>(_onRemoveFavorite);
    on<RefreshFavorites>(_onRefreshFavorites);
    on<CheckIsFavorited>(_onCheckIsFavorited);
    on<ClearAllFavorites>(_onClearAllFavorites);
    on<MigrateGuestFavorites>(_onMigrateGuestFavorites);
  }

  //============================================================================
  // LOAD FAVORITES
  //============================================================================

  Future<void> _onLoadFavorites(
      LoadFavorites event,
      Emitter<FavoritesState> emit,
      ) async {
    try {
      emit(const FavoritesLoading());

      log.i('Loading favorites for user: ${event.userId} (guest: ${event.isGuest})');

      // Get favorite salon IDs
      final salonIds = await _favoritesRepository.getFavoriteSalonIds(
        userId: event.userId,
        isGuest: event.isGuest,
      );

      // If no favorites, emit empty state
      if (salonIds.isEmpty) {
        emit(const FavoritesEmpty());
        return;
      }

      // Get full salon details
      final salons = await _favoritesRepository.getFavoriteSalons(
        userId: event.userId,
        isGuest: event.isGuest,
      );

      emit(FavoritesLoaded(
        favoriteSalons: salons,
        favoriteSalonIds: salonIds,
        totalCount: salonIds.length,
      ));

      log.i('Loaded ${salons.length} favorite salons');
    } catch (e, s) {
      log.e('Error loading favorites', error: e, stackTrace: s);
      emit(FavoritesError(
        message: 'Failed to load favorites. Please try again.',
        errorCode: e.toString(),
      ));
    }
  }

  //============================================================================
  // TOGGLE FAVORITE
  //============================================================================

  Future<void> _onToggleFavorite(
      ToggleFavorite event,
      Emitter<FavoritesState> emit,
      ) async {
    try {
      // Emit toggling state for optimistic UI update
      final currentState = state;
      bool wasAdding = true;

      // Check current status
      final isFav = await _favoritesRepository.isFavorited(
        userId: event.userId,
        salonId: event.salonId,
        isGuest: event.isGuest,
      );

      wasAdding = !isFav; // If not favorited, we're adding

      emit(FavoriteToggling(
        salonId: event.salonId,
        isAdding: wasAdding,
      ));

      // Perform the toggle
      final newStatus = await _favoritesRepository.toggleFavorite(
        userId: event.userId,
        salonId: event.salonId,
        isGuest: event.isGuest,
      );

      // Emit success state
      emit(FavoriteToggled(
        salonId: event.salonId,
        isFavorited: newStatus,
        message: newStatus
            ? 'Added to favorites'
            : 'Removed from favorites',
      ));

      // If we were in loaded state, update the list
      if (currentState is FavoritesLoaded) {
        // Refresh the favorites list
        add(RefreshFavorites(
          userId: event.userId,
          isGuest: event.isGuest,
        ));
      }

      log.i('Toggled favorite for salon ${event.salonId}: $newStatus');
    } catch (e, s) {
      log.e('Error toggling favorite', error: e, stackTrace: s);
      emit(FavoritesError(
        message: 'Failed to update favorite. Please try again.',
        errorCode: e.toString(),
      ));
    }
  }

  //============================================================================
  // ADD FAVORITE
  //============================================================================

  Future<void> _onAddFavorite(
      AddFavorite event,
      Emitter<FavoritesState> emit,
      ) async {
    try {
      emit(FavoriteToggling(
        salonId: event.salonId,
        isAdding: true,
      ));

      await _favoritesRepository.addFavorite(
        userId: event.userId,
        salonId: event.salonId,
        isGuest: event.isGuest,
      );

      emit(FavoriteToggled(
        salonId: event.salonId,
        isFavorited: true,
        message: 'Added to favorites',
      ));

      // Refresh list if we're viewing favorites
      if (state is FavoritesLoaded) {
        add(RefreshFavorites(
          userId: event.userId,
          isGuest: event.isGuest,
        ));
      }

      log.i('Added salon ${event.salonId} to favorites');
    } catch (e, s) {
      log.e('Error adding favorite', error: e, stackTrace: s);
      emit(FavoritesError(
        message: 'Failed to add favorite. Please try again.',
        errorCode: e.toString(),
      ));
    }
  }

  //============================================================================
  // REMOVE FAVORITE
  //============================================================================

  Future<void> _onRemoveFavorite(
      RemoveFavorite event,
      Emitter<FavoritesState> emit,
      ) async {
    try {
      emit(FavoriteToggling(
        salonId: event.salonId,
        isAdding: false,
      ));

      await _favoritesRepository.removeFavorite(
        userId: event.userId,
        salonId: event.salonId,
        isGuest: event.isGuest,
      );

      emit(FavoriteToggled(
        salonId: event.salonId,
        isFavorited: false,
        message: 'Removed from favorites',
      ));

      // Refresh list if we're viewing favorites
      if (state is FavoritesLoaded) {
        add(RefreshFavorites(
          userId: event.userId,
          isGuest: event.isGuest,
        ));
      }

      log.i('Removed salon ${event.salonId} from favorites');
    } catch (e, s) {
      log.e('Error removing favorite', error: e, stackTrace: s);
      emit(FavoritesError(
        message: 'Failed to remove favorite. Please try again.',
        errorCode: e.toString(),
      ));
    }
  }

  //============================================================================
  // REFRESH FAVORITES
  //============================================================================

  Future<void> _onRefreshFavorites(
      RefreshFavorites event,
      Emitter<FavoritesState> emit,
      ) async {
    try {
      // Don't show loading state on refresh (smoother UX)
      final salonIds = await _favoritesRepository.getFavoriteSalonIds(
        userId: event.userId,
        isGuest: event.isGuest,
      );

      if (salonIds.isEmpty) {
        emit(const FavoritesEmpty());
        return;
      }

      final salons = await _favoritesRepository.getFavoriteSalons(
        userId: event.userId,
        isGuest: event.isGuest,
      );

      emit(FavoritesLoaded(
        favoriteSalons: salons,
        favoriteSalonIds: salonIds,
        totalCount: salonIds.length,
      ));

      log.i('Refreshed ${salons.length} favorite salons');
    } catch (e, s) {
      log.e('Error refreshing favorites', error: e, stackTrace: s);
      emit(FavoritesError(
        message: 'Failed to refresh favorites.',
        errorCode: e.toString(),
      ));
    }
  }

  //============================================================================
  // CHECK IS FAVORITED
  //============================================================================

  Future<void> _onCheckIsFavorited(
      CheckIsFavorited event,
      Emitter<FavoritesState> emit,
      ) async {
    try {
      final isFav = await _favoritesRepository.isFavorited(
        userId: event.userId,
        salonId: event.salonId,
        isGuest: event.isGuest,
      );

      // This is mainly for single card updates
      // You might want to handle this differently in your UI
      log.d('Salon ${event.salonId} favorited: $isFav');
    } catch (e, s) {
      log.e('Error checking if favorited', error: e, stackTrace: s);
    }
  }

  //============================================================================
  // CLEAR ALL FAVORITES
  //============================================================================

  Future<void> _onClearAllFavorites(
      ClearAllFavorites event,
      Emitter<FavoritesState> emit,
      ) async {
    try {
      emit(const FavoritesLoading());

      await _favoritesRepository.clearAllFavorites(
        userId: event.userId,
        isGuest: event.isGuest,
      );

      emit(const FavoritesEmpty(
        message: 'All favorites cleared',
      ));

      log.i('Cleared all favorites for user ${event.userId}');
    } catch (e, s) {
      log.e('Error clearing favorites', error: e, stackTrace: s);
      emit(FavoritesError(
        message: 'Failed to clear favorites.',
        errorCode: e.toString(),
      ));
    }
  }

  //============================================================================
  // MIGRATE GUEST FAVORITES
  //============================================================================

  Future<void> _onMigrateGuestFavorites(
      MigrateGuestFavorites event,
      Emitter<FavoritesState> emit,
      ) async {
    try {
      // Get count of guest favorites to migrate
      final guestCount = await _favoritesRepository.getFavoritesCount(
        userId: event.guestUserId,
        isGuest: true,
      );

      if (guestCount == 0) {
        log.i('No guest favorites to migrate');
        return;
      }

      emit(FavoritesMigrating(totalToMigrate: guestCount));

      // Perform migration
      await _favoritesRepository.migrateGuestFavorites(
        guestUserId: event.guestUserId,
        authenticatedUserId: event.authenticatedUserId,
      );

      emit(FavoritesMigrated(
        migratedCount: guestCount,
        message: 'Migrated $guestCount favorites to your account',
      ));

      // Load the newly migrated favorites
      add(LoadFavorites(
        userId: event.authenticatedUserId,
        isGuest: false,
      ));

      log.i('Successfully migrated $guestCount favorites');
    } catch (e, s) {
      log.e('Error migrating guest favorites', error: e, stackTrace: s);
      emit(FavoritesError(
        message: 'Failed to migrate favorites. Don\'t worry, your favorites are safe!',
        errorCode: e.toString(),
      ));
    }
  }

  //============================================================================
  // HELPER METHODS
  //============================================================================

  /// Get current user info from AuthBloc
  String? _getCurrentUserId() {
    final authState = _authBloc.state;
    if (authState is Authenticated) {
      return authState.user.uid;
    } else if (authState is GuestMode) {
      return authState.guestUser.uid;
    }
    return null;
  }

  /// Check if current user is guest
  bool _isCurrentUserGuest() {
    return _authBloc.state is GuestMode;
  }
}

