import 'package:pendeza/features/2_client_favorites/presentation/bloc/favorites_state.dart';
// Add this import to access the repository interface
import 'package:pendeza/features/2_client_favorites/domain/repositories/favorites_repository.dart';

/// A reusable favorite icon button that handles guest and authenticated users.
class FavoriteIconButton extends StatefulWidget {
  final String salonId;
  final double size;
  final Color? backgroundColor;
  final Color? iconColor;
  final Color? favoriteColor;
  final bool showBackground;
  final VoidCallback? onToggled; // Callback after toggle completes

  const FavoriteIconButton({
    super.key,
    required this.salonId,
    this.size = 20,
    this.backgroundColor,
    this.iconColor,
    this.favoriteColor,
    this.showBackground = true,
    this.onToggled,
  });

  @override
  State<FavoriteIconButton> createState() => _FavoriteIconButtonState();
}

class _FavoriteIconButtonState extends State<FavoriteIconButton>
    with SingleTickerProviderStateMixin {
  late AnimationController _animationController;
  late Animation<double> _scaleAnimation;
  bool _isFavorited = false;
  bool _isLoading = false;

  @override
  void initState() {
    super.initState();

    // Setup animation for heart pop effect
    _animationController = AnimationController(
      duration: const Duration(milliseconds: 300),
      vsync: this,
    );

    _scaleAnimation = Tween<double>(begin: 1.0, end: 1.3).animate(
      CurvedAnimation(
        parent: _animationController,
        curve: Curves.easeInOut,
      ),
    );

    // Check initial favorite status
    _checkFavoriteStatus();
  }

  @override
  void dispose() {
    _animationController.dispose();
    super.dispose();
  }

  /// Check if this salon is already favorited
  Future<void> _checkFavoriteStatus() async {
    if (!mounted) return;

    final authState = context.read<AuthBloc>().state;
    String? userId;
    bool isGuest = false;

    if (authState is Authenticated) {
      userId = authState.user.uid;
      isGuest = false;
    } else if (authState is GuestMode) {
      userId = authState.guestUser.uid;
      isGuest = true;
    }

    if (userId == null) return;

    try {
      // FIX: Get the repository directly from SL, not from the Bloc's private field
      final favRepo = sl<FavoritesRepository>();

      final isFav = await favRepo.isFavorited(
        userId: userId,
        salonId: widget.salonId,
        isGuest: isGuest,
      );

      if (mounted) {
        setState(() {
          _isFavorited = isFav;
        });
      }
    } catch (e) {
      // Fail silently - not critical
      // print('Error checking favorite status: $e');
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return BlocListener<FavoritesBloc, FavoritesState>(
      listener: (context, state) {
        if (state is FavoriteToggled && state.salonId == widget.salonId) {
          // Update local state
          setState(() {
            _isFavorited = state.isFavorited;
            _isLoading = false;
          });

          // Animate if favorited
          if (state.isFavorited) {
            _animationController.forward().then((_) {
              _animationController.reverse();
            });
          }

          // Show snackbar
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(state.message),
              duration: const Duration(seconds: 2),
              behavior: SnackBarBehavior.floating,
            ),
          );

          // Trigger callback
          widget.onToggled?.call();
        } else if (state is FavoriteToggling &&
            state.salonId == widget.salonId) {
          setState(() {
            _isLoading = true;
          });
        }
      },
      child: GestureDetector(
        onTap: _isLoading ? null : _handleToggle,
        child: AnimatedBuilder(
          animation: _scaleAnimation,
          builder: (context, child) {
            return Transform.scale(
              scale: _scaleAnimation.value,
              child: Container(
                padding: const EdgeInsets.all(6),
                decoration: widget.showBackground
                    ? BoxDecoration(
                  color: widget.backgroundColor ??
                      Colors.white.withOpacity(0.9),
                  shape: BoxShape.circle,
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black.withOpacity(0.1),
                      blurRadius: 4,
                      offset: const Offset(0, 2),
                    ),
                  ],
                )
                    : null,
                child: _isLoading
                    ? SizedBox(
                  width: widget.size,
                  height: widget.size,
                  child: CircularProgressIndicator(
                    strokeWidth: 2,
                    valueColor: AlwaysStoppedAnimation<Color>(
                      theme.colorScheme.primary,
                    ),
                  ),
                )
                    : Icon(
                  _isFavorited
                      ? CupertinoIcons.heart_fill
                      : CupertinoIcons.heart,
                  size: widget.size,
                  color: _isFavorited
                      ? (widget.favoriteColor ?? Colors.red)
                      : (widget.iconColor ??
                      theme.colorScheme.onSurface),
                ),
              ),
            );
          },
        ),
      ),
    );
  }

  /// Handle favorite toggle
  void _handleToggle() {
    final authState = context.read<AuthBloc>().state;
    String? userId;
    bool isGuest = false;

    if (authState is Authenticated) {
      userId = authState.user.uid;
      isGuest = false;
    } else if (authState is GuestMode) {
      userId = authState.guestUser.uid;
      isGuest = true;
    }

    if (userId == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please sign in to add favorites'),
        ),
      );
      return;
    }

    // Dispatch toggle event
    context.read<FavoritesBloc>().add(
      ToggleFavorite(
        userId: userId,
        salonId: widget.salonId,
        isGuest: isGuest,
      ),
    );
  }
}

import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:pendeza/shared/models/notification_model.dart';
import 'package:pendeza/app/utils/logger.dart';

/// Repository for managing user notifications
class NotificationRepository {
  final FirebaseFirestore _firestore;

  NotificationRepository({FirebaseFirestore? firestore})
      : _firestore = firestore ?? FirebaseFirestore.instance;

  /// Collection reference for notifications
  CollectionReference<Map<String, dynamic>> get _notificationsCollection =>
      _firestore.collection('notifications');

  /// Get notifications for a user
  Future<List<NotificationModel>> getNotifications(String userId) async {
    try {
      final snapshot = await _notificationsCollection
          .where('userId', isEqualTo: userId)
          .orderBy('createdAt', descending: true)
          .limit(50)
          .get();

      return snapshot.docs
          .map((doc) => NotificationModel.fromFirestore(doc))
          .toList();
    } catch (e, stackTrace) {
      log.e('Error fetching notifications', error: e, stackTrace: stackTrace);
      return [];
    }
  }

  /// Stream notifications for real-time updates
  Stream<List<NotificationModel>> streamNotifications(String userId) {
    return _notificationsCollection
        .where('userId', isEqualTo: userId)
        .orderBy('createdAt', descending: true)
        .limit(50)
        .snapshots()
        .map((snapshot) => snapshot.docs
            .map((doc) => NotificationModel.fromFirestore(doc))
            .toList());
  }

  /// Get unread notification count
  Future<int> getUnreadCount(String userId) async {
    try {
      final snapshot = await _notificationsCollection
          .where('userId', isEqualTo: userId)
          .where('isRead', isEqualTo: false)
          .count()
          .get();

      return snapshot.count ?? 0;
    } catch (e, stackTrace) {
      log.e('Error getting unread count', error: e, stackTrace: stackTrace);
      return 0;
    }
  }

  /// Stream unread notification count for real-time badge updates
  Stream<int> streamUnreadCount(String userId) {
    return _notificationsCollection
        .where('userId', isEqualTo: userId)
        .where('isRead', isEqualTo: false)
        .snapshots()
        .map((snapshot) => snapshot.docs.length);
  }

  /// Mark a notification as read
  Future<void> markAsRead(String notificationId) async {
    try {
      await _notificationsCollection.doc(notificationId).update({
        'isRead': true,
        'readAt': FieldValue.serverTimestamp(),
      });
    } catch (e, stackTrace) {
      log.e('Error marking notification as read',
          error: e, stackTrace: stackTrace);
      rethrow;
    }
  }

  /// Mark all notifications as read for a user
  Future<void> markAllAsRead(String userId) async {
    try {
      final batch = _firestore.batch();

      final snapshot = await _notificationsCollection
          .where('userId', isEqualTo: userId)
          .where('isRead', isEqualTo: false)
          .get();

      for (final doc in snapshot.docs) {
        batch.update(doc.reference, {
          'isRead': true,
          'readAt': FieldValue.serverTimestamp(),
        });
      }

      await batch.commit();
      log.i('Marked ${snapshot.docs.length} notifications as read');
    } catch (e, stackTrace) {
      log.e('Error marking all notifications as read',
          error: e, stackTrace: stackTrace);
      rethrow;
    }
  }

  /// Delete a notification
  Future<void> deleteNotification(String notificationId) async {
    try {
      await _notificationsCollection.doc(notificationId).delete();
    } catch (e, stackTrace) {
      log.e('Error deleting notification', error: e, stackTrace: stackTrace);
      rethrow;
    }
  }

  /// Delete all notifications for a user
  Future<void> deleteAllNotifications(String userId) async {
    try {
      final batch = _firestore.batch();

      final snapshot = await _notificationsCollection
          .where('userId', isEqualTo: userId)
          .get();

      for (final doc in snapshot.docs) {
        batch.delete(doc.reference);
      }

      await batch.commit();
      log.i('Deleted ${snapshot.docs.length} notifications');
    } catch (e, stackTrace) {
      log.e('Error deleting all notifications',
          error: e, stackTrace: stackTrace);
      rethrow;
    }
  }

  /// Create a local notification (for testing or local use)
  Future<NotificationModel> createNotification({
    required String userId,
    required String title,
    required String body,
    NotificationType type = NotificationType.general,
    String? imageUrl,
    String? actionRoute,
    Map<String, dynamic>? data,
  }) async {
    try {
      final docRef = await _notificationsCollection.add({
        'userId': userId,
        'title': title,
        'body': body,
        'type': type.name,
        'createdAt': FieldValue.serverTimestamp(),
        'isRead': false,
        if (imageUrl != null) 'imageUrl': imageUrl,
        if (actionRoute != null) 'actionRoute': actionRoute,
        if (data != null) 'data': data,
      });

      final doc = await docRef.get();
      return NotificationModel.fromFirestore(doc);
    } catch (e, stackTrace) {
      log.e('Error creating notification', error: e, stackTrace: stackTrace);
      rethrow;
    }
  }
}

import 'dart:async';

import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:pendeza/app/utils/logger.dart';
import 'package:pendeza/features/0_auth/presentation/bloc/auth_bloc.dart';
import 'package:pendeza/features/0_auth/presentation/bloc/auth_state.dart';
import 'package:pendeza/features/2_client_notifications/domain/repositories/notification_repository.dart';
import 'package:pendeza/shared/models/notification_model.dart';

import 'notification_event.dart';
import 'notification_state.dart';

class NotificationBloc extends Bloc<NotificationEvent, NotificationState> {
  final NotificationRepository _repository;
  final AuthBloc _authBloc;

  StreamSubscription<List<NotificationModel>>? _notificationsSubscription;
  StreamSubscription<int>? _unreadCountSubscription;
  StreamSubscription<AuthState>? _authSubscription;

  NotificationBloc({
    required NotificationRepository repository,
    required AuthBloc authBloc,
  })  : _repository = repository,
        _authBloc = authBloc,
        super(const NotificationInitial()) {
    on<LoadNotifications>(_onLoadNotifications);
    on<RefreshNotifications>(_onRefreshNotifications);
    on<MarkNotificationAsRead>(_onMarkAsRead);
    on<MarkAllNotificationsAsRead>(_onMarkAllAsRead);
    on<DeleteNotification>(_onDeleteNotification);
    on<DeleteAllNotifications>(_onDeleteAllNotifications);
    on<UpdateUnreadCount>(_onUpdateUnreadCount);

    // Listen to auth state changes
    _authSubscription = _authBloc.stream.listen((authState) {
      if (authState is Authenticated) {
        add(const LoadNotifications());
      } else {
        _cancelSubscriptions();
        emit(const NotificationInitial());
      }
    });

    // Load notifications if already authenticated
    if (_authBloc.state is Authenticated) {
      add(const LoadNotifications());
    }
  }

  String? get _currentUserId {
    final authState = _authBloc.state;
    if (authState is Authenticated) {
      return authState.user.uid;
    }
    return null;
  }

  Future<void> _onLoadNotifications(
    LoadNotifications event,
    Emitter<NotificationState> emit,
  ) async {
    final userId = _currentUserId;
    if (userId == null) {
      emit(const NotificationError('User not authenticated'));
      return;
    }

    emit(const NotificationLoading());

    try {
      // Cancel existing subscriptions
      await _cancelSubscriptions();

      // Get initial notifications
      final notifications = await _repository.getNotifications(userId);
      final unreadCount = await _repository.getUnreadCount(userId);

      emit(NotificationLoaded(
        notifications: notifications,
        unreadCount: unreadCount,
      ));

      // Setup real-time streams
      _setupStreams(userId);
    } catch (e, stackTrace) {
      log.e('Error loading notifications', error: e, stackTrace: stackTrace);
      emit(NotificationError(e.toString()));
    }
  }

  Future<void> _onRefreshNotifications(
    RefreshNotifications event,
    Emitter<NotificationState> emit,
  ) async {
    final userId = _currentUserId;
    if (userId == null) return;

    try {
      final notifications = await _repository.getNotifications(userId);
      final unreadCount = await _repository.getUnreadCount(userId);

      emit(NotificationLoaded(
        notifications: notifications,
        unreadCount: unreadCount,
      ));
    } catch (e, stackTrace) {
      log.e('Error refreshing notifications', error: e, stackTrace: stackTrace);
    }
  }

  Future<void> _onMarkAsRead(
    MarkNotificationAsRead event,
    Emitter<NotificationState> emit,
  ) async {
    final currentState = state;
    if (currentState is! NotificationLoaded) return;

    try {
      await _repository.markAsRead(event.notificationId);

      // Update local state
      final updatedNotifications = currentState.notifications.map((n) {
        if (n.id == event.notificationId) {
          return n.copyWith(isRead: true);
        }
        return n;
      }).toList();

      emit(currentState.copyWith(
        notifications: updatedNotifications,
        unreadCount: (currentState.unreadCount - 1).clamp(0, double.maxFinite.toInt()),
      ));
    } catch (e, stackTrace) {
      log.e('Error marking notification as read',
          error: e, stackTrace: stackTrace);
    }
  }

  Future<void> _onMarkAllAsRead(
    MarkAllNotificationsAsRead event,
    Emitter<NotificationState> emit,
  ) async {
    final userId = _currentUserId;
    if (userId == null) return;

    final currentState = state;
    if (currentState is! NotificationLoaded) return;

    try {
      await _repository.markAllAsRead(userId);

      // Update local state
      final updatedNotifications = currentState.notifications
          .map((n) => n.copyWith(isRead: true))
          .toList();

      emit(currentState.copyWith(
        notifications: updatedNotifications,
        unreadCount: 0,
      ));
    } catch (e, stackTrace) {
      log.e('Error marking all notifications as read',
          error: e, stackTrace: stackTrace);
    }
  }

  Future<void> _onDeleteNotification(
    DeleteNotification event,
    Emitter<NotificationState> emit,
  ) async {
    final currentState = state;
    if (currentState is! NotificationLoaded) return;

    try {
      // Find the notification to check if it was unread
      final notification = currentState.notifications.firstWhere(
        (n) => n.id == event.notificationId,
        orElse: () => throw Exception('Notification not found'),
      );

      await _repository.deleteNotification(event.notificationId);

      // Update local state
      final updatedNotifications = currentState.notifications
          .where((n) => n.id != event.notificationId)
          .toList();

      emit(currentState.copyWith(
        notifications: updatedNotifications,
        unreadCount: notification.isRead
            ? currentState.unreadCount
            : (currentState.unreadCount - 1).clamp(0, double.maxFinite.toInt()),
      ));
    } catch (e, stackTrace) {
      log.e('Error deleting notification', error: e, stackTrace: stackTrace);
    }
  }

  Future<void> _onDeleteAllNotifications(
    DeleteAllNotifications event,
    Emitter<NotificationState> emit,
  ) async {
    final userId = _currentUserId;
    if (userId == null) return;

    try {
      await _repository.deleteAllNotifications(userId);

      emit(const NotificationLoaded(
        notifications: [],
        unreadCount: 0,
      ));
    } catch (e, stackTrace) {
      log.e('Error deleting all notifications',
          error: e, stackTrace: stackTrace);
    }
  }

  void _onUpdateUnreadCount(
    UpdateUnreadCount event,
    Emitter<NotificationState> emit,
  ) {
    final currentState = state;
    if (currentState is NotificationLoaded) {
      emit(currentState.copyWith(unreadCount: event.count));
    }
  }

  void _setupStreams(String userId) {
    // Stream notifications for real-time updates
    _notificationsSubscription = _repository
        .streamNotifications(userId)
        .listen((notifications) {
      if (state is NotificationLoaded) {
        final currentState = state as NotificationLoaded;
        emit(currentState.copyWith(notifications: notifications));
      }
    });

    // Stream unread count
    _unreadCountSubscription = _repository
        .streamUnreadCount(userId)
        .listen((count) {
      add(UpdateUnreadCount(count));
    });
  }

  Future<void> _cancelSubscriptions() async {
    await _notificationsSubscription?.cancel();
    await _unreadCountSubscription?.cancel();
    _notificationsSubscription = null;
    _unreadCountSubscription = null;
  }

  @override
  Future<void> close() async {
    await _cancelSubscriptions();
    await _authSubscription?.cancel();
    return super.close();
  }
}

import 'package:equatable/equatable.dart';

abstract class NotificationEvent extends Equatable {
  const NotificationEvent();

  @override
  List<Object?> get props => [];
}

/// Load notifications for the current user
class LoadNotifications extends NotificationEvent {
  const LoadNotifications();
}

/// Refresh notifications
class RefreshNotifications extends NotificationEvent {
  const RefreshNotifications();
}

/// Mark a single notification as read
class MarkNotificationAsRead extends NotificationEvent {
  final String notificationId;

  const MarkNotificationAsRead(this.notificationId);

  @override
  List<Object?> get props => [notificationId];
}

/// Mark all notifications as read
class MarkAllNotificationsAsRead extends NotificationEvent {
  const MarkAllNotificationsAsRead();
}

/// Delete a single notification
class DeleteNotification extends NotificationEvent {
  final String notificationId;

  const DeleteNotification(this.notificationId);

  @override
  List<Object?> get props => [notificationId];
}

/// Delete all notifications
class DeleteAllNotifications extends NotificationEvent {
  const DeleteAllNotifications();
}

/// Update unread count (usually from stream)
class UpdateUnreadCount extends NotificationEvent {
  final int count;

  const UpdateUnreadCount(this.count);

  @override
  List<Object?> get props => [count];
}

import 'package:equatable/equatable.dart';
import 'package:pendeza/shared/models/notification_model.dart';

abstract class NotificationState extends Equatable {
  const NotificationState();

  @override
  List<Object?> get props => [];
}

/// Initial state
class NotificationInitial extends NotificationState {
  const NotificationInitial();
}

/// Loading state
class NotificationLoading extends NotificationState {
  const NotificationLoading();
}

/// Loaded state with notifications
class NotificationLoaded extends NotificationState {
  final List<NotificationModel> notifications;
  final int unreadCount;

  const NotificationLoaded({
    required this.notifications,
    this.unreadCount = 0,
  });

  /// Get unread notifications
  List<NotificationModel> get unreadNotifications =>
      notifications.where((n) => !n.isRead).toList();

  /// Get read notifications
  List<NotificationModel> get readNotifications =>
      notifications.where((n) => n.isRead).toList();

  /// Check if there are any notifications
  bool get hasNotifications => notifications.isNotEmpty;

  /// Check if there are unread notifications
  bool get hasUnread => unreadCount > 0;

  @override
  List<Object?> get props => [notifications, unreadCount];

  NotificationLoaded copyWith({
    List<NotificationModel>? notifications,
    int? unreadCount,
  }) {
    return NotificationLoaded(
      notifications: notifications ?? this.notifications,
      unreadCount: unreadCount ?? this.unreadCount,
    );
  }
}

/// Error state
class NotificationError extends NotificationState {
  final String message;

  const NotificationError(this.message);

  @override
  List<Object?> get props => [message];
}

