  Future<void> updateAppSettings({
    required String userId,
    required Map<String, dynamic> settings,
  });
}

import 'dart:io';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_storage/firebase_storage.dart';
import 'package:pendeza/app/utils/logger.dart';
import 'package:pendeza/features/2_client_profile/domain/repositories/profile_repository.dart';
import '../../../../app/helpers/image_compressor_helper.dart';
import '../../data/models/profile_stats.dart';

/// ============================================================================
/// PROFILE REPOSITORY IMPLEMENTATION - FIXED VERSION
/// ============================================================================
///
/// 🔥 FIXES APPLIED:
///
/// 1. Storage Path: Changed from 'users/{userId}/profile_pic.jpg' to
///    'profile_pictures/{userId}/profile_pic.jpg' to match Firebase Storage rules
///
/// 2. Aggregate Queries: Using regular queries with client-side counting
///    as a fallback when aggregate queries fail due to permissions
///
/// 3. Better error handling and logging
/// ============================================================================

class ProfileRepositoryImpl implements ProfileRepository {
  final FirebaseFirestore _db = FirebaseFirestore.instance;
  final FirebaseStorage _storage = FirebaseStorage.instance;

  @override
  Future<ProfileStats> getUserStats(String userId) async {
    try {
      // Try aggregate queries first (more efficient)
      return await _getUserStatsWithAggregate(userId);
    } catch (e) {
      // Fallback to regular queries if aggregate fails (permission issues)
      log.w('ProfileRepo: Aggregate query failed, falling back to regular queries', error: e);
      return await _getUserStatsWithRegularQueries(userId);
    }
  }

  /// Primary method: Use aggregate queries (more efficient)
  Future<ProfileStats> _getUserStatsWithAggregate(String userId) async {
    // 1. Count Bookings
    final bookingsCountQuery = await _db
        .collection('appointments')
        .where('clientId', isEqualTo: userId)
        .count()
        .get();

    // 2. Count Reviews
    final reviewsCountQuery = await _db
        .collection('reviews')
        .where('userId', isEqualTo: userId)
        .count()
        .get();

    // 3. Count Favorites (subcollection)
    final favoritesCountQuery = await _db
        .collection('users')
        .doc(userId)
        .collection('favorites')
        .count()
        .get();

    log.d('ProfileRepo: Stats loaded via aggregate - '
        'bookings: ${bookingsCountQuery.count}, '
        'reviews: ${reviewsCountQuery.count}, '
        'favorites: ${favoritesCountQuery.count}');

    return ProfileStats(
      totalBookings: bookingsCountQuery.count ?? 0,
      totalReviews: reviewsCountQuery.count ?? 0,
      totalFavorites: favoritesCountQuery.count ?? 0,
    );
  }

  /// Fallback method: Use regular queries with client-side counting
  Future<ProfileStats> _getUserStatsWithRegularQueries(String userId) async {
    try {
      // 1. Count Bookings
      final bookingsSnapshot = await _db
          .collection('appointments')
          .where('clientId', isEqualTo: userId)
          .limit(1000)
          .get();
      final bookingsCount = bookingsSnapshot.docs.length;

      // 2. Count Reviews
      final reviewsSnapshot = await _db
          .collection('reviews')
          .where('userId', isEqualTo: userId)
          .limit(1000)
          .get();
      final reviewsCount = reviewsSnapshot.docs.length;

      // 3. Count Favorites
      final favoritesSnapshot = await _db
          .collection('users')
          .doc(userId)
          .collection('favorites')
          .limit(1000)
          .get();
      final favoritesCount = favoritesSnapshot.docs.length;

      log.d('ProfileRepo: Stats loaded via regular queries - '
          'bookings: $bookingsCount, '
          'reviews: $reviewsCount, '
          'favorites: $favoritesCount');

      return ProfileStats(
        totalBookings: bookingsCount,
        totalReviews: reviewsCount,
        totalFavorites: favoritesCount,
      );
    } catch (e, s) {
      log.e('ProfileRepo: Failed to fetch stats for $userId', error: e, stackTrace: s);
      return const ProfileStats();
    }
  }

  @override
  Future<String> updateProfileImage({
    required String userId,
    required File imageFile,
  }) async {
    try {
      // 1. Compress the image to save bandwidth and storage cost
      final compressedFile = await ImageCompressionHelper.compressProfilePicture(imageFile);
      final fileToUpload = compressedFile ?? imageFile;

      // ================================================================
      // 🔥 FIX: Use correct path that matches Firebase Storage rules!
      //
      // Your storage rules allow writes to:
      //   match /profile_pictures/{userId}/{allPaths=**}
      //
      // But the old code was uploading to:
      //   users/{userId}/profile_pic.jpg
      //
      // This path mismatch caused:
      // 1. Upload might fail due to permission denied
      // 2. Or upload to wrong location that isn't persisted properly
      // ================================================================
      final ref = _storage.ref().child('profile_pictures/$userId/profile_pic.jpg');

      log.i('ProfileRepo: Uploading profile image to: profile_pictures/$userId/profile_pic.jpg');

      final uploadTask = await ref.putFile(fileToUpload);
      final downloadUrl = await uploadTask.ref.getDownloadURL();

      log.i('ProfileRepo: Upload successful. URL: $downloadUrl');

      // 3. Update Firestore User Document
      await _db.collection('users').doc(userId).update({
        'profilePictureUrl': downloadUrl,
        'updatedAt': FieldValue.serverTimestamp(),
      });

      log.i('ProfileRepo: Updated user document with new profile picture URL');

      return downloadUrl;
    } catch (e, s) {
      log.e('ProfileRepo: Failed to upload image', error: e, stackTrace: s);
      throw Exception('Failed to upload image. Please try again.');
    }
  }

  @override
  Future<void> updateProfileData({
    required String userId,
    required Map<String, dynamic> data,
  }) async {
    try {
      // Add timestamp
      final updateData = Map<String, dynamic>.from(data);
      updateData['updatedAt'] = FieldValue.serverTimestamp();

      await _db.collection('users').doc(userId).update(updateData);
      log.i('ProfileRepo: Updated profile data for $userId');
    } catch (e, s) {
      log.e('ProfileRepo: Failed to update profile data', error: e, stackTrace: s);
      throw Exception('Failed to update profile.');
    }
  }

  @override
  Future<void> updateAppSettings({
    required String userId,
    required Map<String, dynamic> settings,
  }) async {
    try {
      await _db.collection('users').doc(userId).update({
        'settings': settings,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      log.i('ProfileRepo: Updated app settings for $userId');
    } catch (e) {
      log.e('ProfileRepo: Failed to update settings', error: e);
    }
  }
}

// profile_bloc.dart
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:pendeza/app/utils/logger.dart';
import 'package:pendeza/features/0_auth/presentation/bloc/auth_bloc.dart';
// To trigger ReloadUser

import '../../../0_auth/presentation/bloc/auth_event.dart';
import '../../data/models/profile_stats.dart';
import '../../domain/repositories/profile_repository.dart';
import 'profile_event.dart';
import 'profile_state.dart';

class ProfileBloc extends Bloc<ProfileEvent, ProfileState> {
  final ProfileRepository _profileRepository;
  final AuthBloc _authBloc;

  ProfileBloc({
    required ProfileRepository profileRepository,
    required AuthBloc authBloc,
  })  : _profileRepository = profileRepository,
        _authBloc = authBloc,
        super(ProfileInitial()) {
    on<LoadProfile>(_onLoadProfile);
    on<UpdateProfileImage>(_onUpdateProfileImage);
    on<UpdateProfileInfo>(_onUpdateProfileInfo);
  }

  Future<void> _onLoadProfile(
      LoadProfile event,
      Emitter<ProfileState> emit,
      ) async {
    emit(ProfileLoading());
    try {
      final stats = await _profileRepository.getUserStats(event.userId);
      emit(ProfileLoaded(stats: stats));
    } catch (e) {
      log.e('ProfileBloc: Error loading profile', error: e);
      emit(const ProfileError('Could not load profile data'));
    }
  }

  Future<void> _onUpdateProfileImage(
      UpdateProfileImage event,
      Emitter<ProfileState> emit,
      ) async {
    // Preserve current stats if possible
    ProfileStats? currentStats;
    if (state is ProfileLoaded) {
      currentStats = (state as ProfileLoaded).stats;
    }

    emit(ProfileImageUploading(previousStats: currentStats));

    try {
      // 1. Upload logic via repo
      await _profileRepository.updateProfileImage(
        userId: event.userId,
        imageFile: event.imageFile,
      );

      // 2. IMPORTANT: Tell AuthBloc to reload the user!
      // This ensures the sidebar, header, and other auth-dependent widgets
      // see the new image URL immediately.
      _authBloc.add(ReloadUser());

      // 3. Emit Success (which UI can listen to show a snackbar)
      emit(const ProfileUpdateSuccess('Profile picture updated!'));

      // 4. Return to Loaded state
      if (currentStats != null) {
        emit(ProfileLoaded(stats: currentStats));
      }
    } catch (e) {
      emit(const ProfileError('Failed to upload image'));
      // Fallback
      if (currentStats != null) {
        emit(ProfileLoaded(stats: currentStats));
      }
    }
  }

  Future<void> _onUpdateProfileInfo(
      UpdateProfileInfo event,
      Emitter<ProfileState> emit,
      ) async {
    emit(ProfileLoading());
    try {
      await _profileRepository.updateProfileData(
        userId: event.userId,
        data: event.data,
      );

      // Sync AuthBloc
      _authBloc.add(ReloadUser());

      emit(const ProfileUpdateSuccess('Profile updated successfully'));

      // Re-fetch stats to return to stable state
      add(LoadProfile(userId: event.userId));
    } catch (e) {
      emit(const ProfileError('Failed to update profile info'));
    }
  }
}

// profile_event.dart
import 'dart:io';
import 'package:equatable/equatable.dart';

abstract class ProfileEvent extends Equatable {
  const ProfileEvent();

  @override
  List<Object?> get props => [];
}

/// Triggered when the profile screen is opened.
/// Fetches stats and ensures data is fresh.
class LoadProfile extends ProfileEvent {
  final String userId;
  final bool forceRefresh;

  const LoadProfile({required this.userId, this.forceRefresh = false});

  @override
  List<Object?> get props => [userId, forceRefresh];
}

/// Triggered when user selects a new photo from gallery/camera.
class UpdateProfileImage extends ProfileEvent {
  final String userId;
  final File imageFile;

  const UpdateProfileImage({required this.userId, required this.imageFile});

  @override
  List<Object?> get props => [userId, imageFile];
}

/// Triggered when user edits name, phone, gender, etc.
class UpdateProfileInfo extends ProfileEvent {
  final String userId;
  final Map<String, dynamic> data; // e.g. {'fullName': 'New Name'}

  const UpdateProfileInfo({required this.userId, required this.data});

  @override
  List<Object?> get props => [userId, data];
}

// profile_state.dart
import 'package:equatable/equatable.dart';
import '../../data/models/profile_stats.dart';


abstract class ProfileState extends Equatable {
  const ProfileState();

  @override
  List<Object?> get props => [];
}

class ProfileInitial extends ProfileState {}

class ProfileLoading extends ProfileState {}

/// The main state for the profile screen.
class ProfileLoaded extends ProfileState {
  final ProfileStats stats;
  // We don't store the User object here because AuthBloc is the source of truth for User.
  // We only store the "Extra" data that AuthBloc doesn't care about (stats).

  const ProfileLoaded({required this.stats});

  @override
  List<Object?> get props => [stats];
}

/// A specific loading state for image uploading (so we can show a progress spinner on the avatar)
class ProfileImageUploading extends ProfileState {
  final ProfileStats? previousStats; // Keep showing stats while uploading
  const ProfileImageUploading({this.previousStats});
}

class ProfileError extends ProfileState {
  final String message;
  const ProfileError(this.message);

  @override
  List<Object?> get props => [message];
}

class ProfileUpdateSuccess extends ProfileState {
  final String message;
  const ProfileUpdateSuccess(this.message);
}

