  Widget _buildSectionTitle(ThemeData theme, String title) {
    return Padding(
      padding: const EdgeInsets.only(bottom: AppConstants.padS),
      child: Text(
        title,
        style: theme.textTheme.labelLarge?.copyWith(
          color: theme.colorScheme.primary,
          fontWeight: FontWeight.bold,
        ),
      ),
    );
  }

  Widget _buildDetailRow(ThemeData theme, IconData icon, String text) {
    return Row(
      children: [
        Icon(icon, size: 18, color: theme.colorScheme.onSurfaceVariant),
        const SizedBox(width: AppConstants.padM),
        Expanded(
          child: Text(text, style: theme.textTheme.bodyMedium),
        ),
      ],
    );
  }

  Widget _buildStatusChip(ThemeData theme, String status) {
    Color statusColor;
    Color backgroundColor;

    switch (status.toLowerCase()) {
      case 'confirmed':
        statusColor = Colors.blue;
        backgroundColor = Colors.blue.withOpacity(0.1);
        break;
      case 'completed':
        statusColor = Colors.green;
        backgroundColor = Colors.green.withOpacity(0.1);
        break;
      case 'cancelled':
        statusColor = Colors.red;
        backgroundColor = Colors.red.withOpacity(0.1);
        break;
      case 'noshow':
        statusColor = Colors.orange;
        backgroundColor = Colors.orange.withOpacity(0.1);
        break;
      default:
        statusColor = theme.colorScheme.primary;
        backgroundColor = theme.colorScheme.primary.withOpacity(0.1);
    }

    return Container(
      padding: const EdgeInsets.symmetric(
        horizontal: AppConstants.padM,
        vertical: AppConstants.padS,
      ),
      decoration: BoxDecoration(
        color: backgroundColor,
        borderRadius: AppConstants.radiusS,
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(Icons.info_outline_rounded, size: 18, color: statusColor),
          const SizedBox(width: AppConstants.padS),
          Text(
            status.toUpperCase(),
            style: theme.textTheme.labelMedium?.copyWith(
              color: statusColor,
              fontWeight: FontWeight.bold,
              letterSpacing: 0.5,
            ),
          ),
        ],
      ),
    );
  }

  // ADDED: Handle marking appointment as complete
  Future<void> _handleMarkComplete(BuildContext context) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Mark as Complete'),
        content: const Text(
          'Are you sure you want to mark this appointment as completed?',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Cancel'),
          ),
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            style: TextButton.styleFrom(foregroundColor: Colors.green),
            child: const Text('Mark Complete'),
          ),
        ],
      ),
    );

    if (confirmed == true && mounted) {
      try {
        await _firestoreService.updateAppointmentStatus(
          widget.appointment.id,
          'Completed',
        );
        if (mounted) {
          Navigator.of(context).pop(); // Close dialog
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('Appointment marked as completed'),
              backgroundColor: Colors.green,
            ),
          );
        }
      } catch (e) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text('Error: ${e.toString()}'),
              backgroundColor: Colors.red,
            ),
          );
        }
      }
    }
  }

  // ADDED: Handle cancelling appointment
  Future<void> _handleCancel(BuildContext context) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Cancel Appointment'),
        content: const Text(
          'Are you sure you want to cancel this appointment? This action cannot be undone.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('No, Keep It'),
          ),
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            style: TextButton.styleFrom(foregroundColor: Colors.red),
            child: const Text('Yes, Cancel'),
          ),
        ],
      ),
    );

    if (confirmed == true && mounted) {
      try {
        await _firestoreService.updateAppointmentStatus(
          widget.appointment.id,
          'Cancelled',
        );
        if (mounted) {
          Navigator.of(context).pop(); // Close dialog
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('Appointment cancelled'),
              backgroundColor: Colors.orange,
            ),
          );
        }
      } catch (e) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text('Error: ${e.toString()}'),
              backgroundColor: Colors.red,
            ),
          );
        }
      }
    }
  }
}

import 'package:equatable/equatable.dart';

/// Model representing client statistics and insights
class ClientStats extends Equatable {
  final String clientId;
  final String clientName;
  final String? phoneNumber;
  final String? email;
  final String? profilePictureUrl;
  final int totalAppointments;
  final int completedAppointments;
  final int cancelledAppointments;
  final double totalSpent;
  final DateTime firstVisit;
  final DateTime lastVisit;
  final List<String> favoriteServices;

  const ClientStats({
    required this.clientId,
    required this.clientName,
    this.phoneNumber,
    this.email,
    this.profilePictureUrl,
    required this.totalAppointments,
    required this.completedAppointments,
    required this.cancelledAppointments,
    required this.totalSpent,
    required this.firstVisit,
    required this.lastVisit,
    required this.favoriteServices,
  });

  @override
  List<Object?> get props => [
    clientId,
    clientName,
    phoneNumber,
    email,
    profilePictureUrl,
    totalAppointments,
    completedAppointments,
    cancelledAppointments,
    totalSpent,
    firstVisit,
    lastVisit,
    favoriteServices,
  ];

  /// Calculate completion rate percentage
  double get completionRate {
    if (totalAppointments == 0) return 0.0;
    return (completedAppointments / totalAppointments) * 100;
  }

  /// Check if client is a regular (3+ completed appointments)
  bool get isRegularClient => completedAppointments >= 3;

  /// Calculate average spending per visit
  double get averageSpending {
    if (completedAppointments == 0) return 0.0;
    return totalSpent / completedAppointments;
  }

  ClientStats copyWith({
    String? clientId,
    String? clientName,
    String? phoneNumber,
    String? email,
    String? profilePictureUrl,
    int? totalAppointments,
    int? completedAppointments,
    int? cancelledAppointments,
    double? totalSpent,
    DateTime? firstVisit,
    DateTime? lastVisit,
    List<String>? favoriteServices,
  }) {
    return ClientStats(
      clientId: clientId ?? this.clientId,
      clientName: clientName ?? this.clientName,
      phoneNumber: phoneNumber ?? this.phoneNumber,
      email: email ?? this.email,
      profilePictureUrl: profilePictureUrl ?? this.profilePictureUrl,
      totalAppointments: totalAppointments ?? this.totalAppointments,
      completedAppointments:
      completedAppointments ?? this.completedAppointments,
      cancelledAppointments:
      cancelledAppointments ?? this.cancelledAppointments,
      totalSpent: totalSpent ?? this.totalSpent,
      firstVisit: firstVisit ?? this.firstVisit,
      lastVisit: lastVisit ?? this.lastVisit,
      favoriteServices: favoriteServices ?? this.favoriteServices,
    );
  }
}

