  }

  Future<void> _onLoadClients(
      LoadClients event,
      Emitter<ClientManagementState> emit,
      ) async {
    emit(const ClientManagementLoading());
    await _fetchClients(emit, null);
  }

  Future<void> _onSearchClients(
      SearchClients event,
      Emitter<ClientManagementState> emit,
      ) async {
    await _fetchClients(emit, event.query);
  }

  Future<void> _onRefreshClients(
      RefreshClients event,
      Emitter<ClientManagementState> emit,
      ) async {
    // Keep current search query if exists
    final currentState = state;
    final query = currentState is ClientManagementLoaded
        ? currentState.searchQuery
        : null;
    await _fetchClients(emit, query);
  }

  Future<void> _fetchClients(
      Emitter<ClientManagementState> emit,
      String? searchQuery,
      ) async {
    try {
      log.i('ClientManagementBloc: Fetching clients...');

      // Get authenticated owner's salon
      final authState = _authBloc.state;
      if (authState is! Authenticated) {
        throw Exception('User not authenticated');
      }

      // Get salon ID (cache it for future requests)
      if (_currentSalonId == null) {
        final salon = await _firestoreService.getSalonForOwner(
          ownerId: authState.user.uid,
        );
        if (salon == null) {
          throw Exception('No salon found for owner');
        }
        _currentSalonId = salon.id;
      }

      final salonId = _currentSalonId!;

      // Fetch or search clients
      final clients = searchQuery != null && searchQuery.isNotEmpty
          ? await _repository.searchClients(salonId, searchQuery)
          : await _repository.getAllClientsForSalon(salonId);

      log.i('ClientManagementBloc: Loaded ${clients.length} clients');

      emit(ClientManagementLoaded(
        clients: clients,
        searchQuery: searchQuery,
      ));
    } catch (e, s) {
      log.e('ClientManagementBloc: Error fetching clients',
          error: e, stackTrace: s);
      emit(ClientManagementError('Failed to load clients: ${e.toString()}'));
    }
  }
}

import 'package:equatable/equatable.dart';

abstract class ClientManagementEvent extends Equatable {
  const ClientManagementEvent();

  @override
  List<Object?> get props => [];
}

/// Event to load all clients for the salon
class LoadClients extends ClientManagementEvent {
  const LoadClients();
}

/// Event to search clients
class SearchClients extends ClientManagementEvent {
  final String query;

  const SearchClients(this.query);

  @override
  List<Object?> get props => [query];
}

/// Event to load a specific client's details
class LoadClientDetails extends ClientManagementEvent {
  final String clientId;

  const LoadClientDetails(this.clientId);

  @override
  List<Object?> get props => [clientId];
}

/// Event to refresh client list
class RefreshClients extends ClientManagementEvent {
  const RefreshClients();
}

import 'package:equatable/equatable.dart';
import '../../domain/models/client_stats.dart';


abstract class ClientManagementState extends Equatable {
  const ClientManagementState();

  @override
  List<Object?> get props => [];
}

/// Initial state
class ClientManagementInitial extends ClientManagementState {
  const ClientManagementInitial();
}

/// Loading clients
class ClientManagementLoading extends ClientManagementState {
  const ClientManagementLoading();
}

/// Clients loaded successfully
class ClientManagementLoaded extends ClientManagementState {
  final List<ClientStats> clients;
  final String? searchQuery;

  const ClientManagementLoaded({
    required this.clients,
    this.searchQuery,
  });

  @override
  List<Object?> get props => [clients, searchQuery];
}

/// Error loading clients
class ClientManagementError extends ClientManagementState {
  final String message;

  const ClientManagementError(this.message);

  @override
  List<Object?> get props => [message];
}

