class FavoriteServicesWidget extends StatelessWidget {
  final ClientStats clientStats;

  const FavoriteServicesWidget({
    super.key,
    required this.clientStats,
  });

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    if (clientStats.favoriteServices.isEmpty) {
      return const SizedBox.shrink();
    }

    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: AppConstants.padL),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            'Favorite Services',
            style: theme.textTheme.headlineSmall?.copyWith(
              fontWeight: FontWeight.bold,
            ),
          ),
          const SizedBox(height: AppConstants.padM),
          _FavoriteServicesList(serviceIds: clientStats.favoriteServices),
        ],
      ),
    );
  }
}

class _FavoriteServicesList extends StatelessWidget {
  final List<String> serviceIds;

  const _FavoriteServicesList({required this.serviceIds});

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final firestoreService = sl<FirestoreService>();

    return FutureBuilder<List<ServiceModel>>(
      future: _fetchServices(firestoreService, serviceIds),
      builder: (context, snapshot) {
        if (snapshot.connectionState == ConnectionState.waiting) {
          return CustomCard(
            child: Center(
              child: Padding(
                padding: const EdgeInsets.all(AppConstants.padL),
                child: CircularProgressIndicator(
                  color: theme.colorScheme.primary,
                ),
              ),
            ),
          );
        }

        if (snapshot.hasError || !snapshot.hasData || snapshot.data!.isEmpty) {
          return const SizedBox.shrink();
        }

        final services = snapshot.data!;
        return Column(
          children: services
              .asMap()
              .entries
              .map((entry) => Padding(
            padding: const EdgeInsets.only(bottom: AppConstants.padS),
            child: _FavoriteServiceItem(
              service: entry.value,
              rank: entry.key + 1,
            ),
          ))
              .toList(),
        );
      },
    );
  }

  Future<List<ServiceModel>> _fetchServices(
      FirestoreService firestoreService,
      List<String> serviceIds,
      ) async {
    final services = <ServiceModel>[];
    for (final serviceId in serviceIds) {
      try {
        final service = await firestoreService.getServiceDetails(serviceId);
        services.add(service);
      } catch (e) {
        continue;
      }
    }
    return services;
  }
}

class _FavoriteServiceItem extends StatelessWidget {
  final ServiceModel service;
  final int rank;

  const _FavoriteServiceItem({
    required this.service,
    required this.rank,
  });

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return CustomCard(
      padding: const EdgeInsets.all(AppConstants.padM),
      child: Row(
        children: [
          // Rank badge
          Container(
            width: 32,
            height: 32,
            decoration: BoxDecoration(
              color: _getRankColor(rank).withOpacity(0.1),
              shape: BoxShape.circle,
            ),
            child: Center(
              child: Text(
                '#$rank',
                style: theme.textTheme.labelMedium?.copyWith(
                  color: _getRankColor(rank),
                  fontWeight: FontWeight.bold,
                ),
              ),
            ),
          ),
          const SizedBox(width: AppConstants.padM),

          // Service details
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  service.name,
                  style: theme.textTheme.titleMedium?.copyWith(
                    fontWeight: FontWeight.bold,
                  ),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
                const SizedBox(height: 2),
                Row(
                  children: [
                    Icon(
                      Icons.schedule_rounded,
                      size: 14,
                      color: theme.colorScheme.onSurface.withOpacity(0.6),
                    ),
                    const SizedBox(width: 4),
                    Text(
                      '${service.durationMinutes} min',
                      style: theme.textTheme.bodySmall?.copyWith(
                        color: theme.colorScheme.onSurface.withOpacity(0.7),
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),

          // Service icon
          Icon(
            Icons.star_rounded,
            color: _getRankColor(rank),
            size: 24,
          ),
        ],
      ),
    );
  }

  Color _getRankColor(int rank) {
    switch (rank) {
      case 1:
        return Colors.amber;
      case 2:
        return Colors.grey[400]!;
      case 3:
        return Colors.brown[300]!;
      default:
        return Colors.grey;
    }
  }
}

import 'package:equatable/equatable.dart';
import 'package:pendeza/shared/models/appointment_model.dart';

/// Model representing dashboard statistics
class DashboardStats extends Equatable {
  final double todayRevenue;
  final int todayAppointmentsCount;
  final int newClientsThisWeek;
  final double occupancyRate;
  final List<AppointmentModel> upcomingToday;
  final DateTime lastUpdated;

  const DashboardStats({
    required this.todayRevenue,
    required this.todayAppointmentsCount,
    required this.newClientsThisWeek,
    required this.occupancyRate,
    required this.upcomingToday,
    required this.lastUpdated,
  });

  @override
  List<Object?> get props => [
    todayRevenue,
    todayAppointmentsCount,
    newClientsThisWeek,
    occupancyRate,
    upcomingToday,
    lastUpdated,
  ];

  /// Creates empty stats for initial state
  factory DashboardStats.empty() {
    return DashboardStats(
      todayRevenue: 0,
      todayAppointmentsCount: 0,
      newClientsThisWeek: 0,
      occupancyRate: 0,
      upcomingToday: [],
      lastUpdated: DateTime.now(),
    );
  }

  DashboardStats copyWith({
    double? todayRevenue,
    int? todayAppointmentsCount,
    int? newClientsThisWeek,
    double? occupancyRate,
    List<AppointmentModel>? upcomingToday,
    DateTime? lastUpdated,
  }) {
    return DashboardStats(
      todayRevenue: todayRevenue ?? this.todayRevenue,
      todayAppointmentsCount:
      todayAppointmentsCount ?? this.todayAppointmentsCount,
      newClientsThisWeek: newClientsThisWeek ?? this.newClientsThisWeek,
      occupancyRate: occupancyRate ?? this.occupancyRate,
      upcomingToday: upcomingToday ?? this.upcomingToday,
      lastUpdated: lastUpdated ?? this.lastUpdated,
    );
  }
}

import 'package:pendeza/shared/models/appointment_model.dart';
import 'package:pendeza/shared/models/salon_model.dart';
import 'package:pendeza/shared/models/service_model.dart'; // Added this import

/// Repository for fetching owner dashboard analytics data
abstract class OwnerDashboardRepository {
  /// Fetches the salon for the current owner
  Future<SalonModel?> getSalonForOwner(String ownerId);

  /// Fetches all appointments for the salon on a specific date
  Future<List<AppointmentModel>> getAppointmentsForDate(
      String salonId,
      DateTime date,
      );

  /// Fetches appointments for a date range
  Future<List<AppointmentModel>> getAppointmentsForDateRange(
      String salonId,
      DateTime startDate,
      DateTime endDate,
      );

  /// Fetches all unique clients who have booked with the salon
  Future<int> getTotalClientsCount(String salonId);

  /// Fetches all services offered by the salon
  Future<List<ServiceModel>> getServicesForSalon(String salonId);

  /// Fetches new clients within a date range
  Future<int> getNewClientsCount(
      String salonId,
      DateTime startDate,
      DateTime endDate,
      );
}

import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:pendeza/app/services/firestore_service.dart';
import 'package:pendeza/shared/models/appointment_model.dart';
import 'package:pendeza/shared/models/salon_model.dart';
import 'package:pendeza/app/utils/logger.dart';
import 'package:pendeza/shared/models/service_model.dart'; // Added this import
import 'owner_dashboard_repository.dart';

class OwnerDashboardRepositoryImpl implements OwnerDashboardRepository {
  final FirestoreService _firestoreService;
  final FirebaseFirestore _db = FirebaseFirestore.instance;

  OwnerDashboardRepositoryImpl(this._firestoreService);

  @override
  Future<SalonModel?> getSalonForOwner(String ownerId) {
    return _firestoreService.getSalonForOwner(ownerId: ownerId);
  }

  @override
  Future<List<AppointmentModel>> getAppointmentsForDate(
      String salonId,
      DateTime date,
      ) async {
    try {
      final startOfDay = DateTime(date.year, date.month, date.day);
      final endOfDay = DateTime(date.year, date.month, date.day, 23, 59, 59);

      final snapshot = await _db
          .collection('appointments')
          .where('salonId', isEqualTo: salonId)
          .where('startTime',
          isGreaterThanOrEqualTo: Timestamp.fromDate(startOfDay))
          .where('startTime', isLessThanOrEqualTo: Timestamp.fromDate(endOfDay))
          .get();

      return snapshot.docs
          .map((doc) => AppointmentModel.fromFirestore(doc))
          .toList();
    } catch (e, s) {
      log.e('Error fetching appointments for date', error: e, stackTrace: s);
      return [];
    }
  }

  @override
  Future<List<AppointmentModel>> getAppointmentsForDateRange(
      String salonId,
      DateTime startDate,
      DateTime endDate,
      ) async {
    try {
      final start = DateTime(startDate.year, startDate.month, startDate.day);
      final end = DateTime(endDate.year, endDate.month, endDate.day, 23, 59, 59);

      final snapshot = await _db
          .collection('appointments')
          .where('salonId', isEqualTo: salonId)
          .where('startTime', isGreaterThanOrEqualTo: Timestamp.fromDate(start))
          .where('startTime', isLessThanOrEqualTo: Timestamp.fromDate(end))
          .get();

      return snapshot.docs
          .map((doc) => AppointmentModel.fromFirestore(doc))
          .toList();
    } catch (e, s) {
      log.e('Error fetching appointments for date range',
          error: e, stackTrace: s);
      return [];
    }
  }

  @override
  Future<int> getTotalClientsCount(String salonId) async {
    try {
      final snapshot = await _db
          .collection('appointments')
          .where('salonId', isEqualTo: salonId)
          .get();

      // Get unique client IDs
      final clientIds = snapshot.docs
          .map((doc) => AppointmentModel.fromFirestore(doc).clientId)
          .toSet();

      return clientIds.length;
    } catch (e, s) {
      log.e('Error fetching total clients count', error: e, stackTrace: s);
      return 0;
    }
  }

  @override
  Future<int> getNewClientsCount(
      String salonId,
      DateTime startDate,
      DateTime endDate,
      ) async {
    try {
      final start = DateTime(startDate.year, startDate.month, startDate.day);
      final end = DateTime(endDate.year, endDate.month, endDate.day, 23, 59, 59);

      // Get all appointments in date range
      final recentSnapshot = await _db
          .collection('appointments')
          .where('salonId', isEqualTo: salonId)
          .where('startTime', isGreaterThanOrEqualTo: Timestamp.fromDate(start))
          .where('startTime', isLessThanOrEqualTo: Timestamp.fromDate(end))
          .get();

      // Get all appointments before start date
      final previousSnapshot = await _db
          .collection('appointments')
          .where('salonId', isEqualTo: salonId)
          .where('startTime', isLessThan: Timestamp.fromDate(start))
          .get();

      // Get unique client IDs from recent appointments
      final recentClients = recentSnapshot.docs
          .map((doc) => AppointmentModel.fromFirestore(doc).clientId)
          .toSet();

      // Get unique client IDs from previous appointments
      final previousClients = previousSnapshot.docs
          .map((doc) => AppointmentModel.fromFirestore(doc).clientId)
          .toSet();

      // New clients are those in recent but not in previous
      final newClients = recentClients.difference(previousClients);

      return newClients.length;
    } catch (e, s) {
      log.e('Error fetching new clients count', error: e, stackTrace: s);
      return 0;
    }
  }

  // Added the new method implementation
  @override
  Future<List<ServiceModel>> getServicesForSalon(String salonId) async {
    try {
      final snapshot = await _db
          .collection('salons')
          .doc(salonId)
          .collection('services')
          .get();
      return snapshot.docs.map((doc) => ServiceModel.fromFirestore(doc)).toList();
    } catch (e, s) {
      log.e('Error fetching services', error: e, stackTrace: s);
      return [];
    }
  }
}

import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:pendeza/features/0_auth/presentation/bloc/auth_bloc.dart';
import 'package:pendeza/features/0_auth/presentation/bloc/auth_state.dart';
import 'package:pendeza/app/utils/logger.dart';
import '../../../../../shared/models/appointment_model.dart';
import '../../domain/models/dashboard_stats.dart';
import '../../domain/repositories/owner_dashboard_repository.dart';
import 'owner_dashboard_event.dart';
import 'owner_dashboard_state.dart';


class OwnerDashboardBloc
    extends Bloc<OwnerDashboardEvent, OwnerDashboardState> {
  final OwnerDashboardRepository _repository;
  final AuthBloc _authBloc;

  OwnerDashboardBloc({
    required OwnerDashboardRepository repository,
    required AuthBloc authBloc,
  })  : _repository = repository,
        _authBloc = authBloc,
        super(const OwnerDashboardInitial()) {
    on<LoadDashboardData>(_onLoadDashboardData);
    on<RefreshDashboardData>(_onRefreshDashboardData);
  }

  Future<void> _onLoadDashboardData(
      LoadDashboardData event,
      Emitter<OwnerDashboardState> emit,
      ) async {
    emit(const OwnerDashboardLoading());
    await _fetchDashboardData(emit);
  }

  Future<void> _onRefreshDashboardData(
      RefreshDashboardData event,
      Emitter<OwnerDashboardState> emit,
      ) async {
    // Don't show loading state on refresh (keeps UI stable)
    await _fetchDashboardData(emit);
  }

  Future<void> _fetchDashboardData(
      Emitter<OwnerDashboardState> emit) async {
    try {
      log.i('OwnerDashboardBloc: Fetching dashboard data...');

      // Get authenticated owner
      final authState = _authBloc.state;
      if (authState is! Authenticated) {
        throw Exception('User not authenticated');
      }

      final ownerId = authState.user.uid;

      // Get salon
      final salon = await _repository.getSalonForOwner(ownerId);
      if (salon == null) {
        throw Exception('No salon found for owner');
      }

      log.d('OwnerDashboardBloc: Found salon: ${salon.salonName}');

      // Calculate date ranges
      final now = DateTime.now();
      final today = DateTime(now.year, now.month, now.day);
      final startOfWeek = today.subtract(Duration(days: today.weekday - 1));
      final endOfWeek = startOfWeek.add(const Duration(days: 6));

      // Fetch all required data in parallel for speed
      final results = await Future.wait([
        _repository.getAppointmentsForDate(salon.id, today),
        _repository.getNewClientsCount(salon.id, startOfWeek, endOfWeek),
      ]);

      final todayAppointments = results[0] as List<AppointmentModel>;
      final newClientsCount = results[1] as int;

      // Calculate today's revenue (only completed/confirmed appointments)
      final todayRevenue = todayAppointments
          .where((app) =>
      app.status.toLowerCase() == 'completed' ||
          app.status.toLowerCase() == 'confirmed')
          .fold<double>(0.0, (sum, app) => sum + app.totalPrice);

      // Count today's appointments (exclude cancelled)
      final todayAppointmentsCount = todayAppointments
          .where((app) => app.status.toLowerCase() != 'cancelled')
          .length;

      // Get upcoming appointments for today (future only)
      final upcomingToday = todayAppointments
          .where((app) =>
      app.startTime.isAfter(now) &&
          app.status.toLowerCase() != 'cancelled')
          .toList();

      // Sort upcoming by start time
      upcomingToday.sort((a, b) => a.startTime.compareTo(b.startTime));

      // Calculate occupancy rate
      // Formula: (Total booked minutes / Total available minutes) * 100
      final occupancyRate = _calculateOccupancyRate(
        todayAppointments
            .where((app) => app.status.toLowerCase() != 'cancelled')
            .toList(),
        salon.openingTime,
        salon.closingTime,
      );

      log.i('OwnerDashboardBloc: Dashboard stats calculated successfully');
      log.d('Today Revenue: TSh ${todayRevenue.toStringAsFixed(0)}');
      log.d('Today Appointments: $todayAppointmentsCount');
      log.d('New Clients This Week: $newClientsCount');
      log.d('Occupancy Rate: ${occupancyRate.toStringAsFixed(1)}%');
      log.d('Upcoming Today: ${upcomingToday.length}');

      final stats = DashboardStats(
        todayRevenue: todayRevenue,
        todayAppointmentsCount: todayAppointmentsCount,
        newClientsThisWeek: newClientsCount,
        occupancyRate: occupancyRate,
        upcomingToday: upcomingToday.take(5).toList(), // Show max 5
        lastUpdated: DateTime.now(),
      );

      emit(OwnerDashboardLoaded(
        stats: stats,
        salonName: salon.salonName,
      ));
    } catch (e, s) {
      log.e('OwnerDashboardBloc: Error fetching dashboard data',
          error: e, stackTrace: s);
      emit(OwnerDashboardError('Failed to load dashboard: ${e.toString()}'));
    }
  }

  /// Calculates occupancy rate based on booked time vs available time
  double _calculateOccupancyRate(
      List<AppointmentModel> appointments,
      String openingTime,
      String closingTime,
      ) {
    try {
      // Parse opening/closing times
      final openingParts = openingTime.split(':');
      final closingParts = closingTime.split(':');

      final openingHour = int.parse(openingParts[0]);
      final openingMinute = int.parse(openingParts[1]);
      final closingHour = int.parse(closingParts[0]);
      final closingMinute = int.parse(closingParts[1]);

      // Calculate total available minutes
      final totalAvailableMinutes =
          (closingHour * 60 + closingMinute) - (openingHour * 60 + openingMinute);

      if (totalAvailableMinutes <= 0) return 0.0;

      // Calculate total booked minutes
      final totalBookedMinutes = appointments.fold<int>(
        0,
            (sum, app) => sum + app.durationMinutes,
      );

      // Calculate percentage
      final occupancyRate =
          (totalBookedMinutes / totalAvailableMinutes) * 100;

      // Cap at 100% (in case of overlapping appointments)
      return occupancyRate > 100 ? 100.0 : occupancyRate;
    } catch (e) {
      log.e('Error calculating occupancy rate', error: e);
      return 0.0;
    }
  }
}

import 'package:equatable/equatable.dart';

abstract class OwnerDashboardEvent extends Equatable {
  const OwnerDashboardEvent();

  @override
  List<Object> get props => [];
}

/// Event to load/refresh dashboard data
class LoadDashboardData extends OwnerDashboardEvent {
  const LoadDashboardData();
}

/// Event to refresh dashboard data (pull-to-refresh)
class RefreshDashboardData extends OwnerDashboardEvent {
  const RefreshDashboardData();
}

import 'package:equatable/equatable.dart';
import '../../domain/models/dashboard_stats.dart';


abstract class OwnerDashboardState extends Equatable {
  const OwnerDashboardState();

  @override
  List<Object> get props => [];
}

/// Initial state
class OwnerDashboardInitial extends OwnerDashboardState {
  const OwnerDashboardInitial();
}

/// Loading dashboard data
class OwnerDashboardLoading extends OwnerDashboardState {
  const OwnerDashboardLoading();
}

/// Dashboard data loaded successfully
class OwnerDashboardLoaded extends OwnerDashboardState {
  final DashboardStats stats;
  final String salonName;

  const OwnerDashboardLoaded({
    required this.stats,
    required this.salonName,
  });

  @override
  List<Object> get props => [stats, salonName];
}

/// Error loading dashboard data
class OwnerDashboardError extends OwnerDashboardState {
  final String message;

  const OwnerDashboardError(this.message);

  @override
  List<Object> get props => [message];
}

