        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Icon(Icons.warning_amber_rounded, color: Colors.orange),
              const SizedBox(width: 8),
              Text(
                '⚠️ DEV ONLY: Video Data Seeder',
                style: theme.textTheme.titleMedium?.copyWith(
                  fontWeight: FontWeight.bold,
                  color: Colors.orange.shade800,
                ),
              ),
            ],
          ),
          const SizedBox(height: 8),
          Text(
            'Tap to seed 16 sample videos to Firestore.\nRemove this section before production!',
            style: theme.textTheme.bodySmall?.copyWith(
              color: Colors.orange.shade700,
            ),
          ),
          const SizedBox(height: AppConstants.padM),

          // Result message
          if (_seedResult != null)
            Container(
              padding: const EdgeInsets.all(8),
              margin: const EdgeInsets.only(bottom: 8),
              decoration: BoxDecoration(
                color: _seedResult!.contains('✅')
                    ? Colors.green.withOpacity(0.1)
                    : Colors.red.withOpacity(0.1),
                borderRadius: BorderRadius.circular(8),
              ),
              child: Text(
                _seedResult!,
                style: TextStyle(
                  color: _seedResult!.contains('✅')
                      ? Colors.green.shade700
                      : Colors.red.shade700,
                  fontWeight: FontWeight.w500,
                ),
              ),
            ),

          Row(
            children: [
              // Seed Button
              Expanded(
                child: ElevatedButton.icon(
                  onPressed: _isSeeding ? null : _seedVideoData,
                  icon: _isSeeding
                      ? const SizedBox(
                    width: 16,
                    height: 16,
                    child: CircularProgressIndicator(
                      strokeWidth: 2,
                      color: Colors.white,
                    ),
                  )
                      : const Icon(Icons.cloud_upload),
                  label: Text(_isSeeding ? 'Seeding...' : 'Seed Videos'),
                  style: ElevatedButton.styleFrom(
                    backgroundColor: Colors.orange,
                    foregroundColor: Colors.white,
                  ),
                ),
              ),
              const SizedBox(width: 8),
              // Delete Button
              Expanded(
                child: OutlinedButton.icon(
                  onPressed: _isSeeding ? null : _deleteVideoData,
                  icon: const Icon(Icons.delete_outline),
                  label: const Text('Delete All'),
                  style: OutlinedButton.styleFrom(
                    foregroundColor: Colors.red,
                    side: const BorderSide(color: Colors.red),
                  ),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Future<void> _seedVideoData() async {
    setState(() {
      _isSeeding = true;
      _seedResult = null;
    });

    try {
      final seeder = VideoDataSeederService();
      final count = await seeder.seedSalonVideos();

      setState(() {
        _seedResult = '✅ Successfully seeded $count videos!';
      });
    } catch (e) {
      setState(() {
        _seedResult = '❌ Error: $e';
      });
    } finally {
      setState(() {
        _isSeeding = false;
      });
    }
  }

  Future<void> _deleteVideoData() async {
    // Show confirmation dialog
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('Delete All Videos?'),
        content: const Text(
          'This will delete ALL videos from the salon_videos collection. This cannot be undone.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('Cancel'),
          ),
          TextButton(
            onPressed: () => Navigator.pop(context, true),
            style: TextButton.styleFrom(foregroundColor: Colors.red),
            child: const Text('Delete'),
          ),
        ],
      ),
    );

    if (confirmed != true) return;

    setState(() {
      _isSeeding = true;
      _seedResult = null;
    });

    try {
      final seeder = VideoDataSeederService();
      final count = await seeder.deleteAllSeededVideos();

      setState(() {
        _seedResult = '✅ Deleted $count videos!';
      });
    } catch (e) {
      setState(() {
        _seedResult = '❌ Error: $e';
      });
    } finally {
      setState(() {
        _isSeeding = false;
      });
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════

  Widget _buildAnimatedKpi(
      BuildContext context, {
        required int index,
        required Widget child,
      }) {
    return TweenAnimationBuilder<double>(
      tween: Tween(begin: 0.0, end: 1.0),
      duration: Duration(milliseconds: 400 + (index * 100)),
      curve: Curves.easeOutCubic,
      builder: (context, value, _) {
        return Transform.scale(
          scale: 0.8 + (0.2 * value),
          child: Opacity(
            opacity: value,
            child: child,
          ),
        );
      },
    );
  }

  Widget _buildManageSalonCard(BuildContext context, ThemeData theme) {
    return GestureDetector(
      onTap: () => context.push(AppRoutes.ownerSalonProfile),
      child: Container(
        width: double.infinity,
        padding: const EdgeInsets.all(AppConstants.padL),
        decoration: BoxDecoration(
          gradient: LinearGradient(
            colors: [
              theme.colorScheme.primary,
              theme.colorScheme.primary.withValues(alpha: 0.8),
            ],
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
          ),
          borderRadius: AppConstants.radiusL,
          boxShadow: [
            BoxShadow(
              color: theme.colorScheme.primary.withValues(alpha: 0.3),
              blurRadius: 12,
              offset: const Offset(0, 4),
            ),
          ],
        ),
        child: Row(
          children: [
            Container(
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: Colors.white.withValues(alpha: 0.2),
                borderRadius: BorderRadius.circular(12),
              ),
              child: const Icon(
                Icons.store_rounded,
                color: Colors.white,
                size: 28,
              ),
            ),
            const SizedBox(width: AppConstants.padM),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'owner.dashboard.manage_salon'.tr(),
                    style: theme.textTheme.titleMedium?.copyWith(
                      color: Colors.white,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 4),
                  Text(
                    'owner.dashboard.manage_salon_desc'.tr(),
                    style: theme.textTheme.bodySmall?.copyWith(
                      color: Colors.white.withValues(alpha: 0.9),
                    ),
                  ),
                ],
              ),
            ),
            const Icon(
              Icons.arrow_forward_ios_rounded,
              color: Colors.white,
              size: 20,
            ),
          ],
        ),
      ),
    );
  }
}

