class _EditAmenitiesDialogState extends State<_EditAmenitiesDialog> {
  late List<String> _selectedAmenities;

  @override
  void initState() {
    super.initState();
    _selectedAmenities = List.from(widget.salon.amenities ?? []);
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return Dialog(
      child: SingleChildScrollView(
        child: Padding(
          padding: const EdgeInsets.all(AppConstants.padL),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              // Header
              Row(
                children: [
                  Expanded(
                    child: Text(
                      'Select Amenities',
                      style: theme.textTheme.titleLarge?.copyWith(
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  ),
                  IconButton(
                    icon: const Icon(Icons.close),
                    onPressed: () => Navigator.pop(context),
                  ),
                ],
              ),
              const SizedBox(height: AppConstants.padM),

              Text(
                'Select all that apply to your salon',
                style: theme.textTheme.bodyMedium?.copyWith(
                  color: theme.colorScheme.onSurface.withOpacity(0.7),
                ),
              ),
              const SizedBox(height: AppConstants.padL),

              // Amenities List
              ...AVAILABLE_AMENITIES.map((amenity) {
                final isSelected = _selectedAmenities.contains(amenity);
                return CheckboxListTile(
                  value: isSelected,
                  onChanged: (value) {
                    setState(() {
                      if (value == true) {
                        _selectedAmenities.add(amenity);
                      } else {
                        _selectedAmenities.remove(amenity);
                      }
                    });
                  },
                  title: Row(
                    children: [
                      Icon(
                        _getAmenityIcon(amenity),
                        size: 20,
                        color: theme.colorScheme.primary,
                      ),
                      const SizedBox(width: AppConstants.padS),
                      Text(amenity),
                    ],
                  ),
                  contentPadding: EdgeInsets.zero,
                  controlAffinity: ListTileControlAffinity.leading,
                );
              }),

              const SizedBox(height: AppConstants.padL),

              // Selected count
              Container(
                padding: const EdgeInsets.all(AppConstants.padM),
                decoration: BoxDecoration(
                  color: theme.colorScheme.primaryContainer.withOpacity(0.3),
                  // FIX: Use radiusValM (double) instead of radiusM (BorderRadius)
                  borderRadius: BorderRadius.circular(AppConstants.radiusValM),
                ),
                child: Row(
                  children: [
                    Icon(
                      Icons.check_circle_outline,
                      size: 20,
                      color: theme.colorScheme.primary,
                    ),
                    const SizedBox(width: AppConstants.padS),
                    Expanded(
                      child: Text(
                        '${_selectedAmenities.length} amenities selected',
                        style: theme.textTheme.bodySmall,
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: AppConstants.padL),

              // Save Button
              SizedBox(
                width: double.infinity,
                child: ElevatedButton(
                  onPressed: _handleSave,
                  style: ElevatedButton.styleFrom(
                    padding: const EdgeInsets.all(AppConstants.padM),
                  ),
                  child: const Text('Save Amenities'),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  IconData _getAmenityIcon(String amenity) {
    switch (amenity.toLowerCase()) {
      case 'wifi':
        return Icons.wifi_rounded;
      case 'parking':
        return Icons.local_parking_rounded;
      case 'air conditioning':
        return Icons.ac_unit_rounded;
      case 'credit cards':
        return Icons.credit_card_rounded;
      case 'mobile money':
        return Icons.phone_android_rounded;
      case 'wheelchair accessible':
        return Icons.accessible_rounded;
      case 'kids friendly':
        return Icons.child_friendly_rounded;
      case 'refreshments':
        return Icons.local_cafe_rounded;
      case 'magazine/books':
        return Icons.menu_book_rounded;
      case 'tv':
        return Icons.tv_rounded;
      default:
        return Icons.check_circle_rounded;
    }
  }

  void _handleSave() {
    context.read<SalonProfileBloc>().add(
      UpdateAmenities(_selectedAmenities),
    );

    Navigator.pop(context);

    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('Amenities updated!'),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }
}

