                  Positioned(
                    bottom: 8,
                    right: 8,
                    child: Container(
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                      decoration: BoxDecoration(
                        color: Colors.black.withOpacity(0.7),
                        borderRadius: BorderRadius.circular(4),
                      ),
                      child: Text(
                        '${_duration! ~/ 60}:${(_duration! % 60).toString().padLeft(2, '0')}',
                        style: const TextStyle(
                          color: Colors.white,
                          fontSize: 12,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                    ),
                  ),

                Positioned(
                  top: 8,
                  right: 8,
                  child: Material(
                    color: Colors.black.withOpacity(0.5),
                    borderRadius: BorderRadius.circular(20),
                    child: InkWell(
                      onTap: () {
                        setState(() {
                          _selectedVideo = null;
                          _thumbnail = null;
                          _duration = null;
                          _errorMessage = null;
                        });
                      },
                      borderRadius: BorderRadius.circular(20),
                      child: const Padding(
                        padding: EdgeInsets.all(8),
                        child: Icon(Icons.close_rounded, color: Colors.white, size: 20),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),

        const SizedBox(height: AppConstants.padM),
        Row(
          children: [
            const Icon(Icons.check_circle_rounded, color: Colors.green, size: 18),
            const SizedBox(width: AppConstants.padXS),
            Text(
              'Video ready to upload',
              style: theme.textTheme.bodyMedium?.copyWith(
                color: Colors.green,
                fontWeight: FontWeight.w500,
              ),
            ),
          ],
        ),
      ],
    );
  }

  Future<void> _pickVideo(ImageSource source) async {
    setState(() {
      _isProcessing = true;
      _errorMessage = null;
    });

    try {
      final picker = ImagePicker();
      final XFile? video = await picker.pickVideo(
        source: source,
        maxDuration: const Duration(seconds: kMaxVideoDuration),
      );

      if (video == null) {
        setState(() => _isProcessing = false);
        return;
      }

      final videoFile = File(video.path);
      final duration = await VideoCompressionHelper.getVideoDuration(videoFile);

      if (duration == null) {
        setState(() {
          _isProcessing = false;
          _errorMessage = 'Could not read video duration';
        });
        return;
      }

      if (duration > kMaxVideoDuration) {
        setState(() {
          _isProcessing = false;
          _errorMessage = 'Video must be $kMaxVideoDuration seconds or less. Your video is $duration seconds.';
        });
        return;
      }

      final thumbnail = await VideoCompressionHelper.generateThumbnail(videoFile);

      setState(() {
        _selectedVideo = videoFile;
        _thumbnail = thumbnail;
        _duration = duration;
        _isProcessing = false;
      });
    } catch (e) {
      setState(() {
        _isProcessing = false;
        _errorMessage = 'Error selecting video: ${e.toString()}';
      });
    }
  }

  void _handleUpload() {
    if (_selectedVideo == null) return;

    final caption = _captionController.text.trim();
    widget.onVideoSelected(
      _selectedVideo!.path,
      caption.isEmpty ? null : caption,
    );
  }
}

