import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:equatable/equatable.dart';

/// Enhanced Review Model with owner reply and verification support.
///
/// This model stores:
/// - User's rating and comment
/// - Owner's reply (if any)
/// - Verification status (did user actually book this salon?)
/// - Timestamps for tracking
class ReviewModel extends Equatable {
  /// Unique identifier for this review
  final String id;

  /// The ID of the salon being reviewed
  final String salonId;

  /// The ID of the user who wrote this review
  final String userId;

  /// The name of the user (for display purposes)
  final String userName;

  /// Optional profile picture URL of the reviewer
  final String? userProfilePicture;

  /// Rating from 1.0 to 5.0 (stored as double for flexibility)
  final double rating;

  /// The written review comment
  final String comment;

  /// When this review was created
  final DateTime createdAt;

  /// When this review was last updated (for edits)
  final DateTime? updatedAt;

  /// Is this review from a verified booking? (user completed appointment)
  final bool isVerifiedBooking;

  /// The appointment ID that this review is for (if verified)
  final String? appointmentId;

  /// --- OWNER REPLY FIELDS ---

  /// Owner's reply to this review (nullable - may not have replied yet)
  final String? ownerReply;

  /// When the owner replied
  final DateTime? ownerRepliedAt;

  /// The owner's user ID (for verification)
  final String? ownerUserId;

  /// --- HELPFUL VOTING (for future feature) ---

  /// Number of users who found this review helpful
  final int helpfulCount;

  const ReviewModel({
    required this.id,
    required this.salonId,
    required this.userId,
    required this.userName,
    this.userProfilePicture,
    required this.rating,
    required this.comment,
    required this.createdAt,
    this.updatedAt,
    this.isVerifiedBooking = false,
    this.appointmentId,
    this.ownerReply,
    this.ownerRepliedAt,
    this.ownerUserId,
    this.helpfulCount = 0,
  });

  @override
  List<Object?> get props => [
    id,
    salonId,
    userId,
    userName,
    userProfilePicture,
    rating,
    comment,
    createdAt,
    updatedAt,
    isVerifiedBooking,
    appointmentId,
    ownerReply,
    ownerRepliedAt,
    ownerUserId,
    helpfulCount,
  ];

  /// Check if owner has replied to this review
  bool get hasOwnerReply => ownerReply != null && ownerReply!.isNotEmpty;

  /// Get star count as integer (for UI display)
  int get starCount => rating.round();

  /// Check if review was edited
  bool get isEdited => updatedAt != null && updatedAt!.isAfter(createdAt);

  /// Creates a ReviewModel from a Firestore document
  factory ReviewModel.fromFirestore(
      DocumentSnapshot<Map<String, dynamic>> doc) {
    final data = doc.data()!;
    return ReviewModel(
      id: doc.id,
      salonId: data['salonId'] as String? ?? '',
      userId: data['userId'] as String? ?? '',
      userName: data['userName'] as String? ?? 'Anonymous',
      userProfilePicture: data['userProfilePicture'] as String?,
      rating: (data['rating'] as num?)?.toDouble() ?? 0.0,
      comment: data['comment'] as String? ?? '',
      createdAt:
      (data['createdAt'] as Timestamp? ?? Timestamp.now()).toDate(),
      updatedAt: data['updatedAt'] != null
          ? (data['updatedAt'] as Timestamp).toDate()
          : null,
      isVerifiedBooking: data['isVerifiedBooking'] as bool? ?? false,
      appointmentId: data['appointmentId'] as String?,
      ownerReply: data['ownerReply'] as String?,
      ownerRepliedAt: data['ownerRepliedAt'] != null
          ? (data['ownerRepliedAt'] as Timestamp).toDate()
          : null,
      ownerUserId: data['ownerUserId'] as String?,
      helpfulCount: data['helpfulCount'] as int? ?? 0,
    );
  }

  /// Converts this model to a Map for Firestore storage
  Map<String, dynamic> toFirestore() {
    return {
      'salonId': salonId,
      'userId': userId,
      'userName': userName,
      'userProfilePicture': userProfilePicture,
      'rating': rating,
      'comment': comment,
      'createdAt': Timestamp.fromDate(createdAt),
      'updatedAt': updatedAt != null ? Timestamp.fromDate(updatedAt!) : null,
      'isVerifiedBooking': isVerifiedBooking,
      'appointmentId': appointmentId,
      'ownerReply': ownerReply,
      'ownerRepliedAt': ownerRepliedAt != null
          ? Timestamp.fromDate(ownerRepliedAt!)
          : null,
      'ownerUserId': ownerUserId,
      'helpfulCount': helpfulCount,
    };
  }

  /// Creates a copy with updated fields
  ReviewModel copyWith({
    String? id,
    String? salonId,
    String? userId,
    String? userName,
    String? userProfilePicture,
    double? rating,
    String? comment,
    DateTime? createdAt,
    DateTime? updatedAt,
    bool? isVerifiedBooking,
    String? appointmentId,
    String? ownerReply,
    DateTime? ownerRepliedAt,
    String? ownerUserId,
    int? helpfulCount,
    bool clearOwnerReply = false,
  }) {
    return ReviewModel(
      id: id ?? this.id,
      salonId: salonId ?? this.salonId,
      userId: userId ?? this.userId,
      userName: userName ?? this.userName,
      userProfilePicture: userProfilePicture ?? this.userProfilePicture,
      rating: rating ?? this.rating,
      comment: comment ?? this.comment,
      createdAt: createdAt ?? this.createdAt,
      updatedAt: updatedAt ?? this.updatedAt,
      isVerifiedBooking: isVerifiedBooking ?? this.isVerifiedBooking,
      appointmentId: appointmentId ?? this.appointmentId,
      ownerReply:
      clearOwnerReply ? null : (ownerReply ?? this.ownerReply),
      ownerRepliedAt: clearOwnerReply
          ? null
          : (ownerRepliedAt ?? this.ownerRepliedAt),
      ownerUserId:
      clearOwnerReply ? null : (ownerUserId ?? this.ownerUserId),
      helpfulCount: helpfulCount ?? this.helpfulCount,
    );
  }

  /// Factory to create a new review from user input
  factory ReviewModel.create({
    required String salonId,
    required String userId,
    required String userName,
    String? userProfilePicture,
    required double rating,
    required String comment,
    bool isVerifiedBooking = false,
    String? appointmentId,
  }) {
    return ReviewModel(
      id: '', // Will be set by Firestore
      salonId: salonId,
      userId: userId,
      userName: userName,
      userProfilePicture: userProfilePicture,
      rating: rating,
      comment: comment,
      createdAt: DateTime.now(),
      isVerifiedBooking: isVerifiedBooking,
      appointmentId: appointmentId,
    );
  }
}

import '../models/review_model.dart';

/// Abstract repository interface for managing salon reviews.
///
/// This repository handles:
/// - Creating new reviews (with verification check)
/// - Updating existing reviews
/// - Deleting reviews
/// - Fetching reviews for a salon
/// - Owner replies to reviews
/// - Rating aggregation
abstract class ReviewsRepository {
  /// Create a new review for a salon
  ///
  /// Checks if user has completed booking before allowing review
  /// Returns the created review with ID
  Future<ReviewModel> createReview({
    required String salonId,
    required String userId,
    required String userName,
    String? userProfilePicture,
    required double rating,
    required String comment,
  });

  /// Update an existing review
  ///
  /// Only the review author can update their review
  Future<void> updateReview({
    required String reviewId,
    required String userId,
    required double rating,
    required String comment,
  });

  /// Delete a review
  ///
  /// Only the review author can delete their review
  Future<void> deleteReview({
    required String reviewId,
    required String userId,
  });

  /// Get all reviews for a specific salon
  ///
  /// [sortBy]: 'recent', 'highest', 'lowest'
  Future<List<ReviewModel>> getReviewsForSalon({
    required String salonId,
    String sortBy = 'recent',
    int? limit,
  });

  /// Get a specific user's review for a salon
  ///
  /// Returns null if user hasn't reviewed this salon yet
  Future<ReviewModel?> getUserReviewForSalon({
    required String salonId,
    required String userId,
  });

  /// Check if user has already reviewed a salon
  Future<bool> hasUserReviewedSalon({
    required String salonId,
    required String userId,
  });

  /// Check if user is eligible to review (has completed booking)
  Future<bool> canUserReviewSalon({
    required String salonId,
    required String userId,
  });

  /// Get the completed appointment ID for verification
  ///
  /// Returns null if no completed appointments found
  Future<String?> getCompletedAppointmentId({
    required String salonId,
    required String userId,
  });

  /// --- OWNER REPLY METHODS ---

  /// Add or update owner's reply to a review
  ///
  /// Only salon owner can reply
  Future<void> addOwnerReply({
    required String reviewId,
    required String salonId,
    required String ownerId,
    required String replyText,
  });

  /// Delete owner's reply
  Future<void> deleteOwnerReply({
    required String reviewId,
    required String ownerId,
  });

  /// --- RATING AGGREGATION ---

  /// Calculate and get average rating for a salon
  Future<double> getAverageRating({required String salonId});

  /// Get total review count for a salon
  Future<int> getReviewCount({required String salonId});

  /// Get rating distribution (how many 5-star, 4-star, etc.)
  Future<Map<int, int>> getRatingDistribution({required String salonId});

  /// --- HELPFUL VOTING (for future) ---

  /// Mark a review as helpful
  Future<void> markReviewHelpful({
    required String reviewId,
    required String userId,
  });

  /// --- REAL-TIME UPDATES ---

  /// Stream reviews for real-time updates
  Stream<List<ReviewModel>> watchReviewsForSalon({
    required String salonId,
    String sortBy = 'recent',
  });
}

import 'package:pendeza/app/services/firestore_service.dart';
import 'package:pendeza/app/utils/logger.dart';
import '../../data/models/review_model.dart';
import '../../data/repositories/reviews_repository_impl.dart';


/// Implementation of ReviewsRepository with Firestore backend.
///
/// Key features:
/// - ✅ ANY authenticated user can review (NO booking verification)
/// - One review per user per salon (can edit anytime)
/// - Owner replies supported
/// - Real-time rating aggregation
class ReviewsRepositoryImpl implements ReviewsRepository {
  final FirestoreService _firestoreService;

  ReviewsRepositoryImpl({
    required FirestoreService firestoreService,
  }) : _firestoreService = firestoreService;

  @override
  Future<ReviewModel> createReview({
    required String salonId,
    required String userId,
    required String userName,
    String? userProfilePicture,
    required double rating,
    required String comment,
  }) async {
    try {
      // 1. Check if user has already reviewed this salon
      final existingReview = await getUserReviewForSalon(
        salonId: salonId,
        userId: userId,
      );

      if (existingReview != null) {
        throw Exception('You have already reviewed this salon. You can edit your existing review.');
      }

      // ✅ REMOVED: Booking verification check
      // Any authenticated user can now review

      // 2. Create the review
      final review = ReviewModel.create(
        salonId: salonId,
        userId: userId,
        userName: userName,
        userProfilePicture: userProfilePicture,
        rating: rating,
        comment: comment,
        isVerifiedBooking: false, // Changed to false - no verification needed
        appointmentId: null, // No appointment required
      );

      // 3. Save to Firestore
      final createdReview = await _firestoreService.createReview(review);

      log.i('Review created successfully for salon $salonId by user $userId');
      return createdReview;
    } catch (e, s) {
      log.e('Error creating review', error: e, stackTrace: s);
      rethrow;
    }
  }

  @override
  Future<void> updateReview({
    required String reviewId,
    required String userId,
    required double rating,
    required String comment,
  }) async {
    try {
      await _firestoreService.updateReview(
        reviewId: reviewId,
        userId: userId,
        rating: rating,
        comment: comment,
      );

      log.i('Review $reviewId updated successfully');
    } catch (e, s) {
      log.e('Error updating review', error: e, stackTrace: s);
      rethrow;
    }
  }

  @override
  Future<void> deleteReview({
    required String reviewId,
    required String userId,
  }) async {
    try {
      await _firestoreService.deleteReview(
        reviewId: reviewId,
        userId: userId,
      );

      log.i('Review $reviewId deleted successfully');
    } catch (e, s) {
      log.e('Error deleting review', error: e, stackTrace: s);
      rethrow;
    }
  }

  @override
  Future<List<ReviewModel>> getReviewsForSalon({
    required String salonId,
    String sortBy = 'recent',
    int? limit,
  }) async {
    try {
      final reviews = await _firestoreService.getReviewsForSalon(
        salonId: salonId,
        sortBy: sortBy,
        limit: limit,
      );

      log.d('Retrieved ${reviews.length} reviews for salon $salonId');
      return reviews;
    } catch (e, s) {
      log.e('Error getting reviews for salon', error: e, stackTrace: s);
      return [];
    }
  }

  @override
  Future<ReviewModel?> getUserReviewForSalon({
    required String salonId,
    required String userId,
  }) async {
    try {
      return await _firestoreService.getUserReviewForSalon(
        salonId: salonId,
        userId: userId,
      );
    } catch (e, s) {
      log.e('Error getting user review', error: e, stackTrace: s);
      return null;
    }
  }

  @override
  Future<bool> hasUserReviewedSalon({
    required String salonId,
    required String userId,
  }) async {
    try {
      final review = await getUserReviewForSalon(
        salonId: salonId,
        userId: userId,
      );
      return review != null;
    } catch (e, s) {
      log.e('Error checking if user reviewed salon', error: e, stackTrace: s);
      return false;
    }
  }

  @override
  Future<bool> canUserReviewSalon({
    required String salonId,
    required String userId,
  }) async {
    // ✅ SIMPLIFIED: All authenticated users can review
    // No booking check needed
    return true;
  }

  @override
  Future<String?> getCompletedAppointmentId({
    required String salonId,
    required String userId,
  }) async {
    try {
      return await _firestoreService.getCompletedAppointmentIdForReview(
        salonId: salonId,
        userId: userId,
      );
    } catch (e, s) {
      log.e('Error getting completed appointment', error: e, stackTrace: s);
      return null;
    }
  }

  //============================================================================
  // OWNER REPLY METHODS
  //============================================================================

  @override
  Future<void> addOwnerReply({
    required String reviewId,
    required String salonId,
    required String ownerId,
    required String replyText,
  }) async {
    try {
      // Verify that this user is actually the salon owner
      final salon = await _firestoreService.getSalonById(salonId);
      if (salon == null || salon.ownerId != ownerId) {
        throw Exception('Only the salon owner can reply to reviews');
      }

      await _firestoreService.addOwnerReplyToReview(
        reviewId: reviewId,
        ownerId: ownerId,
        replyText: replyText,
      );

      log.i('Owner reply added to review $reviewId');
    } catch (e, s) {
      log.e('Error adding owner reply', error: e, stackTrace: s);
      rethrow;
    }
  }

  @override
  Future<void> deleteOwnerReply({
    required String reviewId,
    required String ownerId,
  }) async {
    try {
      await _firestoreService.deleteOwnerReply(
        reviewId: reviewId,
        ownerId: ownerId,
      );

      log.i('Owner reply deleted from review $reviewId');
    } catch (e, s) {
      log.e('Error deleting owner reply', error: e, stackTrace: s);
      rethrow;
    }
  }

  //============================================================================
  // RATING AGGREGATION
  //============================================================================

  @override
  Future<double> getAverageRating({required String salonId}) async {
    try {
      final reviews = await getReviewsForSalon(salonId: salonId);

      if (reviews.isEmpty) return 0.0;

      final totalRating = reviews.fold<double>(
        0.0,
            (sum, review) => sum + review.rating,
      );

      final average = totalRating / reviews.length;
      return double.parse(average.toStringAsFixed(1)); // Round to 1 decimal
    } catch (e, s) {
      log.e('Error calculating average rating', error: e, stackTrace: s);
      return 0.0;
    }
  }

  @override
  Future<int> getReviewCount({required String salonId}) async {
    try {
      final reviews = await getReviewsForSalon(salonId: salonId);
      return reviews.length;
    } catch (e, s) {
      log.e('Error getting review count', error: e, stackTrace: s);
      return 0;
    }
  }

  @override
  Future<Map<int, int>> getRatingDistribution({required String salonId}) async {
    try {
      final reviews = await getReviewsForSalon(salonId: salonId);

      final distribution = <int, int>{
        5: 0,
        4: 0,
        3: 0,
        2: 0,
        1: 0,
      };

      for (final review in reviews) {
        final stars = review.starCount;
        distribution[stars] = (distribution[stars] ?? 0) + 1;
      }

      return distribution;
    } catch (e, s) {
      log.e('Error getting rating distribution', error: e, stackTrace: s);
      return {5: 0, 4: 0, 3: 0, 2: 0, 1: 0};
    }
  }

  //============================================================================
  // HELPFUL VOTING (Future feature)
  //============================================================================

  @override
  Future<void> markReviewHelpful({
    required String reviewId,
    required String userId,
  }) async {
    try {
      await _firestoreService.incrementReviewHelpfulCount(reviewId: reviewId);
      log.i('Review $reviewId marked as helpful by user $userId');
    } catch (e, s) {
      log.e('Error marking review as helpful', error: e, stackTrace: s);
      rethrow;
    }
  }

  //============================================================================
  // REAL-TIME UPDATES
  //============================================================================

  @override
  Stream<List<ReviewModel>> watchReviewsForSalon({
    required String salonId,
    String sortBy = 'recent',
  }) {
    try {
      return _firestoreService.watchReviewsForSalon(
        salonId: salonId,
        sortBy: sortBy,
      );
    } catch (e, s) {
      log.e('Error watching reviews', error: e, stackTrace: s);
      return Stream.value([]);
    }
  }
}

import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:pendeza/app/utils/logger.dart';
import '../../data/repositories/reviews_repository_impl.dart';
import 'reviews_event.dart';
import 'reviews_state.dart';

/// BLoC for managing reviews feature.
///
/// This BLoC handles:
/// - Loading and displaying reviews
/// - ✅ Creating, updating, deleting reviews (NO booking verification)
/// - Owner replies to reviews
/// - Rating aggregation
/// - Sorting and filtering
class ReviewsBloc extends Bloc<ReviewsEvent, ReviewsState> {
  final ReviewsRepository _reviewsRepository;

  ReviewsBloc({
    required ReviewsRepository reviewsRepository,
  })  : _reviewsRepository = reviewsRepository,
        super(const ReviewsInitial()) {
    // Register event handlers
    on<LoadReviews>(_onLoadReviews);
    on<RefreshReviews>(_onRefreshReviews);
    on<SortReviews>(_onSortReviews);
    on<CheckReviewEligibility>(_onCheckReviewEligibility);
    on<LoadUserReview>(_onLoadUserReview);
    on<SubmitReview>(_onSubmitReview);
    on<UpdateReview>(_onUpdateReview);
    on<DeleteReview>(_onDeleteReview);
    on<AddOwnerReply>(_onAddOwnerReply);
    on<DeleteOwnerReply>(_onDeleteOwnerReply);
    on<MarkReviewHelpful>(_onMarkReviewHelpful);
  }

  //============================================================================
  // LOAD REVIEWS
  //============================================================================

  Future<void> _onLoadReviews(
      LoadReviews event,
      Emitter<ReviewsState> emit,
      ) async {
    try {
      emit(const ReviewsLoading());

      log.i('Loading reviews for salon: ${event.salonId}');

      // Load reviews
      final reviews = await _reviewsRepository.getReviewsForSalon(
        salonId: event.salonId,
        sortBy: event.sortBy,
      );

      // If no reviews, emit empty state
      if (reviews.isEmpty) {
        emit(ReviewsEmpty(salonId: event.salonId));
        return;
      }

      // Calculate aggregated data
      final averageRating = await _reviewsRepository.getAverageRating(
        salonId: event.salonId,
      );

      final ratingDistribution =
      await _reviewsRepository.getRatingDistribution(
        salonId: event.salonId,
      );

      emit(ReviewsLoaded(
        reviews: reviews,
        salonId: event.salonId,
        averageRating: averageRating,
        totalReviews: reviews.length,
        ratingDistribution: ratingDistribution,
        sortBy: event.sortBy,
      ));

      log.i('Loaded ${reviews.length} reviews with avg rating $averageRating');
    } catch (e, s) {
      log.e('Error loading reviews', error: e, stackTrace: s);
      emit(ReviewsError(
        message: 'Failed to load reviews. Please try again.',
        errorCode: e.toString(),
      ));
    }
  }

  //============================================================================
  // REFRESH REVIEWS
  //============================================================================

  Future<void> _onRefreshReviews(
      RefreshReviews event,
      Emitter<ReviewsState> emit,
      ) async {
    final currentState = state;

    try {
      // Keep current sort if available
      String sortBy = 'recent';
      if (currentState is ReviewsLoaded) {
        sortBy = currentState.sortBy;
      }

      // Reload without showing loading state (smoother UX)
      final reviews = await _reviewsRepository.getReviewsForSalon(
        salonId: event.salonId,
        sortBy: sortBy,
      );

      if (reviews.isEmpty) {
        emit(ReviewsEmpty(salonId: event.salonId));
        return;
      }

      final averageRating = await _reviewsRepository.getAverageRating(
        salonId: event.salonId,
      );

      final ratingDistribution =
      await _reviewsRepository.getRatingDistribution(
        salonId: event.salonId,
      );

      emit(ReviewsLoaded(
        reviews: reviews,
        salonId: event.salonId,
        averageRating: averageRating,
        totalReviews: reviews.length,
        ratingDistribution: ratingDistribution,
        sortBy: sortBy,
      ));

      log.i('Refreshed ${reviews.length} reviews');
    } catch (e, s) {
      log.e('Error refreshing reviews', error: e, stackTrace: s);
      emit(ReviewsError(message: 'Failed to refresh reviews'));
    }
  }

  //============================================================================
  // SORT REVIEWS
  //============================================================================

  Future<void> _onSortReviews(
      SortReviews event,
      Emitter<ReviewsState> emit,
      ) async {
    final currentState = state;
    if (currentState is! ReviewsLoaded) return;

    try {
      final reviews = await _reviewsRepository.getReviewsForSalon(
        salonId: currentState.salonId,
        sortBy: event.sortBy,
      );

      emit(currentState.copyWith(
        reviews: reviews,
        sortBy: event.sortBy,
      ));

      log.i('Sorted reviews by: ${event.sortBy}');
    } catch (e, s) {
      log.e('Error sorting reviews', error: e, stackTrace: s);
    }
  }

  //============================================================================
  // CHECK REVIEW ELIGIBILITY - ✅ SIMPLIFIED (NO BOOKING CHECK)
  //============================================================================

  Future<void> _onCheckReviewEligibility(
      CheckReviewEligibility event,
      Emitter<ReviewsState> emit,
      ) async {
    try {
      emit(CheckingEligibility(salonId: event.salonId));

      log.i('Checking review eligibility for user ${event.userId}');

      // ✅ SIMPLIFIED: Just check if user already has a review
      // All authenticated users are eligible to review
      final existingReview = await _reviewsRepository.getUserReviewForSalon(
        salonId: event.salonId,
        userId: event.userId,
      );

      // All authenticated users are eligible
      emit(EligibleToReview(
        salonId: event.salonId,
        hasExistingReview: existingReview != null,
        existingReview: existingReview,
      ));

      log.i('User eligible - ${existingReview != null ? "has existing review" : "can write new review"}');
    } catch (e, s) {
      log.e('Error checking eligibility', error: e, stackTrace: s);
      emit(ReviewsError(
        message: 'Failed to check review eligibility',
        errorCode: e.toString(),
      ));
    }
  }

  //============================================================================
  // LOAD USER REVIEW
  //============================================================================

  Future<void> _onLoadUserReview(
      LoadUserReview event,
      Emitter<ReviewsState> emit,
      ) async {
    try {
      final review = await _reviewsRepository.getUserReviewForSalon(
        salonId: event.salonId,
        userId: event.userId,
      );

      if (review != null) {
        emit(EligibleToReview(
          salonId: event.salonId,
          hasExistingReview: true,
          existingReview: review,
        ));
      } else {
        emit(EligibleToReview(
          salonId: event.salonId,
          hasExistingReview: false,
        ));
      }
    } catch (e, s) {
      log.e('Error loading user review', error: e, stackTrace: s);
    }
  }

  //============================================================================
  // SUBMIT REVIEW - ✅ REMOVED BOOKING ERROR MESSAGE
  //============================================================================

  Future<void> _onSubmitReview(
      SubmitReview event,
      Emitter<ReviewsState> emit,
      ) async {
    try {
      emit(const SubmittingReview());

      log.i('Submitting review for salon ${event.salonId}');

      final review = await _reviewsRepository.createReview(
        salonId: event.salonId,
        userId: event.userId,
        userName: event.userName,
        userProfilePicture: event.userProfilePicture,
        rating: event.rating,
        comment: event.comment,
      );

      emit(ReviewSubmitted(review: review));

      log.i('Review submitted successfully');

      // Auto-refresh reviews list
      add(LoadReviews(salonId: event.salonId));
    } catch (e, s) {
      log.e('Error submitting review', error: e, stackTrace: s);

      String errorMessage = 'Failed to submit review';
      if (e.toString().contains('already reviewed')) {
        errorMessage = 'You have already reviewed this salon. You can edit your existing review.';
      }
      // ✅ REMOVED: booking completion error message

      emit(ReviewsError(
        message: errorMessage,
        errorCode: e.toString(),
      ));
    }
  }

  //============================================================================
  // UPDATE REVIEW
  //============================================================================

  Future<void> _onUpdateReview(
      UpdateReview event,
      Emitter<ReviewsState> emit,
      ) async {
    try {
      emit(UpdatingReview(reviewId: event.reviewId));

      log.i('Updating review ${event.reviewId}');

      await _reviewsRepository.updateReview(
        reviewId: event.reviewId,
        userId: event.userId,
        rating: event.rating,
        comment: event.comment,
      );

      emit(ReviewUpdated(reviewId: event.reviewId));

      log.i('Review updated successfully');

      // Auto-refresh reviews list if we have salon context
      final currentState = state;
      if (currentState is ReviewsLoaded) {
        add(LoadReviews(salonId: currentState.salonId));
      }
    } catch (e, s) {
      log.e('Error updating review', error: e, stackTrace: s);
      emit(ReviewsError(
        message: 'Failed to update review. Please try again.',
        errorCode: e.toString(),
      ));
    }
  }

  //============================================================================
  // DELETE REVIEW
  //============================================================================

  Future<void> _onDeleteReview(
      DeleteReview event,
      Emitter<ReviewsState> emit,
      ) async {
    try {
      emit(DeletingReview(reviewId: event.reviewId));

      log.i('Deleting review ${event.reviewId}');

      await _reviewsRepository.deleteReview(
        reviewId: event.reviewId,
        userId: event.userId,
      );

      emit(ReviewDeleted(reviewId: event.reviewId));

      log.i('Review deleted successfully');

      // Auto-refresh reviews list if we have salon context
      final currentState = state;
      if (currentState is ReviewsLoaded) {
        add(LoadReviews(salonId: currentState.salonId));
      }
    } catch (e, s) {
      log.e('Error deleting review', error: e, stackTrace: s);
      emit(ReviewsError(
        message: 'Failed to delete review. Please try again.',
        errorCode: e.toString(),
      ));
    }
  }

  //============================================================================
  // OWNER REPLY
  //============================================================================

  Future<void> _onAddOwnerReply(
      AddOwnerReply event,
      Emitter<ReviewsState> emit,
      ) async {
    try {
      emit(AddingOwnerReply(reviewId: event.reviewId));

      log.i('Adding owner reply to review ${event.reviewId}');

      await _reviewsRepository.addOwnerReply(
        reviewId: event.reviewId,
        salonId: event.salonId,
        ownerId: event.ownerId,
        replyText: event.replyText,
      );

      emit(OwnerReplyAdded(reviewId: event.reviewId));

      log.i('Owner reply added successfully');

      // Auto-refresh to show the reply
      add(LoadReviews(salonId: event.salonId));
    } catch (e, s) {
      log.e('Error adding owner reply', error: e, stackTrace: s);

      String errorMessage = 'Failed to add reply';
      if (e.toString().contains('salon owner')) {
        errorMessage = 'Only the salon owner can reply to reviews';
      }

      emit(ReviewsError(
        message: errorMessage,
        errorCode: e.toString(),
      ));
    }
  }

  Future<void> _onDeleteOwnerReply(
      DeleteOwnerReply event,
      Emitter<ReviewsState> emit,
      ) async {
    try {
      emit(DeletingOwnerReply(reviewId: event.reviewId));

      log.i('Deleting owner reply from review ${event.reviewId}');

      await _reviewsRepository.deleteOwnerReply(
        reviewId: event.reviewId,
        ownerId: event.ownerId,
      );

      emit(OwnerReplyDeleted(reviewId: event.reviewId));

      log.i('Owner reply deleted successfully');

      // Auto-refresh
      final currentState = state;
      if (currentState is ReviewsLoaded) {
        add(LoadReviews(salonId: currentState.salonId));
      }
    } catch (e, s) {
      log.e('Error deleting owner reply', error: e, stackTrace: s);
      emit(ReviewsError(
        message: 'Failed to delete reply. Please try again.',
        errorCode: e.toString(),
      ));
    }
  }

  //============================================================================
  // HELPFUL VOTING (Future feature)
  //============================================================================

  Future<void> _onMarkReviewHelpful(
      MarkReviewHelpful event,
      Emitter<ReviewsState> emit,
      ) async {
    try {
      await _reviewsRepository.markReviewHelpful(
        reviewId: event.reviewId,
        userId: event.userId,
      );

      log.i('Review ${event.reviewId} marked as helpful');

      // Optionally refresh to show updated count
      final currentState = state;
      if (currentState is ReviewsLoaded) {
        add(LoadReviews(salonId: currentState.salonId));
      }
    } catch (e, s) {
      log.e('Error marking review as helpful', error: e, stackTrace: s);
    }
  }
}

import 'package:equatable/equatable.dart';

/// Base class for all review events
