/// --- HELPFUL VOTING (Future feature) ---

/// Mark a review as helpful
class MarkReviewHelpful extends ReviewsEvent {
  final String reviewId;
  final String userId;

  const MarkReviewHelpful({
    required this.reviewId,
    required this.userId,
  });

  @override
  List<Object?> get props => [reviewId, userId];
}

import 'package:equatable/equatable.dart';
import '../../data/models/review_model.dart';




/// Base class for all review states
abstract class ReviewsState extends Equatable {
  const ReviewsState();

  @override
  List<Object?> get props => [];
}

/// Initial state before any reviews are loaded
class ReviewsInitial extends ReviewsState {
  const ReviewsInitial();
}

/// Loading reviews
class ReviewsLoading extends ReviewsState {
  const ReviewsLoading();
}

/// Successfully loaded reviews
class ReviewsLoaded extends ReviewsState {
  final List<ReviewModel> reviews;
  final String salonId;
  final double averageRating;
  final int totalReviews;
  final Map<int, int> ratingDistribution;
  final String sortBy;

  const ReviewsLoaded({
    required this.reviews,
    required this.salonId,
    required this.averageRating,
    required this.totalReviews,
    required this.ratingDistribution,
    this.sortBy = 'recent',
  });

  /// Check if there are any reviews
  bool get hasReviews => reviews.isNotEmpty;

  /// Get reviews with owner replies only
  List<ReviewModel> get reviewsWithReplies =>
      reviews.where((r) => r.hasOwnerReply).toList();

  /// Get verified booking reviews only
  List<ReviewModel> get verifiedReviews =>
      reviews.where((r) => r.isVerifiedBooking).toList();

  @override
  List<Object?> get props => [
    reviews,
    salonId,
    averageRating,
    totalReviews,
    ratingDistribution,
    sortBy,
  ];

  /// Copy with updated fields
  ReviewsLoaded copyWith({
    List<ReviewModel>? reviews,
    String? salonId,
    double? averageRating,
    int? totalReviews,
    Map<int, int>? ratingDistribution,
    String? sortBy,
  }) {
    return ReviewsLoaded(
      reviews: reviews ?? this.reviews,
      salonId: salonId ?? this.salonId,
      averageRating: averageRating ?? this.averageRating,
      totalReviews: totalReviews ?? this.totalReviews,
      ratingDistribution: ratingDistribution ?? this.ratingDistribution,
      sortBy: sortBy ?? this.sortBy,
    );
  }
}

