/// An interactive rating input widget with a label.
class RatingInput extends StatelessWidget {
  final double initialRating;
  final ValueChanged<double> onRatingChanged;
  final String label;

  const RatingInput({
    super.key,
    required this.initialRating,
    required this.onRatingChanged,
    this.label = 'Rate your experience',
  });

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return Column(
      children: [
        Text(
          label,
          style: theme.textTheme.titleMedium,
        ),
        const SizedBox(height: AppConstants.padS),
        RatingStars.input(
          initialRating: initialRating,
          onRatingChanged: onRatingChanged,
          size: 40,
        ),
        const SizedBox(height: 8),
        Text(
          _getRatingLabel(initialRating),
          style: theme.textTheme.bodyMedium?.copyWith(
            color: theme.colorScheme.primary,
            fontWeight: FontWeight.bold,
          ),
        ),
      ],
    );
  }

  String _getRatingLabel(double rating) {
    if (rating == 0) return 'Tap stars to rate';
    if (rating <= 1) return 'Poor';
    if (rating <= 2) return 'Fair';
    if (rating <= 3) return 'Good';
    if (rating <= 4) return 'Very Good';
    return 'Excellent!';
  }
}

/// A bar chart showing the distribution of ratings (5 star, 4 star, etc.)
class RatingDistributionChart extends StatelessWidget {
  final Map<int, int> distribution; // {5: 10, 4: 5, ...}
  final int totalReviews;

  const RatingDistributionChart({
    super.key,
    required this.distribution,
    required this.totalReviews,
  });

  @override
  Widget build(BuildContext context) {
    if (totalReviews == 0) return const SizedBox.shrink();

    return Column(
      children: [5, 4, 3, 2, 1].map((star) {
        final count = distribution[star] ?? 0;
        final percentage = totalReviews > 0 ? count / totalReviews : 0.0;

        return Padding(
          padding: const EdgeInsets.symmetric(vertical: 2),
          child: Row(
            children: [
              // Star label (e.g. "5")
              SizedBox(
                width: 12,
                child: Text(
                  '$star',
                  style: Theme.of(context).textTheme.labelSmall?.copyWith(
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ),
              const SizedBox(width: 4),
              const Icon(Icons.star_rounded, size: 12, color: Colors.grey),
              const SizedBox(width: 8),

              // Progress Bar
              Expanded(
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(4),
                  child: LinearProgressIndicator(
                    value: percentage,
                    minHeight: 6,
                    backgroundColor: Colors.grey[200],
                    valueColor: const AlwaysStoppedAnimation<Color>(Color(0xFFFFB400)),
                  ),
                ),
              ),

              // Count label (e.g. "10")
              SizedBox(
                width: 30,
                child: Text(
                  '$count',
                  textAlign: TextAlign.end,
                  style: Theme.of(context).textTheme.labelSmall?.copyWith(
                    color: Colors.grey,
                  ),
                ),
              ),
            ],
          ),
        );
      }).toList(),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:go_router/go_router.dart';
import 'package:pendeza/app/config/app_router.dart';
import 'package:pendeza/app/config/theme/app_constants.dart';
import 'package:pendeza/features/0_auth/presentation/bloc/auth_bloc.dart';
import 'package:pendeza/features/0_auth/presentation/bloc/auth_state.dart';
import 'package:pendeza/features/3_reviews/presentation/bloc/reviews_bloc.dart';
import 'package:pendeza/features/3_reviews/presentation/bloc/reviews_event.dart';
import 'package:pendeza/features/3_reviews/presentation/bloc/reviews_state.dart';
import 'package:pendeza/features/3_reviews/presentation/widgets/rating_stars_widget.dart';
import 'package:pendeza/features/3_reviews/presentation/widgets/review_card.dart';
import 'package:pendeza/shared/models/salon_model.dart';
import '../../../../shared/widgets/custom_snackbar.dart'; // Import

class ReviewsSection extends StatelessWidget {
  final SalonModel salon;

  const ReviewsSection({super.key, required this.salon});

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return BlocBuilder<ReviewsBloc, ReviewsState>(
      builder: (context, state) {
        if (state is ReviewsLoading) {
          return const Padding(
            padding: EdgeInsets.symmetric(vertical: AppConstants.padL),
            child: Center(child: CircularProgressIndicator()),
          );
        }

        if (state is ReviewsEmpty) {
          return _buildEmptyState(context, theme);
        }

        if (state is ReviewsLoaded) {
          return _buildLoadedState(context, theme, state);
        }

        return const SizedBox.shrink();
      },
    );
  }

  Widget _buildEmptyState(BuildContext context, ThemeData theme) {
    return Container(
      padding: const EdgeInsets.symmetric(
        horizontal: AppConstants.padL,
        vertical: AppConstants.padXL,
      ),
      child: Column(
        children: [
          Icon(
            Icons.star_border_rounded,
            size: 48,
            color: theme.colorScheme.outline.withOpacity(0.5),
          ),
          const SizedBox(height: AppConstants.padM),
          Text(
            'No reviews yet',
            style: theme.textTheme.titleMedium?.copyWith(
              fontWeight: FontWeight.bold,
            ),
          ),
          Text(
            'Be the first to share your experience!',
            style: theme.textTheme.bodyMedium?.copyWith(
              color: theme.colorScheme.onSurfaceVariant,
            ),
          ),
          const SizedBox(height: AppConstants.padL),
          OutlinedButton(
            onPressed: () => _handleWriteReview(context),
            style: OutlinedButton.styleFrom(
              shape: RoundedRectangleBorder(
                borderRadius: AppConstants.radiusM,
              ),
            ),
            child: const Text('Write a Review'),
          ),
        ],
      ),
    );
  }

  Widget _buildLoadedState(
      BuildContext context,
      ThemeData theme,
      ReviewsLoaded state,
      ) {
    final previewReviews = state.reviews.take(3).toList();

    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: AppConstants.padL),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                'Reviews',
                style: theme.textTheme.headlineSmall?.copyWith(
                  fontWeight: FontWeight.bold,
                ),
              ),
              TextButton(
                onPressed: () => _handleWriteReview(context),
                child: const Text('Write a Review'),
              ),
            ],
          ),
          const SizedBox(height: AppConstants.padM),

          // Summary Card
          _buildSummaryCard(context, theme, state),
          const SizedBox(height: AppConstants.padXL),

          // Reviews List
          ...previewReviews.map((review) {
            final authState = context.read<AuthBloc>().state;
            String? currentUserId;
            bool isOwner = false;

            if (authState is Authenticated) {
              currentUserId = authState.user.uid;
              isOwner = authState.user.uid == salon.ownerId;
            }

            return Padding(
              padding: const EdgeInsets.only(bottom: AppConstants.padL),
              child: ReviewCard(
                review: review,
                currentUserId: currentUserId,
                isOwner: isOwner,
                onEdit: () => context.push(
                  AppRoutes.writeReview.replaceFirst(':salonId', salon.id),
                  extra: {'salon': salon, 'review': review},
                ),
                onDelete: () {
                  context.read<ReviewsBloc>().add(
                    DeleteReview(reviewId: review.id, userId: review.userId),
                  );
                },
                onReply: () {
                  // Custom Snackbar for not implemented features too!
                  CustomSnackBar.show(
                      context,
                      message: 'Reply feature coming soon',
                      type: SnackBarType.info
                  );
                },
              ),
            );
          }),

          if (state.totalReviews > 3)
            SizedBox(
              width: double.infinity,
              child: OutlinedButton(
                onPressed: () {
                  // View all
                },
                style: OutlinedButton.styleFrom(
                  padding: const EdgeInsets.symmetric(vertical: 14),
                  side: BorderSide(color: theme.colorScheme.outline),
                  shape: RoundedRectangleBorder(
                    borderRadius: AppConstants.radiusM,
                  ),
                ),
                child: Text('See all ${state.totalReviews} reviews'),
              ),
            ),
        ],
      ),
    );
  }

  Widget _buildSummaryCard(
      BuildContext context, ThemeData theme, ReviewsLoaded state) {
    return Container(
      padding: const EdgeInsets.all(AppConstants.padM),
      decoration: BoxDecoration(
        color: theme.colorScheme.surfaceContainerHighest.withOpacity(0.3),
        borderRadius: AppConstants.radiusL,
        border: Border.all(
          color: theme.colorScheme.outline.withOpacity(0.1),
        ),
      ),
      child: Row(
        children: [
          Column(
            children: [
              Text(
                state.averageRating.toStringAsFixed(1),
                style: theme.textTheme.displayMedium?.copyWith(
                  fontWeight: FontWeight.bold,
                  color: theme.colorScheme.onSurface,
                  height: 1.0,
                ),
              ),
              const SizedBox(height: 4),
              RatingStars.display(
                rating: state.averageRating,
                size: 16,
                color: Colors.amber,
              ),
              const SizedBox(height: 4),
              Text(
                '${state.totalReviews} ratings',
                style: theme.textTheme.bodySmall?.copyWith(
                  color: theme.colorScheme.onSurfaceVariant,
                ),
              ),
            ],
          ),
          const SizedBox(width: AppConstants.padL),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [5, 4, 3, 2, 1].map((star) {
                final count = state.ratingDistribution[star] ?? 0;
                final percentage =
                state.totalReviews == 0 ? 0.0 : count / state.totalReviews;

                return Padding(
                  padding: const EdgeInsets.symmetric(vertical: 2),
                  child: Row(
                    children: [
                      Text(
                        '$star',
                        style: theme.textTheme.bodySmall?.copyWith(
                          fontWeight: FontWeight.bold,
                          fontSize: 10,
                        ),
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: ClipRRect(
                          borderRadius: BorderRadius.circular(4),
                          child: LinearProgressIndicator(
                            value: percentage,
                            minHeight: 6,
                            backgroundColor: theme.colorScheme.surface,
                            valueColor: const AlwaysStoppedAnimation<Color>(
                              Colors.amber,
                            ),
                          ),
                        ),
                      ),
                    ],
                  ),
                );
              }).toList(),
            ),
          ),
        ],
      ),
    );
  }

  void _handleWriteReview(BuildContext context) {
    final authState = context.read<AuthBloc>().state;

    if (authState is! Authenticated) {
      // INFO SNACKBAR
      CustomSnackBar.show(
        context,
        message: 'Please sign in to write a review',
        type: SnackBarType.info,
      );
      return;
    }

    context.push(
      AppRoutes.writeReview.replaceFirst(':salonId', salon.id),
      extra: salon,
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/cupertino.dart';
import 'package:timeago/timeago.dart' as timeago;
import 'package:cached_network_image/cached_network_image.dart';
import 'package:pendeza/app/config/theme/app_constants.dart';
import '../../data/models/review_model.dart';

import '../widgets/rating_stars_widget.dart';

/// A card widget that displays a single review with:
/// - User info (name, photo, verified badge)
/// - Rating stars
/// - Review text
/// - Timestamp
/// - Owner reply (if any)
/// - Edit/Delete options (if user owns the review)
class ReviewCard extends StatelessWidget {
  final ReviewModel review;
  final String? currentUserId;
  final bool isOwner;
  final VoidCallback? onEdit;
  final VoidCallback? onDelete;
  final VoidCallback? onReply;
  final VoidCallback? onDeleteReply;

  const ReviewCard({
    super.key,
    required this.review,
    this.currentUserId,
    this.isOwner = false,
    this.onEdit,
    this.onDelete,
    this.onReply,
    this.onDeleteReply,
  });

  /// Check if current user is the review author
  bool get isReviewAuthor => currentUserId == review.userId;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return Container(
      margin: const EdgeInsets.only(bottom: AppConstants.padM),
      padding: const EdgeInsets.all(AppConstants.padM),
      decoration: BoxDecoration(
        color: theme.colorScheme.surface,
        borderRadius: AppConstants.radiusL,
        border: Border.all(
          color: theme.colorScheme.outline.withOpacity(0.1),
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(0.02),
            blurRadius: 6,
            offset: const Offset(0, 2),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // User info row
          _buildUserInfoRow(context, theme),

          const SizedBox(height: AppConstants.padM),

          // Rating stars
          RatingStars.display(
            rating: review.rating,
            size: 18,
          ),

          const SizedBox(height: AppConstants.padS),

          // Review comment
          if (review.comment.isNotEmpty) ...[
            Text(
              review.comment,
              style: theme.textTheme.bodyMedium?.copyWith(
                height: 1.5,
              ),
            ),
            const SizedBox(height: AppConstants.padS),
          ],

          // Timestamp and edited indicator
          _buildTimestampRow(context, theme),

          // Owner reply section
          if (review.hasOwnerReply) ...[
            const SizedBox(height: AppConstants.padM),
            _buildOwnerReply(context, theme),
          ],

          // Action buttons (edit/delete or reply)
          if (isReviewAuthor || isOwner || !review.hasOwnerReply) ...[
            const SizedBox(height: AppConstants.padS),
            _buildActionButtons(context, theme),
          ],
        ],
      ),
    );
  }

  //============================================================================
  // USER INFO ROW
  //============================================================================

  Widget _buildUserInfoRow(BuildContext context, ThemeData theme) {
    return Row(
      children: [
        // Profile picture
        CircleAvatar(
          radius: 20,
          backgroundColor: theme.colorScheme.primary.withOpacity(0.1),
          backgroundImage: review.userProfilePicture != null
              ? CachedNetworkImageProvider(review.userProfilePicture!)
              : null,
          child: review.userProfilePicture == null
              ? Text(
            review.userName[0].toUpperCase(),
            style: theme.textTheme.titleMedium?.copyWith(
              color: theme.colorScheme.primary,
              fontWeight: FontWeight.bold,
            ),
          )
              : null,
        ),

        const SizedBox(width: AppConstants.padS),

        // Name and verified badge
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Flexible(
                    child: Text(
                      review.userName,
                      style: theme.textTheme.titleSmall?.copyWith(
                        fontWeight: FontWeight.bold,
                      ),
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                  if (review.isVerifiedBooking) ...[
                    const SizedBox(width: 6),
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 6,
                        vertical: 2,
                      ),
                      decoration: BoxDecoration(
                        color: Colors.green.withOpacity(0.1),
                        borderRadius: BorderRadius.circular(4),
                        border: Border.all(
                          color: Colors.green.withOpacity(0.3),
                          width: 1,
                        ),
                      ),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Icon(
                            Icons.verified_rounded,
                            size: 12,
                            color: Colors.green[700],
                          ),
                          const SizedBox(width: 2),
                          Text(
                            'Verified',
                            style: theme.textTheme.labelSmall?.copyWith(
                              color: Colors.green[700],
                              fontWeight: FontWeight.bold,
                              fontSize: 10,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ],
              ),
            ],
          ),
        ),

        // More menu
        if (isReviewAuthor)
          PopupMenuButton<String>(
            icon: const Icon(Icons.more_vert_rounded, size: 20),
            onSelected: (value) {
              if (value == 'edit' && onEdit != null) {
                onEdit!();
              } else if (value == 'delete' && onDelete != null) {
                onDelete!();
              }
            },
            itemBuilder: (context) => [
              const PopupMenuItem(
                value: 'edit',
                child: Row(
                  children: [
                    Icon(Icons.edit_outlined, size: 18),
                    SizedBox(width: 8),
                    Text('Edit Review'),
                  ],
                ),
              ),
              const PopupMenuItem(
                value: 'delete',
                child: Row(
                  children: [
                    Icon(Icons.delete_outline, size: 18, color: Colors.red),
                    SizedBox(width: 8),
                    Text('Delete Review', style: TextStyle(color: Colors.red)),
                  ],
                ),
              ),
            ],
          ),
      ],
    );
  }

  //============================================================================
  // TIMESTAMP ROW
  //============================================================================

  Widget _buildTimestampRow(BuildContext context, ThemeData theme) {
    return Row(
      children: [
        Icon(
          CupertinoIcons.clock,
          size: 12,
          color: theme.colorScheme.onSurfaceVariant,
        ),
        const SizedBox(width: 4),
        Text(
          timeago.format(review.createdAt),
          style: theme.textTheme.bodySmall?.copyWith(
            color: theme.colorScheme.onSurfaceVariant,
          ),
        ),
        if (review.isEdited) ...[
          const SizedBox(width: 8),
          Text(
            '(edited)',
            style: theme.textTheme.bodySmall?.copyWith(
              color: theme.colorScheme.onSurfaceVariant.withOpacity(0.7),
              fontStyle: FontStyle.italic,
            ),
          ),
        ],
      ],
    );
  }

  //============================================================================
  // OWNER REPLY
  //============================================================================

  Widget _buildOwnerReply(BuildContext context, ThemeData theme) {
    return Container(
      padding: const EdgeInsets.all(AppConstants.padM),
      decoration: BoxDecoration(
        color: theme.colorScheme.primary.withOpacity(0.05),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
          color: theme.colorScheme.primary.withOpacity(0.1),
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(
                Icons.store_rounded,
                size: 16,
                color: theme.colorScheme.primary,
              ),
              const SizedBox(width: 6),
              Text(
                'Response from Owner',
                style: theme.textTheme.labelMedium?.copyWith(
                  color: theme.colorScheme.primary,
                  fontWeight: FontWeight.bold,
                ),
              ),
              const Spacer(),
              if (isOwner && onDeleteReply != null)
                IconButton(
                  icon: const Icon(Icons.close, size: 16),
                  onPressed: onDeleteReply,
                  padding: EdgeInsets.zero,
                  constraints: const BoxConstraints(),
                  visualDensity: VisualDensity.compact,
                ),
            ],
          ),
          const SizedBox(height: 8),
          Text(
            review.ownerReply!,
            style: theme.textTheme.bodyMedium?.copyWith(
              height: 1.5,
            ),
          ),
          if (review.ownerRepliedAt != null) ...[
            const SizedBox(height: 8),
            Text(
              timeago.format(review.ownerRepliedAt!),
              style: theme.textTheme.bodySmall?.copyWith(
                color: theme.colorScheme.onSurfaceVariant,
              ),
            ),
          ],
        ],
      ),
    );
  }

  //============================================================================
  // ACTION BUTTONS
  //============================================================================

  Widget _buildActionButtons(BuildContext context, ThemeData theme) {
    // Owner can reply if they haven't yet
    if (isOwner && !review.hasOwnerReply && onReply != null) {
      return TextButton.icon(
        onPressed: onReply,
        icon: const Icon(Icons.reply_rounded, size: 18),
        label: const Text('Reply'),
        style: TextButton.styleFrom(
          padding: EdgeInsets.zero,
          tapTargetSize: MaterialTapTargetSize.shrinkWrap,
        ),
      );
    }

    return const SizedBox.shrink();
  }
}

import 'dart:async';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:pendeza/app/utils/logger.dart';
import '../../../../app/services/payment_service.dart';
import '../../../../app/services/service_locator.dart';
import 'payment_event.dart';
import 'payment_state.dart';

/// 🔥 REFACTORED PaymentBloc - Reactive & Webhook-Based
///
/// **Benefits:**
/// ✅ No polling = better battery life
/// ✅ Real-time updates via Firestore
/// ✅ Works even after app restart
/// ✅ Simpler code
/// ✅ Webhook handles all backend logic
class PaymentBloc extends Bloc<PaymentEvent, PaymentState> {
  final PaymentService _paymentService;
  final FirebaseFirestore _firestore = FirebaseFirestore.instance;

  // Stream subscriptions for listening to status changes
  StreamSubscription<DocumentSnapshot>? _transactionSubscription;
  StreamSubscription<DocumentSnapshot>? _appointmentSubscription;

  PaymentBloc()
      : _paymentService = sl<PaymentService>(),
        super(PaymentInitial()) {
    on<InitiatePayment>(_onInitiatePayment);
    on<WatchPaymentStatus>(_onWatchPaymentStatus);
    on<_PaymentStatusChanged>(_onPaymentStatusChanged);
    on<CancelPaymentWatch>(_onCancelPaymentWatch);
    on<ResetPaymentState>(_onResetPaymentState);
  }

  /// Initiate payment with PalmPesa
  Future<void> _onInitiatePayment(
      InitiatePayment event,
      Emitter<PaymentState> emit,
      ) async {
    try {
      log.i('PaymentBloc: Initiating payment for appointment ${event.appointmentId}');
      emit(PaymentLoading());

      // 🔥 FIX: Pass userId so transaction document can be created with proper permissions
      final result = await _paymentService.initiatePayment(
        phoneNumber: event.phoneNumber,
        amount: event.amount,
        orderId: event.appointmentId,
        name: event.customerName,
        email: event.customerEmail,
        userId: event.userId, // 🔥 CRITICAL: Pass userId for Firestore rules
      );

      log.d('PaymentBloc: Payment result: $result');

      if (result['success'] == true) {
        log.i('✅ PaymentBloc: Payment initiated successfully');

        final transactionId = result['transactionId'];

        // Show user feedback
        emit(const PaymentInitiated(
          "Payment request sent! Complete payment on your phone.",
        ));

        // Start listening to BOTH transaction document AND appointment
        log.i('👂 Starting to watch payment status');
        add(WatchPaymentStatus(
          transactionId: transactionId,
          appointmentId: event.appointmentId,
        ));
      } else {
        final errorMsg = result['message'] ?? 'Payment initiation failed';
        log.e('❌ PaymentBloc: Payment failed - $errorMsg');
        emit(PaymentError(errorMsg));
      }
    } catch (e, stackTrace) {
      log.e('PaymentBloc: Exception during payment', error: e, stackTrace: stackTrace);
      emit(PaymentError('Failed to initiate payment: ${e.toString()}'));
    }
  }

  /// Watch transaction AND appointment documents for status changes (REACTIVE)
  ///
  /// Uses DUAL LISTENER strategy:
  /// 1. Transaction listener - catches webhook updates to transaction doc
  /// 2. Appointment listener - catches updates to appointment status
  Future<void> _onWatchPaymentStatus(
      WatchPaymentStatus event,
      Emitter<PaymentState> emit,
      ) async {
    try {
      log.i('👂 Setting up payment status listeners');
      log.i('   Transaction ID: ${event.transactionId}');
      log.i('   Appointment ID: ${event.appointmentId}');

      // Cancel any existing subscriptions
      await _transactionSubscription?.cancel();
      await _appointmentSubscription?.cancel();

      // ========================================
      // LISTENER 1: Transaction Document
      // ========================================
      if (event.transactionId != null && event.transactionId!.isNotEmpty) {
        log.i('👂 Setting up transaction listener: ${event.transactionId}');

        _transactionSubscription = _firestore
            .collection('transactions')
            .doc(event.transactionId)
            .snapshots()
            .listen(
              (snapshot) {
            if (!snapshot.exists) {
              log.w('⚠️ Transaction document does not exist yet: ${event.transactionId}');
              return;
            }

            final data = snapshot.data();
            if (data == null) return;

            final status = data['status']?.toString().toLowerCase() ?? 'pending';
            log.d('📡 Transaction status update: $status');

            // Only emit for terminal states
            if (status == 'completed' || status == 'failed') {
              add(_PaymentStatusChanged(
                status: status,
                transactionId: event.transactionId!,
                appointmentId: event.appointmentId,
                data: data,
                source: 'transaction',
              ));
            }
          },
          onError: (error) {
            log.e('❌ Error listening to transaction status', error: error);
          },
        );
      }

      // ========================================
      // LISTENER 2: Appointment Document (ALWAYS)
      // ========================================
      log.i('👂 Setting up appointment listener: ${event.appointmentId}');

      _appointmentSubscription = _firestore
          .collection('appointments')
          .doc(event.appointmentId)
          .snapshots()
          .listen(
            (snapshot) {
          if (!snapshot.exists) {
            log.w('⚠️ Appointment document does not exist: ${event.appointmentId}');
            return;
          }

          final data = snapshot.data();
          if (data == null) return;

          final status = data['status']?.toString() ?? 'Pending Payment';
          log.d('📡 Appointment status update: $status');

          // Map appointment status to payment status
          String paymentStatus;
          if (status == 'Confirmed' || status == 'confirmed') {
            paymentStatus = 'completed';
          } else if (status == 'Cancelled' || status == 'cancelled' || status == 'Failed') {
            paymentStatus = 'failed';
          } else {
            paymentStatus = 'pending';
          }

          add(_PaymentStatusChanged(
            status: paymentStatus,
            transactionId: event.transactionId ?? '',
            appointmentId: event.appointmentId,
            data: data,
            source: 'appointment',
          ));
        },
        onError: (error) {
          log.e('❌ Error listening to appointment status', error: error);
        },
      );

      log.i('✅ Payment status listeners set up successfully');
    } catch (e, stackTrace) {
      log.e('❌ Error setting up status listeners', error: e, stackTrace: stackTrace);
      emit(PaymentError('Failed to track payment status: ${e.toString()}'));
    }
  }

  /// Handle status changes from Firestore listeners
  Future<void> _onPaymentStatusChanged(
      _PaymentStatusChanged event,
      Emitter<PaymentState> emit,
      ) async {
    log.i('🔄 Processing status change from ${event.source}: ${event.status}');

    switch (event.status) {
      case 'completed':
        log.i('✅ Payment COMPLETED! (from ${event.source})');
        await _cancelSubscriptions();
        emit(PaymentSuccess(event.appointmentId));
        break;

      case 'failed':
        log.w('❌ Payment FAILED (from ${event.source})');
        await _cancelSubscriptions();
        final errorMsg = event.data['errorMessage'] ??
            event.data['failureReason'] ??
            'Payment failed';
        emit(PaymentError(errorMsg));
        break;

      case 'processing':
        log.i('⏳ Payment is being processed...');
        emit(const PaymentInitiated(
          "Processing payment... This may take a moment.",
        ));
        break;

      case 'pending':
        log.d('⏳ Payment still pending...');
        break;

      case 'error':
        log.e('❌ Payment tracking error');
        await _cancelSubscriptions();
        emit(const PaymentError(
          'Error tracking payment. Please check your booking status.',
        ));
        break;

      default:
        log.w('⚠️ Unknown payment status: ${event.status}');
    }
  }

  /// Cancel the status listeners
  Future<void> _onCancelPaymentWatch(
      CancelPaymentWatch event,
      Emitter<PaymentState> emit,
      ) async {
    log.i('🛑 Cancelling payment status listeners');
    await _cancelSubscriptions();
  }

  /// Reset payment state
  Future<void> _onResetPaymentState(
      ResetPaymentState event,
      Emitter<PaymentState> emit,
      ) async {
    log.i('🔄 Resetting payment state');
    await _cancelSubscriptions();
    emit(PaymentInitial());
  }

  Future<void> _cancelSubscriptions() async {
    await _transactionSubscription?.cancel();
    await _appointmentSubscription?.cancel();
    _transactionSubscription = null;
    _appointmentSubscription = null;
  }

  @override
  Future<void> close() {
    _cancelSubscriptions();
    return super.close();
  }
}

