    this.isDisabled = false,
    this.badge,
    this.badgeColor,
    this.customSubtitle,
    this.onTap,
  });

  IconData get _icon {
    switch (method) {
      case PaymentMethod.wallet:
        return Icons.account_balance_wallet;
      case PaymentMethod.ussdPush:
