                style: IconButton.styleFrom(
                  backgroundColor: Colors.black54,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildAudienceSelector(ThemeData theme, bool isDark) {
    return Wrap(
      spacing: 8,
      runSpacing: 8,
      children: [
        _buildAudienceChip(
          'all',
          'All Users',
          CupertinoIcons.globe,
          AppColors.primary,
          theme,
          isDark,
        ),
        _buildAudienceChip(
          'clients',
          'Clients Only',
          CupertinoIcons.person_2_fill,
          AppColors.success,
          theme,
          isDark,
        ),
        _buildAudienceChip(
          'owners',
          'Owners Only',
          CupertinoIcons.building_2_fill,
          AppColors.accent2,
          theme,
          isDark,
        ),
      ],
    );
  }

  Widget _buildAudienceChip(
      String value,
      String label,
      IconData icon,
      Color color,
      ThemeData theme,
      bool isDark,
      ) {
    final isSelected = _targetAudience == value;

    return FilterChip(
      selected: isSelected,
      label: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(icon, size: 16, color: isSelected ? color : null),
          const SizedBox(width: 8),
          Text(label),
        ],
      ),
      onSelected: (selected) {
        if (selected) {
          setState(() => _targetAudience = value);
        }
      },
      selectedColor: color.withOpacity(0.2),
      checkmarkColor: color,
      backgroundColor: isDark
          ? AppColors.darkSurface
          : Colors.grey.shade100,
    );
  }

  Widget _buildExpandableSection({
    required String title,
    required ThemeData theme,
    required bool isDark,
    required List<Widget> children,
  }) {
    return ExpansionTile(
      title: Text(
        title,
        style: AppTextStyles.bodyMedium.copyWith(
          fontWeight: FontWeight.bold,
          color: isDark ? Colors.white : AppColors.textPrimary,
        ),
      ),
      children: [
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: AppConstants.padM),
          child: Column(children: children),
        ),
      ],
    );
  }

  Widget _buildPreviewSection(ThemeData theme, bool isDark) {
    return Container(
      decoration: BoxDecoration(
        color: isDark ? AppColors.darkSurface : Colors.grey.shade100,
        border: Border(
          left: BorderSide(
            color: isDark ? AppColors.darkBorder : AppColors.border,
          ),
        ),
      ),
      child: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(AppConstants.padM),
            child: Text(
              'Preview',
              style: AppTextStyles.bodyMedium.copyWith(
                fontWeight: FontWeight.bold,
                color: isDark ? Colors.white : AppColors.textPrimary,
              ),
            ),
          ),
          Expanded(
            child: Center(
              child: NotificationPreviewWidget(
                title: _titleController.text.isNotEmpty
                    ? _titleController.text
                    : 'Notification Title',
                body: _bodyController.text.isNotEmpty
                    ? _bodyController.text
                    : 'Your message will appear here',
                imageUrl: _image?.path,
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildFooter(ThemeData theme, bool isDark) {
    return Container(
      padding: const EdgeInsets.all(AppConstants.padL),
      decoration: BoxDecoration(
        color: isDark
            ? AppColors.darkSurface
            : Colors.grey.shade50,
        borderRadius: const BorderRadius.only(
          bottomLeft: Radius.circular(24),
          bottomRight: Radius.circular(24),
        ),
        border: Border(
          top: BorderSide(
            color: isDark ? AppColors.darkBorder : AppColors.border,
          ),
        ),
      ),
      child: Row(
        children: [
          TextButton.icon(
            onPressed: () {
              setState(() => _showPreview = !_showPreview);
            },
            icon: Icon(
              _showPreview
                  ? CupertinoIcons.eye_slash
                  : CupertinoIcons.eye,
            ),
            label: Text(_showPreview ? 'Hide Preview' : 'Show Preview'),
          ),
          const Spacer(),
          TextButton(
            onPressed: () => Navigator.of(context).pop(),
            child: const Text('Cancel'),
          ),
          const SizedBox(width: AppConstants.padS),
          PrimaryGradientButton(
            onPressed: _sendNotification,
            text: 'Send Notification',
            isLoading: _isLoading,
          ),
        ],
      ),
    );
  }
}

