/// Data source for the PaginatedDataTable2
class UserDataTableSource extends DataTableSource {
  final List<UserModel> users;
  final AdminBloc adminBloc;
  final BuildContext context;

  UserDataTableSource({
    required this.users,
    required this.adminBloc,
    required this.context,
  });

  @override
  DataRow? getRow(int index) {
    if (index >= users.length) return null;
    final user = users[index];

    return DataRow2.byIndex(
      index: index,
      onSelectChanged: (isSelected) {
        if (isSelected != null && isSelected) {
          _showRoleDialog(context, user);
        }
      },
      cells: [
        // Name Cell
        DataCell(
          Row(
            children: [
              ProfileAvatar(
                imageUrl: user.profilePictureUrl,
                fullName: user.fullName,
                radius: 20,
              ),
              const SizedBox(width: AppConstants.padM),
              Expanded(
                child: Text(
                  user.fullName,
                  overflow: TextOverflow.ellipsis,
                ),
              ),
            ],
          ),
        ),
        // Contact Cell
        DataCell(
          Text(user.email.isEmpty ? user.phoneNumber ?? 'N/A' : user.email),
        ),
        // Role Cell
        DataCell(_buildRoleChip(user.role)),
      ],
    );
  }

  void _showRoleDialog(BuildContext context, UserModel user) {
    showDialog(
      context: context,
      builder: (dialogContext) => AdminRoleDialog(
        user: user,
        adminBloc: adminBloc,
      ),
    );
  }

  Widget _buildRoleChip(String? role) {
    Color color;
    switch (role) {
      case 'admin':
        color = AppColors.error;
        break;
      case 'owner':
        color = AppColors.accent2;
        break;
      case 'client':
        color = AppColors.success;
        break;
      default:
        color = AppColors.textSecondary;
    }
    return Chip(
      label: Text(
        role ?? 'N/A',
        style: AppTextStyles.bodySmall.copyWith(
          color: color,
          fontWeight: FontWeight.bold,
        ),
      ),
      backgroundColor: color.withOpacity(0.1),
      side: BorderSide.none,
      padding: const EdgeInsets.symmetric(horizontal: 8),
    );
  }

  @override
  bool get isRowCountApproximate => false;

  @override
  int get rowCount => users.length;

  @override
  int get selectedRowCount => 0;
}

