/// Full-screen video viewer with TikTok-style vertical swiping
///
/// Features:
/// - Vertical swipe to navigate between videos
/// - Auto-play and loop
/// - Book Now button → Service Selection
/// - Salon info overlay
/// - Tap to pause/play
class VideoViewerScreen extends StatefulWidget {
  final List<SalonVideoModel> videos;
  final int initialIndex;

  const VideoViewerScreen({
    super.key,
    required this.videos,
    this.initialIndex = 0,
  });

  @override
  State<VideoViewerScreen> createState() => _VideoViewerScreenState();
}

class _VideoViewerScreenState extends State<VideoViewerScreen> {
  late PageController _pageController;
  late int _currentIndex;
  final Map<int, VideoPlayerController> _controllers = {};

  @override
  void initState() {
    super.initState();
    _currentIndex = widget.initialIndex;
    _pageController = PageController(initialPage: _currentIndex);

    // Set to full screen / immersive mode
    SystemChrome.setEnabledSystemUIMode(SystemUiMode.immersiveSticky);
    SystemChrome.setPreferredOrientations([DeviceOrientation.portraitUp]);

    // Initialize first video
    _initializeVideo(_currentIndex);

    // Pre-load adjacent videos
    if (_currentIndex > 0) _initializeVideo(_currentIndex - 1);
    if (_currentIndex < widget.videos.length - 1) _initializeVideo(_currentIndex + 1);
  }

  @override
  void dispose() {
    // Restore system UI
    SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge);

    // Dispose all controllers
    for (final controller in _controllers.values) {
      controller.dispose();
    }
    _pageController.dispose();
    super.dispose();
  }

  Future<void> _initializeVideo(int index) async {
    if (_controllers.containsKey(index)) return;
    if (index < 0 || index >= widget.videos.length) return;

    final video = widget.videos[index];
    final controller = VideoPlayerController.networkUrl(Uri.parse(video.videoUrl));
    _controllers[index] = controller;

    await controller.initialize();
    controller.setLooping(true);

    // Auto-play if it's the current video
    if (index == _currentIndex && mounted) {
      controller.play();
      setState(() {});
    }
  }

  void _onPageChanged(int index) {
    // Pause old video
    _controllers[_currentIndex]?.pause();

    // Update index
    _currentIndex = index;

    // Play new video
    _controllers[_currentIndex]?.play();

    // Pre-load adjacent videos
    if (index > 0) _initializeVideo(index - 1);
    if (index < widget.videos.length - 1) _initializeVideo(index + 1);

    // Clean up far away videos to save memory
    _cleanupDistantControllers(index);

    setState(() {});
  }

  void _cleanupDistantControllers(int currentIndex) {
    final keysToRemove = <int>[];
    for (final key in _controllers.keys) {
      if ((key - currentIndex).abs() > 2) {
        keysToRemove.add(key);
      }
    }
    for (final key in keysToRemove) {
      _controllers[key]?.dispose();
      _controllers.remove(key);
    }
  }

  void _togglePlayPause() {
    final controller = _controllers[_currentIndex];
    if (controller == null) return;

    if (controller.value.isPlaying) {
      controller.pause();
    } else {
      controller.play();
    }
    setState(() {});
  }

  void _navigateToBooking(SalonVideoModel video) {
    // Close video viewer first
    Navigator.of(context).pop();

    // Navigate to salon detail screen (which resolves salon data and shows services)
    context.push(
      AppRoutes.salonDetail.replaceFirst(':salonId', video.salonId),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.black,
      body: Stack(
        children: [
          // Video PageView
          PageView.builder(
            controller: _pageController,
            scrollDirection: Axis.vertical,
            onPageChanged: _onPageChanged,
            itemCount: widget.videos.length,
            itemBuilder: (context, index) {
              return _VideoPage(
                video: widget.videos[index],
                controller: _controllers[index],
                onTap: _togglePlayPause,
                onBookNow: () => _navigateToBooking(widget.videos[index]),
              );
            },
          ),

          // Close button
          Positioned(
            top: MediaQuery.of(context).padding.top + 10,
            right: 16,
            child: IconButton(
              onPressed: () => Navigator.of(context).pop(),
              icon: Container(
                padding: const EdgeInsets.all(8),
                decoration: BoxDecoration(
                  color: Colors.black.withOpacity(0.5),
                  shape: BoxShape.circle,
                ),
                child: const Icon(
                  Icons.close,
                  color: Colors.white,
                  size: 24,
                ),
              ),
            ),
          ),

          // Video counter
          Positioned(
            top: MediaQuery.of(context).padding.top + 16,
            left: 16,
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
              decoration: BoxDecoration(
                color: Colors.black.withOpacity(0.5),
                borderRadius: BorderRadius.circular(20),
              ),
              child: Text(
                '${_currentIndex + 1} / ${widget.videos.length}',
                style: const TextStyle(
                  color: Colors.white,
                  fontSize: 14,
                  fontWeight: FontWeight.bold,
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

