/// Enhanced primary button with modern "Aura" effect
class PrimaryGradientButton extends StatefulWidget {
  final VoidCallback? onPressed;
  final String text;
  final IconData? iconData;
  final bool isLoading;
  final double? height;
  final EdgeInsetsGeometry? padding;

  const PrimaryGradientButton({
    super.key,
    required this.onPressed,
    required this.text,
    this.iconData,
    this.isLoading = false,
    this.height,
    this.padding,
  });

  @override
  State<PrimaryGradientButton> createState() => _PrimaryGradientButtonState();
}

class _PrimaryGradientButtonState extends State<PrimaryGradientButton>
    with SingleTickerProviderStateMixin {
  late AnimationController _glowController;
  bool _isPressed = false;

  @override
  void initState() {
    super.initState();
    _glowController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1500),
    )..repeat(reverse: true);
  }

  @override
  void dispose() {
    _glowController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final bool isEnabled = widget.onPressed != null && !widget.isLoading;
    final theme = Theme.of(context);

    return GestureDetector(
      onTapDown: isEnabled ? (_) => setState(() => _isPressed = true) : null,
      onTapUp: isEnabled ? (_) => setState(() => _isPressed = false) : null,
      onTapCancel: isEnabled ? () => setState(() => _isPressed = false) : null,
      child: AnimatedBuilder(
        animation: _glowController,
        builder: (context, child) {
          final glowIntensity = isEnabled ? _glowController.value : 0.0;

          return AnimatedContainer(
            duration: AppConstants.durationFast,
            height: widget.height ?? 50,
            decoration: BoxDecoration(
              gradient: isEnabled
                  ? const LinearGradient(
                colors: [AppColors.primary, AppColors.primaryDark],
                begin: Alignment.topLeft,
                end: Alignment.bottomRight,
              )
                  : LinearGradient(
                colors: [
                  theme.disabledColor.withOpacity(0.3),
                  theme.disabledColor.withOpacity(0.2),
                ],
              ),
              borderRadius: BorderRadius.circular(AppConstants.radiusValM),
              boxShadow: isEnabled
                  ? [
                BoxShadow(
                  color: AppColors.primary.withOpacity(0.3 + (glowIntensity * 0.2)),
                  blurRadius: 12 + (glowIntensity * 8),
                  offset: const Offset(0, 4),
                  spreadRadius: glowIntensity * 2,
                ),
              ]
                  : [],
            ),
            child: Material(
              color: Colors.transparent,
              child: InkWell(
                onTap: isEnabled ? widget.onPressed : null,
                borderRadius: BorderRadius.circular(AppConstants.radiusValM),
                child: AnimatedScale(
                  scale: _isPressed ? 0.96 : 1.0,
                  duration: AppConstants.durationFast,
                  child: Container(
                    padding: widget.padding ??
                        const EdgeInsets.symmetric(
                          vertical: AppConstants.padS,
                          horizontal: AppConstants.padL,
                        ),
                    child: widget.isLoading
                        ? const SizedBox(
                      width: 24,
                      height: 24,
                      child: Center(
                        child: CircularProgressIndicator(
                          color: Colors.white,
                          strokeWidth: 2.5,
                        ),
                      ),
                    )
                        : Row(
                      mainAxisSize: MainAxisSize.min,
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        if (widget.iconData != null) ...[
                          Icon(
                            widget.iconData,
                            color: Colors.white,
                            size: 20,
                          ),
                          const SizedBox(width: AppConstants.padXS),
                        ],
                        Flexible(
                          child: Text(
                            widget.text,
                            textAlign: TextAlign.center,
                            style: AppTextStyles.button.copyWith(
                              color: Colors.white,
                              fontSize: 15,
                              fontWeight: FontWeight.w600,
                              letterSpacing: 0.3,
                            ),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ),
          );
        },
      ),
    );
  }
}

import 'package:cached_network_image/cached_network_image.dart';
import 'package:flutter/material.dart';
import 'loading_indicator.dart';


/// A reusable widget to display a user's profile picture or initials.
///
/// It handles multiple states:
/// 1. Displays a network image using `CachedNetworkImage` for performance.
/// 2. Shows a `ShimmerPlaceholder` while the image is loading.
/// 3. Shows a fallback with the user's initials if the image URL is null or fails to load.
class ProfileAvatar extends StatelessWidget {
  /// The URL of the profile image to display.
  final String? imageUrl;

  /// The radius of the avatar circle. Defaults to 24.0.
  final double radius;

  /// The full name of the user, used to generate initials for the fallback.
  final String? fullName;

  /// The font size for the initials. It scales with the radius.
  final double? fontSize;

  const ProfileAvatar({
    super.key,
    this.imageUrl,
    this.radius = 24.0,
    this.fullName,
    this.fontSize,
  });

  /// Generates initials from a full name.
  /// Example: "John Doe" -> "JD"
  String _getInitials() {
    if (fullName == null || fullName!.trim().isEmpty) {
      return '?';
    }
    final names = fullName!.trim().split(' ');
    if (names.length > 1) {
      return names[0][0].toUpperCase() + names.last[0].toUpperCase();
    } else if (names.isNotEmpty) {
      return names[0][0].toUpperCase();
    }
    return '?';
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final initials = _getInitials();

    // The main widget is a CircleAvatar for a circular shape.
    return CircleAvatar(
      radius: radius,
      backgroundColor: theme.colorScheme.primary.withOpacity(0.1),
      // The child of the CircleAvatar is a ClipOval to ensure
      // all children (image, fallback) are perfectly circular.
      child: ClipOval(
        child: CachedNetworkImage(
          imageUrl: imageUrl ?? '', // Use empty string to trigger errorBuilder if null
          fit: BoxFit.cover,
          width: radius * 2,
          height: radius * 2,
          // Placeholder to show while the image is loading from the network.
          placeholder: (context, url) => ShimmerPlaceholder.circle(size: radius * 2),
          // Widget to show if the imageUrl is null or fails to load.
          errorWidget: (context, url, error) => Center(
            child: Text(
              initials,
              style: theme.textTheme.titleLarge?.copyWith(
                color: theme.colorScheme.primary,
                fontWeight: FontWeight.bold,
                fontSize: fontSize ?? radius * 0.8, // Font size scales with avatar size
              ),
            ),
          ),
        ),
      ),
    );
  }
}

