class _SalonCardState extends State<SalonCard> with SingleTickerProviderStateMixin {
  late AnimationController _scaleController;
  bool _isPressed = false;

  @override
  void initState() {
    super.initState();
    _scaleController = AnimationController(
      vsync: this,
      duration: AppConstants.durationFast,
    );
  }

  @override
  void dispose() {
    _scaleController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final isDark = theme.brightness == Brightness.dark;

    return GestureDetector(
      onTapDown: (_) {
        setState(() => _isPressed = true);
        _scaleController.forward();
      },
      onTapUp: (_) {
        setState(() => _isPressed = false);
        _scaleController.reverse();
        if (widget.onTap != null) widget.onTap!();
      },
      onTapCancel: () {
        setState(() => _isPressed = false);
        _scaleController.reverse();
      },
      child: AnimatedBuilder(
        animation: _scaleController,
        builder: (context, child) => Transform.scale(
          scale: 1.0 - (_scaleController.value * 0.03),
          child: child,
        ),
        child: Container(
          width: widget.width,
          height: widget.height,
          decoration: BoxDecoration(
            color: theme.colorScheme.surface,
            borderRadius: BorderRadius.circular(AppConstants.radiusValXL),
            boxShadow: _isPressed
                ? []
                : [
              BoxShadow(
                color: isDark ? Colors.black54 : Colors.black.withOpacity(0.08),
                blurRadius: 15,
                offset: const Offset(0, 8),
              ),
            ],
          ),
          clipBehavior: Clip.antiAlias,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              _buildImageSection(theme),
              Expanded(child: _buildInfoSection(theme)),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildImageSection(ThemeData theme) {
    return Stack(
      children: [
        AspectRatio(
          aspectRatio: 1.25,
          child: CachedNetworkImage(
            imageUrl: widget.salon.primaryImage ?? '',
            fit: BoxFit.cover,
            placeholder: (context, url) => const ShimmerPlaceholder.rectangular(height: double.infinity),
            errorWidget: (context, url, error) => Container(
              color: theme.colorScheme.surfaceContainerHighest,
              child: const Icon(CupertinoIcons.scissors, size: 32),
            ),
          ),
        ),
        Positioned(
          top: 8,
          right: 8,
          child: Container(
            padding: const EdgeInsets.all(4),
            decoration: BoxDecoration(
              color: Colors.white.withOpacity(0.7),
              shape: BoxShape.circle,
            ),
            child: FavoriteIconButton(salonId: widget.salon.id, size: 18),
          ),
        ),
      ],
    );
  }

  Widget _buildInfoSection(ThemeData theme) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 8.0, vertical: 6.0),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          // Top section - flexible to shrink if needed
          Flexible(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                // Category label
                if (widget.salon.serviceCategories.isNotEmpty)
                  Text(
                    widget.salon.serviceCategories.first.toUpperCase(),
                    style: theme.textTheme.labelSmall?.copyWith(
                      color: theme.colorScheme.primary,
                      fontWeight: FontWeight.bold,
                      fontSize: 8,
                    ),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                // Title row
                Row(
                  children: [
                    Expanded(
                      child: Text(
                        widget.salon.salonName,
                        style: theme.textTheme.titleSmall?.copyWith(
                          fontWeight: FontWeight.bold,
                          fontSize: 12,
                        ),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                    const SizedBox(width: 4),
                    Icon(
                      CupertinoIcons.checkmark_seal_fill,
                      color: theme.colorScheme.primary,
                      size: 12,
                    ),
                  ],
                ),
                // Location row
                Row(
                  children: [
                    const Icon(CupertinoIcons.location_solid, size: 10, color: Colors.grey),
                    const SizedBox(width: 4),
                    Expanded(
                      child: Text(
                        widget.salon.district ?? widget.salon.address,
                        style: theme.textTheme.bodySmall?.copyWith(fontSize: 9),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),
          // Bottom row - rating and price level (fixed height)
          Row(
            children: [
              const Icon(CupertinoIcons.star_fill, color: Color(0xFFFFB800), size: 12),
              const SizedBox(width: 4),
              Text(
                "4.8",
                style: theme.textTheme.bodySmall?.copyWith(
                  fontWeight: FontWeight.bold,
                  fontSize: 10,
                ),
              ),
              const Spacer(),
              Text(
                '\$\$\$',
                style: theme.textTheme.labelSmall?.copyWith(fontSize: 9),
              ),
            ],
          ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import '../../app/config/theme/app_constants.dart';
import '../../app/config/theme/app_text_styles.dart';

/// A custom secondary button for the application.
///
/// This button has a subtle, outlined style and is intended for actions
/// that are less important than the primary action on a screen, such as
/// "Cancel", "Go Back", or "View Details".
class SecondaryButton extends StatelessWidget {
  /// The callback that is called when the button is tapped.
  final VoidCallback? onPressed;

  /// The text to display inside the button.
  final String text;

  /// An optional icon to display to the left of the text.
  final IconData? iconData;

  const SecondaryButton({
    super.key,
    required this.onPressed,
    required this.text,
    this.iconData,
  });

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return OutlinedButton(
      onPressed: onPressed,
      style: OutlinedButton.styleFrom(
        padding: const EdgeInsets.symmetric(
          vertical: AppConstants.padM,
          horizontal: AppConstants.padL,
        ),
        // Use the primary color for the border and text
        foregroundColor: theme.colorScheme.primary,
        side: BorderSide(
          color: theme.colorScheme.primary,
          width: 1.5,
        ),
        shape: RoundedRectangleBorder(
          borderRadius: AppConstants.radiusM,
        ),
      ),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          if (iconData != null) ...[
            Icon(
              iconData,
              size: AppConstants.iconSizeM,
            ),
            const SizedBox(width: AppConstants.padXS),
          ],
          Text(
            text,
            // Use the button text style but with the primary color
            style: AppTextStyles.button.copyWith(
                color: theme.colorScheme.primary
            ),
          ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import '../../app/config/theme/app_constants.dart';
import '../../app/config/theme/app_text_styles.dart';

/// A custom, reusable text form field for the entire application.
///
/// It standardizes the look and feel of all input fields, using the
/// pre-defined InputDecorationTheme from AppTheme. It also provides
/// a consistent way to handle validation and input control.
class CustomTextFormField extends StatelessWidget {
  final TextEditingController? controller;
  final String labelText;
  final String? hintText;
  final IconData? prefixIcon;
  final Widget? suffixIcon;
  final String? Function(String?)? validator;
  final TextInputType? keyboardType;
  final bool obscureText;
  final TextInputAction? textInputAction;
  final List<TextInputFormatter>? inputFormatters;
  final bool? enabled;
  final int? maxLines;
  // ✅ FIX: Added the onChanged parameter
  final ValueChanged<String>? onChanged;

  const CustomTextFormField({
    super.key,
    this.controller,
    required this.labelText,
    this.hintText,
    this.prefixIcon,
    this.suffixIcon,
    this.validator,
    this.keyboardType,
    this.obscureText = false,
    this.textInputAction,
    this.inputFormatters,
    this.enabled,
    this.maxLines = 1,
    // ✅ FIX: Added onChanged to the constructor
    this.onChanged,
  });

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          labelText,
          style: AppTextStyles.caption.copyWith(
            color: theme.textTheme.bodySmall?.color,
          ),
        ),
        const SizedBox(height: AppConstants.padXS),
        TextFormField(
          controller: controller,
          validator: validator,
          keyboardType: maxLines != null && maxLines! > 1
              ? TextInputType.multiline
              : keyboardType,
          obscureText: obscureText,
          textInputAction: textInputAction,
          inputFormatters: inputFormatters,
          enabled: enabled,
          style: theme.textTheme.bodyMedium,
          maxLines: maxLines,
          // ✅ FIX: Passed onChanged to the underlying TextFormField
          onChanged: onChanged,
          decoration: InputDecoration(
            hintText: hintText,
            prefixIcon: prefixIcon != null
                ? Icon(
              prefixIcon,
              size: AppConstants.iconSizeM,
              color: theme.colorScheme.onSurface.withOpacity(0.6),
            )
                : null,
            suffixIcon: suffixIcon,
          ),
        ),
      ],
    );
  }
}
